window.READER_DATA={"title": "Sharh Fahm Mahmud", "slug": "sharh-fahm-mahmud", "pages": [{"n": 1, "paras": ["في فقه الإصلاح والتجديد عند الإمام حسن البنا", "فهم أصول الإسلام في رسالة التعاليم", "د. علي عبد الحليم محمود من علماء الأزهر"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0001.png"}, {"n": 2, "paras": ["حقوق الطبع محفوظة الطبعة الأولى", "١٤١٤ ه - ١٩٩٤ م", "دار التوزيع والنشر الإسلامية", "٨ ميدان السيدة زينب ت : ٣٩١١٩٩١ ص . ب : ١٦٣٦"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0002.png"}, {"n": 3, "paras": ["بسم الله الرحمن الرحيم", "إهداء", "إلى المؤمنين الذين يعملون الصالحات وإلى الذين هداهم الله إلى الحق وإلى طريق مستقيم ، وإلى شباب الصحوة الإسلامية وشيوخها في العالم الإسلامي . وإلى كل من ينادون بأن الإسلام هو الحل لكل مشكلات الإنسان . إليهم أقدم: خلاصة فكر الإمام حسن البنا في الإصلاح والتجديد الإسلامي وتفسير مبدأ « الإسلام هو الحل » في رسالته الجليلة القدر « رسالة التعاليم » أو فقه أركان الإصلاح الإسلامي"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0003.png"}, {"n": 4, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0004.png"}, {"n": 5, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0005.png"}, {"n": 6, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0006.png"}, {"n": 7, "paras": ["الحمد لله رب العالمين الرحمن الرحيم مالك يوم الدين ، والصلاة والسلام على محمد المبعوث رحمة للعالمين ، وعلى آله وصحبه والسائرين على دربه إلى يوم الدين . وبعد : فإن المسلمين اليوم بل منذ بداية القرن الذي نعيش فيه ، يمارسون حياتهم في تشرذم وافتراق كلمة ، وذهاب ريح ، بل ضياع وقلق واضطراب ، وكل هذا قد يفرضه عليهم عدو حاقد متحكم حينا ، وقد يسعون هم إليه لبعدهم عن منهج الإسلام حينا آخر ، فيعيشون بذلك تراجعا حضاريا لا يليق بهم بوصفهم منتسبين إلى أكمل الأديان وأتمها ، الدين الذي أقام أرقى حضارة إنسانية من حيث شمولها وقدرتها على تحقيق تكريم الإنسان والمحافظة على حقوقه ، وأقداره على ممارسة حياة إنسانية كريمة في المعاش والمعاد ، شهد بذلك القاصي والداني من المسلمين ، ومن المنصفين من غير المسلمين . أسباب تفرق المسلمين وتراجعهم الحضاري اليوم ولابد من إشارة خاطفة إلى أسباب التشرذم والفرقة والضياع ، بل التراجع الحضاري لكي يفيق من كان غافلا ، ويعرف من كان من غير العارفين . إن هذه الأسباب - وهي كثيرة كثرة مذهلة للمتأمل - ترجع إلى نوعين كبيرين : أما أولهما : فأسباب خارجية عن العالم الإسلامي . وأما الثاني : فأسباب من داخل العالم الإسلامي من المسلمين أنفسهم . وقد يكون الأول مفضيا إلى الثاني ، وقد يكون أثره محدودا فيه .", "* فالأسباب التي أدت إلى تشرذم المسلمين وفرقتهم وفرضت عليهم من الخارج كثيرة نشير منها إلى تحالف دول الغرب - ورثة الصليبيين وحروبهم ضد", "V"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0007.png"}, {"n": 8, "paras": ["الإسلام والمسلمين - من أجل القضاء على الإسلام والمسلمين أو القضاء على وحدة المسلمين وتقدمهم ، أو القضاء على تمسكهم بمنهجهم كتاب الله وسنة رسوله ﷺ .", "وتخالف اليهود - وهم من شرق وغرب وشمال وجنوب - مع الغرب الصليبي ، لضرب الإسلام عدوهم التقليدي ، وضرب المسلمين حتى يضعفوا وتذهب ريحهم ، فيستطيع اليهود في هذا الجو أن يقيموا دولة في أرض فلسطين العربية الإسلامية ، أو يحولوا بين المسلمين وبين الوحدة والتماسك حتى يعيشوا هم على نتائج الفرقة والتعادى .", "وتخالف الغرب الصليبي واليهودية الصهيونية مع ما كان يعرف بالاتحاد السوفيتي وما يضمه من إلحاد شيوعية واشتراكية ، ليصلوا جميعا من وراء هذا التحالف إلى ضرب الإسلام والمسلمين في كل مكان يمكن أن تقوم للمسلمين فيه قائمة ، ومنعهم من اتحاد الكلمة فضلا عن وحدة الصف .", "وتخالف كل هذه القوى ، مع الفساد وانحلال الأخلاق ، وإطلاق العنان لشهوات الإنسان وكل هذا يفد إلى المسلمين من الغرب حينا ومن الشرق حينا ، ومن اليهود في كل حين(١) لكى يغرقوا المسلمين فيما نهاهم الله وحرم عليهم. فيضيعوا ويتبعوا الشهوات فلا تقوم لهم قائمة ، وهذا من أهم أهداف هؤلاء الأعداء متحدين ومتفرقين.", "* والأسباب الداخلية التي أدت إلى تشرذم المسلمين وفرقتهم وذهاب ريحهم كثيرة كذلك نذكر منها ولا نحصيها ، ما يمكن الإشارة إليه فيما يلى :", "ضعف تدين المسلمين وتساهل كثير منهم في التمسك بواجبات الدين وآدابه، وإقبال الناس على مفردات الحضارة الغربية - وهي حضارة مادية تطلق", "(١) انظر : الخطر اليهودى برتوكولات حكماء صهيون : ترجمة محمد خليفة التونسي - دار الكتاب العربي - بيروت دون تاريخ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0008.png"}, {"n": 9, "paras": ["العنان للجانب المادى في الإنسان - وتخليهم عن حضارتهم ومفرداتها، وانبهار كثير من المسلمين بما حققه الغرب من مكاسب مادية على حساب الروح والخلق ، بل على حساب الدين بفصله عن الحياة ، وافتتان بعض المسلمين بما أشاعه الشيوعيون والاشتراكيون من زعمهم أن الناس يعيشون في ظل مبادئهم في فردوس أرضى يعيش فيه شركاء في كل شيء ، ثم جاء الواقع فكذب كل هذه الدعاوى إذ سريعا ما أخذ العالم الشيوعي والاشتراكي في الانهيار. ومن أهم هذه الأسباب الداخلية انحراف بعض أنظمة الحكم أو الحكام في كثير من بلدان العالم الإسلامي ، إذ كثيراً ما غلبت هؤلاء الحكام شهواتهم وعلاقاتهم المشبوهة بقوى الغرب أو الشرق المعادية للإسلام . كل تلك الأسباب المستقرة في داخل العالم الإسلامي وغيرها مما لا تتسع له هذه المقدمة إلى جانب الأسباب الخارجية التي ذكرنا طرفا منها ، هي التي أدت إلى تشرذم المسلمين وفرقتهم وذهاب ريحهم ، وتراجعهم الحضاري في هذا القرن الذي نعيش فيه .", "* وكان من الضروى - ولا يزال - أن يخرج المسلمون من هذه الدائرة التي فرض عليهم أعداؤهم التحرك في داخلها ، حتى لا يظلوا هكذا في نكوص عن الإسلام وتشرذم وتراجع حضارى فيقدموا بذلك أحسن الفرص لأعداءهم أعداء الإسلام ويمكنوا منهم أعداءهم ، ويعينون بذلك على أنفسهم بأنفسهم . المخرج من هذه الفرقة والضياع", "* ولا يستطيع المسلمون أن يستأنفوا مسعاهم الحضاري القائم على الإيمان والعمل الصالح والعدل والإحسان والأمر بالمعروف والنهي عن المنكر ، إلا إذا عادوا يتمسكون بمنهج الإسلام في الحياة - كما كانوا يوم أشادوا بهذا المنهج تلك الحضارة السامقة - التي أفاد منها الغرب وجعلها في جانبيها العملي والتقنى أساساً أقام عليه حضارته -."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0009.png"}, {"n": 10, "paras": ["مناهج المصلحين المسلمين في الإصلاح", "* ومن أجل دعوة المسلمين إلى التمسك بهذا المنهج العظيم وإحياء معالم الدين وقيمه في نفوسهم يبعث الله لهذه الأمة على رأس كل مائة سنة من يجدد لها أمر دينها - كما ورد ذلك على لسان المعصوم ﷺ ، حتى يعود المسلمون إلى التمسك بمنهجهم ويأخذوا بذلك مكانهم اللائق بهم في قيادة الإنسانية نحو ما يصلح دينها ودنياها . فكان ذلك شغل المصلحين والصالحين وشاغلهم خلال تاريخ الإسلام ، وكلما نجح مصلح في إيقاظ المسلمين ليطبقوا منهجهم نجح المسلمون في استعادة حضارتهم مهما كثر حولهم الأعداء وزاد عدد المتربصين بهم الدوائر .", "* وما نتصور مصلحا من المسلمين في عصر من العصور إلا وهو حسن النية فيما يدعو إليه من إصلاح ، وليس لأحد أن يقول غير ذلك ولا أن ينتقص من قدر أحد منهم إلا أن يكون قد حركه الهوى ، أو غلب عليه الجهل بالإسلام أو بالإصلاح والتجديد لأمر هذا الدين . كل ما في الأمر أن بعض المصلحين كان يرى سببا في تشرذم المسلمين وتراجعهم الحضاري أرجح من سبب ، فيهتم بعلاجه ويجعله في قمة أولوياته الإصلاحيه أو يجعل إصلاحه منحصرا فيه ، حتى يمحوا أثره ويزيل تأثيره ، وهو في هذا العمل قد يخالف أولويات الإصلاح وقد يرى مهماً منها ما ليس بمهم ، وقد يرى غير مهم منها ما هو مهم !!! وعلى سبيل المثال :", "* فإن من المصلحين المسلمين من اهتم بإصلاح العقيدة لاقتناعه بأن من صلحت عقيدته ونقيت من الشوائب انصلح عمله ، لأن العمل يصدر عن العقيدة ، وكلما كانت العقيدة صحيحة كان العمل صحيحا ، وليس هذا"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0010.png"}, {"n": 11, "paras": ["يخطأ ولكنه بعض الصواب لا كل الصواب .", "* ومن المصلحين من اهتم بالعبادة فأولاها في خطته الإصلاحية أكبر العناية والرعاية ، مقتنعا بأن صحت عبادته لله تعالى وفق ما شرع ، فقد مشى في طريق الإصلاح والتقوى والقرب من الله سبحانه وتوليه ، ومن كان كذلك أصلحه الله وأصلح به ، بل أجرى على يديه الخير له وللناس ، والعبادة الصحيحة لله مفتاح كل خير ومغلاق كل شر في الدين والدنيا .", "* ومن المصلحين من رأى أن أهم أنواع الإصلاح هو إصلاح الروح وتصفيتها من صدئها وشوائبها ، وتقوية صلتها بخالقها سبحانه وتعالى ، فيزيد إقبالها على الله وحبها له ، واستمدادها منه ، فتبلغ بذلك درجة رضاها عن الله سبحانه ورضى الله سبحانه عنها ، ومن وصل إلى تلك المنزلة فقد وعده الله بإجابة سؤاله ، وتأييده ونصره ، وحسب المسلم أن يصل إلى هذا فتتفتح أمامه كل أبواب الخير المغلقة ، وتوصد أمامه كل أبواب الشر المفتحة .", "* ومنهم من رأى أن حرب المنكرات ومقاومة الفواحش ما ظهر منها وما بطن هو الإصلاح وهو علاج المسلمين في حاضرهم السيئ ، فأعطى هذه القضية أهمية كبيرة ، مقتنعا بأن مرتكبي الفواحش والمنكرات أو السالكين عليها ، لا يمكن أن يكونوا من أحباب الله ولا أوليائه ومن ثم فلا فلاح ولا نجاح يتم على أيديهم ولا في مجتمعات يعيشون فيها ، فكيف بالنصر في تلك المعارك مع أعداء الإسلام ، والنصر لا يكون إلا للمؤمنين .", "* ومن المصلحين من رأى العلة في المسلمين نتيجة لتساهلهم في التعامل مع نصوص الكتاب والسنة ، والأصل في تصورهم أن تؤخذ هذه النصوص بظواهرها وحرفيتها دون تأويل ، فأعطوا أهمية كبيرة للتمسك بالنصوص بل بظواهرها وحرفيتها والعودة إلى ما كان عليه سلف هذه الأمة ، لأن في ذلك العلاج والخروج من هذا التشرذم والضياع ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0011.png"}, {"n": 12, "paras": ["* ومنهم من قال : إن المسلمين اليوم يحتاجون إلى الدعوة إلى الله ، وتبليغ دين الله لعباد الله فخرجوا في سبيل الله يدعون إليه ويبصرون الناس بأمور دينهم ، ومن تبصر في أمر دينه فلن يكون منه إلا العمل الصالح ، وفي العمل الصالح علاج للمسلمين جميعا .", "* ومنهم من قال : أبنى قاعدة عريضة من المسلمين ، وفي العمل الصالح علاج للمسلمين الفاهمين وأربيهم في خلوات وفي زوايا حتى يعرفوا من دينهم ما لابد من معرفته ، فأخذ يسلك بهم طرقا في المعرفة ، يرى أن سلوكها هو العلاج وأن بلوغ غايتها هو النجاة في الدنيا والآخرة .", "* ومن المصلحين من قال إن العالم الإسلامي يفتقد القادة ، ولو كانت قيادة حكيمة راشدة ما أصبح هذا حاله ، فرأى أن يربى القادة ، وأعلن أنه من الخير له أن يربى قائدا واحدا أفضل من أن يربى ألف جندى ، ومضى في طريقه مؤمنا بأن هذا هو الصواب وهو العلاج لهذه الشرذمة والضياع.", "* ومن المصلحين من قالوا إن داء المسلمين هو الجهل ، فبنى خطته الإصلاحية على الاهتمام الشديد بالعلم والفكر ، معلنين أن سبيل تقدم الأمم في الماضى والحاضر هو العلم والتفوق في العلم ، وهذا علاج ما يعانيه المسلمون اليوم من تراجع حضارى .", "* ومنهم من قال : ما سبقنا الغرب إلا بالتقنية ، فيوم اتخذ الغرب هذه التقنية سبيلا وصل إلى ما وصل إليه من قوة وتحكم في البلدان المتخلفة في هذا المجال فأخذ يشق طريقه في هذا المجال ، متخبطا في الأشواك والعراقيل التي بثها الغرب في طريق التقدم التقنى ، بل جعلها أسراراً لا يجوز إفشاءها ، ولكنهم ماضون في هذه السبيل يتصورون أنها سبيل الإنصلاح والإصلاح .", "* ومن المصلحين من رأى العقبة في طريق وحدة المسلمين هي الأعداء المتربصون ، فقال أبدء بمحاربة هؤلاء الأعداء ، فأجعلهم همى ، فإن تخلصت"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0012.png"}, {"n": 13, "paras": ["منهم ومن حربهم للدين فقد حققت خطوات في طريق الإصلاح وأزلت عقبات كأدوات من الطريق ليسلك فيها المسلمون وقد أمنوا العثرات .", "* ومنهم من قال : هذه أزمنة فتنة ، وتشرذم المسلمين وعداوة بعضهم لبعض بل حرب بعضهم لبعض ، يجعلنا نعيش زمن الفتنة ، وفي الفتنة يجب أن نعتزلها ونعتزل أهلها حتى لا نشارك فيها ، فنخالف ديننا وأحكامه ، وإذا قعد المسلمون عن الخوض في الفتن أو المشاركة فيها ، فقد تهيأ لهم جو الصلاح والإصلاح .", "* ومنهم من قال : إن مجتمعات المسلمين اليوم بما فيها من أنظمة حكم تتحدى الإسلام ، وحكام يعذبون المسلمين ، ويتطاولون على الكتاب والسنة ، هي مجتمعات جاهلية ، ولا معايشة مع هذه المجتمعات ، وإنما هي المقاطعة والمفاصلة حتى يأتي الله بأمر من عنده ، وعندئذ يتخلص المسلمون من تشرذمهم وتراجعهم الحضاري .", "منهج الإمام البنا في الإصلاح", "* ومن المصلحين من كانت نظرتهم أشمل ورؤيتهم أوضح ، وأيقنوا أن علاج خلل وترك آخر ليس هو الطريق ، ففتح الله عليه باب الحق ووفقه إلى السعى في طريقه فهداه بذلك إلى العلاج الصحيح ، فقال : إن علاج تشرذم المسلمين وتفرق كلمتهم وذهاب ريحهم وتراجعهم الحضاري لا يكون بعلاج واحدة من هذه الآفات ، وإنما يكون بعلاجها جميعا ، ولابد أن يكون منهج الإصلاح لإخراج المسلمين من وهدتهم شاملا متكاملا - دون الزراية بمنهج أحد من المصلحين - يتناول أركان الإصلاح جميعا ، فيها يمكن أن ينصلح حال المسلمين . وهذه الأركان هي :", "- فهم الدين الإسلامي فهما صحيحا شاملا متكاملا ،", "- والإخلاص لله في العمل من أجل هذا الدين ،"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0013.png"}, {"n": 14, "paras": ["- والعمل من أجل هذا الدين بإصلاح النفس والبيت المسلم ، والمجتمع والحكومة ... الخ ،", "- والجهاد في سبيل الله بمختلف درجاته وأنواعه ،", "- والتضحية بالوقت والجهد والمال والنفس من أجل هذا الدين ،", "- والطاعة لله ولرسوله في العسر واليسر والمنشط والمكره ،", "- والثبات على هذا الدين عقيدة وشريعة وعملا مهما تطاولت الأزمان التي يصل المسلمون فيها إلى تحقيق أهدافهم .", "- والتجرد ، بالتخلص من كل فكرة تخالف فكرة الإسلام ، ومن كل شخص أو زعيم يحول بين المسلم وتجرده لدينه ،", "- والأخوة في هذا الدين ، فهي أخت الوحدة ، وعلاج للتشردم والضياع ، بينما الفرقة أخت الكفر .", "- والثقة في قيادة العمل من أجل الإسلام في ضوء القاعدة الإسلامية الذهبية التي تقول : « لا طاعة لمخلوق في معصية الخالق » . وهذه الأركان العشرة هي مفردات منهج الإصلاح التي يعالج بها المسلمون تشرذمهم وفرقتهم وتراجعهم الحضاري ، وهو المنهج الذي وفق الله إليه الإمام حسن البنا رحمه الله فكتب فيه رسالة وجيزة جامعة ، جاءت بين رسائله أوفاها ، وأصبحت من بعده من أهم وثائق الجماعة التي تعنى بوضع برنامج دقيق لإصلاح حال المسلمين واستعادتهم زمام الحضارة الإنسانية . وسوف نحاول في هذا الكتاب الوجيز أن نتناول بالشرح والتفصيل المناسب هذه الرسالة الجامعة (١) ، لندل بها ونشرحها لها على منهج جماعة الإخوان", "(١) سبق لنا شرح هذه الرسالة بإيجاز في كتابنا منهج التربية عن الإخوان المسلمين نشر دار الوفاء ١٩٩١م."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0014.png"}, {"n": 15, "paras": ["المسلمين في الإصلاح العام لكل مرافق الحياة الإنسانية من خلال منهج الإسلام ونظامه ، ولكي نؤكد للناس أن شعار « الإسلام هو الحل » ليس شعاراً أطلق من فراغ ، وليس مجرد شعار ، وإنما يصحبه منهج شامل متكامل مأخوذ من الإسلام ليصلح العقيدة والفكر والثقافة ، ويصلح العبادة والخلق والسلوك ، فهو إصلاح اجتماعي واقتصادي وسياسي ، وهو إصلاح دعوى حركي تربوى تنظيمي شامل متكامل .", "ولكي نوصل هذه الرسالة « رسالة التعاليم » إلى الناس عموما ، وإلى الذين يتوهمون أن شعار « الإسلام هو الحل » هو مجرد شعار لا يصاحبه منهج مفصل نوصل إليهم حقيقة كبرى هي أن « شعار الإسلام هو الحل » معه منهج بلغ الغاية في الدقة والإستيعاب .", "وقد وجه الإمام المؤسس لهيئة الإخوان المسلمين رحمه الله هذه الرسالة إلى الصفوة من الإخوان المسلمين ، الذين نضجوا في مجالات العمل وفي مراحل الدعوة ، وفى الحركة والتربية ، وأصبحوا مؤهلين للجهاد في سبيل الله من أجل تطبيق منهج الإسلام في الحياة ، ومن أجل ذلك سماهم الإخوان المجاهدين ، لما سوف يحملونه من أعباء الجهاد بكل مراتبه وأنواعه من أجل تطبيق هذا المنهج .", "وقد سماهم مرة أخرى - في نفس الرسالة - بالإخوان الصادقين ، لأنهم صدقوا ما عاهدوا الله عليه ، وهم يتربون في صفوف الجماعة ، وقد كان هؤلاء الإخوة عاهدوه وأخذوا على أنفسهم البيعة أن يعملوا ما وسعهم في سبيل تطبيق منهج الإسلام في الإصلاح ، مؤمنين بأن الإسلام هو الحل لكل مشكلة في أي مجال من مجالات الحياة الإنسانية كلها ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0015.png"}, {"n": 16, "paras": ["فإنَّه لا يصحُّ أن يُقال: إنَّه لا يرى، بل هو يرى، ولكنَّه لا يرى كما نرى، ولا يُكيَّفُ رؤيتُه، كما لا تُكيَّفُ ذاتُه، ولا يُكيَّفُ سَمْعُه، ولا كلامُه، ولا عِلْمُه، ولا قُدْرَتُه، ولا غيرُ ذلك من صفاتِه.", "فإنَّ القولَ في الصفاتِ كالقولِ في الذاتِ، فكما أنَّه ذاتٌ لا كذواتِ المخلوقين، فكذلك صفاتُه لا كصفاتِ المخلوقين.", "وقد قال اللهُ تعالى: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾.", "فأثبتَ لنفسِه السَّمْعَ والبَصَرَ، ونفى عن نفسِه المِثْلَ، فدلَّ على أنَّ سَمْعَه وبَصَرَه ليسا كَسَمْعِ وبَصَرِ المخلوقين.", "فمَن قال: إنَّه لا يرى، فقد كذَّبَ القرآنَ، ومَن قال: إنَّه يرى كَرُؤيَتِنا، فقد شَبَّهَه بالمخلوقين، وكلاهما ضالٌّ.", "والحقُّ: أنَّه يرى رؤيةً تليقُ بجلالِه وعظمتِه، لا تُشْبِهُ رؤيةَ المخلوقين، كما أنَّه يَعْلَمُ عِلْمًا لا يُشْبِهُ عِلْمَ المخلوقين، ويَقْدِرُ قُدْرَةً لا تُشْبِهُ قُدْرَةَ المخلوقين."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0016.png"}, {"n": 17, "paras": ["فهم أصول الإسلام في رسالة التعاليم"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0017.png"}, {"n": 18, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0018.png"}, {"n": 19, "paras": ["وقد صدر الإمام المؤسس هذه الرسالة بقوله : أما بعد : فهذه رسالتي إلى الإخوان المجاهدين من الإخوان المسلمين ، الذين آمنوا بسمو دعوتهم وقدسية فكرتهم وعزموا صادقين على أن يعيشوا بها أو يموتوا في سبيلها . إلى هؤلاء الإخوان فقط أوجه هذه الكلمات الموجزة ، وهي ليست دروسا تحفظ لكنها تعليمات تنفذ ، فإلى العمل أيها الإخوة الصادقون « وقل أعملوا فسيرى الله عملكم ورسوله والمؤمنون وستردون إلى عالم الغيب والشهادة فينبئكم بما كنتم تعملون » (١) « وأن هذا صراطى مستقيما فاتبعوه ولا تتبعوا السبل فتفرق بكم عن سبيله ذلكم وصاكم به لعلكم تتقون » (٢) . أما غير هؤلاء فلهم دروس ومحاضرات وكتب ومقالات ومظاهر وإداريات ، ولكل وجهة هو موليها فاستبقوا الخيرات ، وكلا وعد الله الحسنى … والسلام عليكم ورحمة الله وبركاته . ثم أخذ يفيض في الحديث عن الدعائم التي يقوم عليها إعداد هؤلاء الإخوان وتربيتهم ليكونوا قادة العمل في الجماعة وفى العمل الإسلامي كله ، وليكون منهم المجاهدون الصابرون المحتسبون الذين يبيعون أنفسهم وأموالهم ابتغاء مرضاة الله . وقد اعتبر الإمام المؤسس دخول هؤلاء الأفراد في هذه المرحلة بمثابة بيعة يجب عليهم الوفاء بها ، ولا يجوز لهم التخلى عنها ، وجعل لهذه البيعة أركانا عشرة وشرح كل ركن منها الشرح الذي يلائمه ويلائم الإخوان في ذلك الوقت من تاريخ الجماعة وركز على الركن الأول وهو ركن الفهم فعالج فيه", "(١) سورة التوبة : ١٠٥ .", "(٢) سورة الأنعام : ١٥٣ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0019.png"}, {"n": 20, "paras": ["مسائل العقائد والعبادات والمعاملات علاجا نسبيا إذا قورن بحديثه عن بقية الأركان لأنه الأصل والأساس الذي تقوم عليه سائر الأركان. وقد كتب هذه الرسالة سنة ١٩٤٣ م وقد غبرت الجماعة من عمرها عقدا ونصف عقد ، وكان لها من الاحتكاك بالعمل والناس والقضايا رصيد كبير. وسنحاول في هذا الكتاب أن نتعرف على أركان البيعة واحدا واحدا في إجمال ، وأن نتحدث عن ركن الفهم بما يزيده وضوحا ، والله نسأل العون التوفيق . يقول الإمام المؤسس : ه أيها الإخوان الصادقون ، أركان بيعتنا عشرة فاحفظوها : الفهم ، والإخلاص ، والعمل ، والجهاد ، والتضحية ، والطاعة ، والثبات ، والتجرد ، والأخوة ، والثقة . أركان البيعة ولابد لنا بادئ ذي بدء من أن نلقى الضوء على تعبير « أركان بيعتنا عشرة فاحفظوها » : فما مفهوم هذه العبارة ؟ إن العبارة مكونه من كلمات : أركان وبيعة واحفظوها .", "* فالأركان : جمع ركن وهو الجانب أو أحد جوانب الشئ الذي يقوم عليه وعلى باقى الأركان بناؤه . أو هو : الجانب الذى إذا ترك بطل العمل ولم تقم له قائمة . أو هو : الجانب الأقوى . أو هو : الأمر العظيم ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0020.png"}, {"n": 21, "paras": ["أو هو : ما يُقوّي به من ملك وجند وغيره ومنعة .", "* والبيعة : تعهد ببذل الطاعة في مقابل . وهي في الأصل بذل الطاعة للسلطان بما رضح السلطان له . والمبايع : يبايع على أن يبذل الطاعة مهما كلفته الطاعة من مال أو جهد أو نفس ما دام ذلك في رضا الله سبحانه وتعالى . والمقابل : هو جنة الله التي أعدها لمن بذلوا أموالهم وأنفسهم في سبيله ، ولقد ورد في القرآن الكريم حديث عن هذه البيعة بين الله وصفوة عباده من المؤمنين ، فقال تعالى : ﴿ إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة يقاتلون في سبيل الله فيقتلون ويقتلون وعدا عليه حقا في التوراة والإنجيل والقرآن ، ومن أوفى بعهده من الله فاستبشروا ببيعكم الذي بايعتم به وذلك هو الفوز العظيم ﴾(١) . وهذه البيعة بين الله سبحانه والمؤمنين من عباده ، فالله سبحانه فيها هو المشترى والمؤمن الصادق هو البائع والمقابل الجنة وإذا تمت هذه البيعة بين المؤمن وربه لا يبقى للمؤمن بعدها في ماله ولا نفسه ما يجوز له أن يحتجزه من دون الله ، أى دون الجهاد في سبيله لتكون كلمة الله هي العليا ، وليكون الدين كله لله ، وليصبح منهج الإسلام هو المعمول به وهو العلاج لكل مسائل الحياة . والثمن هو الجنة ثمن لا يعدله شيئ ولا سلعة وإنما هو فضل من الله ورحمة ، وما دامت الأنفس هو خالقها والأموال هو رازقها فأى تفضل وإنعام على المؤمنين من الله تعالى إذ يكون في مقابلها الجنة ؟ لقد قال أسلافنا رضوان الله عليهم في هذه الصفقة « إذا ربح البيع لا نقيل ولا نستقيل » . كما وردت البيعة في القرآن الكريم بمناسبة بيعة الرضوان في عمرة الحديبية وهي بيعة تمت فعلا بين الرسول ﷺ والمؤمنين تحت الشجرة قال الله تعالى :", "(١) سورة التوبة : ١١١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0021.png"}, {"n": 22, "paras": ["لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة فعلم ما في قلوبهم فأنزل السكينة عليهم وأثابهم فتحا قريبا ، ومغانم كثيرة يأخذونها وكان الله عزيز حكيما (١).", "والبيعة في الجماعة كانت تعنى بيعة على الجهاد في سبيل الله لتكون كلمة الله العليا والمقابل فيها هو رضا الله سبحانه وتعالى والجنة يوم نلقاه تفضلا منه ورحمة ولذلك عبر عنها المؤسس بقوله : « بيعتنا » أى بيعة الإخوان لقائدهم ليجاهدوا في سبيل الله بأموالهم وأنفسهم حتى يسود منهج الله ونظامه حياة الناس. وليست البيعة هذه هي البيعة لإمام المسلمين أو خليفتهم الذي اختاره أهل الحل والعقد ، أو اختاره المسلمون.", "أقول ذلك حتى أحرر هذه الفكرة من كل لبس يقع فيها أو حولها ، لأنها مسألة شرعية لا تحتمل تأويلا معتسفا ، وذلك أن بعض الذين لم يتعمقوا دراسة الشريعة الإسلامية يقولون : « إن الإمام المؤسس أعطى لنفسه حقوق إمام المسلمين ، وهذا باطل يكذبه فقه الرجل للإسلام ويكذبه الواقع الذي عاشته الجماعة ويكذبه المبايعون له وكثير منهم لا يزالون أحياء - وكنت واحدا منهم -.", "إن الإمام المؤسس كان يعتبر جماعة الإخوان المسلمين بكل مناهجها ونظمها وإداراتها وشعبها ومناطقها وأقسامها ولجانها خطوة أو خطوات توصل إلى أن يكون للمسلمين حكومة إسلامية في وطن من الأوطان ، ثم تتعدد هذه الحكومات الإسلامية بتعدد الأوطان فيكون بينها وحدة - تحدث عنها وعن وسائلها وخطواتها فيما كتب فتكون الأمة الإسلامية أمة واحدة وعند ذلك يتفق المسلمون أو أهل الحل والعقد منهم على إختيار إمام لهم أو خليفة فتكون البيعة له ويكون الإخوان المسلمون أول من يبايعه ويسمع له ويطيع .", "كان هذا هو فقه الإمام المؤسس لهذه القضية ، وكم سمعنا منه هذا الكلام", "(١) سورة الفتح : ١٨ - ١٩ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0022.png"}, {"n": 23, "paras": ["في جلساته الخاصة وفي كثير مما كتب ، وكل القائلين بغير ذلك لم يعرفوا الإمام المؤسس من قرب ولم يقرأوا ما كتب بتعمق وروية وتحليل علمي دقيق . تلك كلمة حق عايشناه عليها كان يجب أن تقال .", "* وأركان البيعة : هي جوانبها القوية التي تقوم عليها ، ولا تقوم إلا بها ، ولا تعد بيعة إلا بها ، وهي عشرة كما عدها الإمام المؤسس فاستوعب كل متطلبات الإصلاح .", "* وكلمة : « فاحفظوها » تعنى أمرين : الأول : الوعى والفقه بعد الاستظهار أى ثبات ما يؤدى إليه الفهم . والثاني : العمل بمقتضاها . أى الرعاية والتعهد والتنفيذ . ولا يغنى واحد من الأمرين عن الثاني ، بل لابد منهما معا . أى فقه وعمل . وهذه الأركان العشرة التي أشرنا إليها آنفا مجملة سوف نفصل الحديث عن أولها وهو الفهم بعون الله وتوفيق منه على النحو التالي :"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0023.png"}, {"n": 24, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0024.png"}, {"n": 25, "paras": ["الركن الأول الفهم وهو وحده موضوع هذا الكتاب ويقول فيه الإمام المؤسس : « إنما أريد بالفهم أن تؤمن بأن فكرتنا إسلامية صميمة ، وأن تفهم الإسلام كما نفهمه في حدود هذه الأصول العشرين الموجزة كل الإيجاز »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0025.png"}, {"n": 26, "paras": ["وهذه المقدمة تتناول أمرين على جانب كبير من الأهمية هما : الأول : اليقين بأن فكرة جماعة الإخوان المسلمين إسلامية من صميم الإسلام لم تزد عليه شيئا ولا نقصت منه شيئا ، فهي فكرة متبعة لا مبتدعة ، وهي مع فكر أهل السنة والجماعة والسلف الصالح رضوان الله عليهم أجمعين ، ولابد من اليقين بذلك . والثاني : ضرورة فهم الإسلام فهما صحيحا سليما كما فهمه أهل السنة والجماعة والسلف الصالح رضوان الله تعالى عليهم في حدود الأصول العشرين التي حددها الإمام المؤسس ، وجمع فيها كل ما يجب أن يفهمه المسلم عن دينه. وفى الإطار الذي يجب أن يفهم فيه ، دون تساهل في شئ ودون تنطع أو تشدد في شئ ، فهكذا فهم أهل السنة والجماعة والسلف الصالح رضوان الله عليهم هذا الدين . وإلى الحديث عن هذه الأصول العشرين سائلين الله التوفيق ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0026.png"}, {"n": 27, "paras": ["الأصل الأول من أصول الفهم", "« أن الإسلام نظام شامل يتناول مظاهر الحياة جميعا ، فهو :", "١ - دولة ووطن ، أو حكومة وأمة ،", "٢ - وهو خلق وقوة ، أو رحمة وعدالة ،", "٣ - وهو ثقافة وقانون ، أو علم وقضاء ،", "٤ - وهو مادة وثروة ، أو كسب وغنى ،", "٥ - وهو جهاد ودعوة ، أو جيش وفكرة ،", "٦ - كما هو عقيدة صادقة وعبادة صحيحة سواء بسواء » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0027.png"}, {"n": 28, "paras": ["هذه كلمات الإمام المؤسس في الأصل الأول من أصول الفهم ، سنلقى عليها بعض الأضواء لنرد بها على قالات السوء التي يرددها العلمانيون «اللادينيون» من زعمهم أن الإسلام دين لا دولة ، وأنه نبوة لا حكومة ، وأنه تضمن قسوة ووحشية بإقامة الحدود ، وأنه نزل لقوم معينين في بيئة معينة في زمن معين ، وأنه يزهد الناس في الحياة ، وأنه فتح وتوسع على حساب الآخرين. إن هذه الكلمات الوجيزة يرد فيها الإمام المؤسس على تلك التهم والمفتريات بتوضيح المعنى الأصيل الصحيح للإسلام كما يفهم من مصدريه الرئيسين الكتاب والسنة.", "ولنوضح هذه الكلمات على النحو التالي :", "١ - « الإسلام دولة ووطن أو حكومة وأمة : أ - الإسلام دولة ووطن : الدولة بمعناها السياسي : هي مجتمع منظم يعيش على إقليم معين ، ويخضع لسيطرة هيئة حاكمة ذات سيادة ، ويتمتع بشخصية معنوية متميزة عن المجتمعات الأخرى المماثلة . وتربط بين الدولة والأفراد رابطة تفرض على الأفراد الولاء للدولة والخضوع لقوانينها. كما تفرض على الدولة حماية أرواح الأفراد وأموالهم وكافة حقوقهم التي يقرها القانون الطبيعي والقوانين الوضعية . هذا تعريف الدولة عند علماء السياسة والاجتماع المعاصرين لنا في أخريات هذا القرن العشرين نهاية العقد الأول من القرن الخامس عشر الهجري . والإسلام إذ طبق عليه هذا التعريف فهو دولة بكل تأكيد ، لتوفر كل مفردات هذا التعريف للدولة الذي ذكرناه ، مع تحفظ واحد هو أن حقوق الأفراد التي يجب على الدولة أن تحميها أو تكفلها وهى التي يقرها القانون الطبيعي - وهى"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0028.png"}, {"n": 29, "paras": ["النظم والقواعد التي يسير عليها الكون كله ، والقواعد التي تسير بمقتضاها الشئون البشرية مستقلة عن أى قانون وضعى وإنما تستمد وجودها من تفكير الإنسان الصادر عن طبيعته كمخلوق إجتماعى رشيد - ويقرها السلوك الاجتماعى المقرر عن طريق الدين لا عن طريق القانون الوضعى ، تلك هي الحقوق الطبيعية للإنسان . ثم نضيف قائلين : الحقوق التي تقرها الشريعة الإسلامية المتمثلة في الكتاب والسنة لا في القوانين الوضعية - هذا هو تحفظنا في هذا المجال . فالإسلام بهذا المعنى دولة متكاملة البناء تمارس حقوقها وتؤدى واجباتها كما تدل على ذلك نصوص الدين وممارسته في حياة النبي ﷺ وحياة الصحابة والتابعين رضى الله عنهم ، وممارسته على فترات غير قصيرة من التاريخ .", "* والوطن هو : المكان الذي يسكنه الأفراد ويشعرون فيه بارتباطهم به وإنتمائهم إليه ، وهذا بالنسبة للمسلمين هو كل مكان يوجد فيه من يقولون : « لا إله إلا الله محمد رسول الله » لأن العقيدة الإسلامية هي وطن المسلم بل جنسيته كما ورد ذلك كثيراً في كلمات المؤسس عليه رحمه الله. فالإسلام شامل لمفهوم الدولة ولمفهوم الوطن ، وقادر بمنهجه على إصلاحهما. ب - الإسلام حكومة وأمة :", "* والحكومة هي : نظام إدارة الدولة وتصريف أمور الناس وتوجيه جهودهم وتنظيمها وضبط سلوك الأفراد والجماعات في الدولة عن طريق القوانين التي يضعها صاحب السلطة في الدولة ويتولى تنفيذها مستعينا بالقوة المادية عند الاقتضاء . وتطلق كلمة الحكومة في المصطلح السياسي على مجموع الهيئات الحاكمة في الدولة فتشمل بذلك السلطات الثلاث :"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0029.png"}, {"n": 30, "paras": ["التشريعية ، والتنفيذية ، والقضائية ، والإسلام حكومة بهذا المعنى كذلك - باستثناء أن القوانين فيه ليست من وضع صاحب السلطة ، وإنما هي وحى من الله عن طريق القرآن الكريم والسنة النبوية المطهرة . والتشريع في الحكومة الإسلامية مقصور على الأمور التي لم ترد فيها نصوص من الكتاب أو السنة ، ويسمى هذا التشريع اجتهادا أفضل من أن يسمى تشريعا - لأن المشرع على وجه الحقيقة هو الله . ولعلماء المسلمين أن يجتهدوا في أي زمان أو أي مكان في الأمور التي تستحدث في حياة الناس وليس فيها نص ، وكل ما أدى إليه الاجتهاد أخذوا به إذا تم الاجتهاد وفق شروطه التي وضعتها الشريعة الإسلامية وعلماء الفقه الإسلامي وأصوله .", "* والأمة هي : مجموعة من الأفراد تجمعهم ثقافة مشتركة تستند إلى وحدة الأصل أو اللغة أو الدين ، ويربط بينهم تاريخ وتراث اجتماعي ومصالح اقتصادية، ويعيشون على أرض واحدة ويعملون على دوام هذه الروابط من الناحية السياسية في إطار الدولة . والمسلمون أمة بهذا المعنى وإن كانت وحدة الدين هي التي تربط بينهم بأوثق الروابط ، ثم تعتبر رابطة التاريخ ورابطة التراث الاجتماعي والمصالح المشتركة في الاقتصاد وغيره. وأما وحدة الأصل فإن لها في الإسلام معنى أشمل وأعم وأنبل وهو أن الناس جميعا لأب واحد هو آدم عليه السلام وأن رب الناس واحد هو الله الرحمن الرحيم الملك القدوس سبحانه وتعالى ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0030.png"}, {"n": 31, "paras": ["وأما اللغة فهي رابطة محلية وإن كان الإسلام يقيم وزنا كبيرا للغة القرآن ويجعلها لغة كل مسلم يتحدث بها مهما كان عرقه ، كما جاء ذلك على لسان النبي ﷺ حيث قال : « … ألا إن العربية اللسان » . فالإسلام شامل أيضا لمفهوم الحكومة ومفهوم الأمة وقادر بمنهجه على توجيه الحكومة وترشيد الأمة لتشق طريقها بهذا المنهج نحو التقدم والتحضر والازدهار.", "٢ - « الإسلام خلق وقوة أو رحمة وعدالة » أ - الإسلام خلق وقوة : والخلق وإن كان في مصطلح علماء الاجتماع يتغير وبتطور حلان ، فمن لأنه نتاج خبرة الفرد ، فإن الخلق في الإسلام ثابت لا يتغير بتغير الزمان والمكان ، وبخاصة فيما هو فضائل مقررة في الدين ، أو رذائل حرمها الدين ، فهو من هذا الجانب ليس من نتاج خبرة الفرد وإنما هو من مقررات الدين وقيمه وآدابه .", "* الإسلام خلق : إذ الأخلاق في الإسلام هي : « مجموعة المبادئ والقيم التي تنظم سلوك المسلم ، ويحددها الوحى لينظم بها حياة الإنسان ، ويضع لها من الضوابط ما يمكنها من أن تحقق الغاية من وجود الإنسان على هذه الأرض وهي : عبادة الله سبحانه المؤدية إلى سعادة الإنسان في الدنيا والآخرة (١) . وخلق الرسول ﷺ - وهو القدوة لجميع المسلمين - هو القرآن الكريم ، كما ورد ذلك على لسان أم المؤمنين عائشة رضى الله عنها حين سئلت عن خلق رسول الله ﷺ فقالت : « كان خلقه القرآن » . وتقوم الأخلاق الإسلامية في مجموعها على ثلاث ركائز : الأولى : التبعة الفردية ، المتمثلة في قوله سبحانه وتعالى : ﴿ كل نفس بما", "(١) على عبد الحليم : مع العقيدة والحركة والمنهج : نشر دار الوفاء ١٩٩٢م."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0031.png"}, {"n": 32, "paras": ["كسبت رهينة (١) . والثانية : العدل والإحسان المتمثلين في قوله تعالى : ﴿ إن الله يأمر بالعدل والإحسان﴾ (٢) . والثالثة : النهي عن الفحشاء والمنكر والبغي المتمثلة في قوله سبحانه وتعالى : ﴿ … وينهى عن الفحشاء والمنكر والبغي ﴾ (٣) . وهذه الركائز الثلاث هي التي جعلت من المسلمين خير أمة أخرجت للناس وهي التي تجعل من منهجهم علاجا لكل مشكلات الحياة الإنسانية .", "* والإسلام قوة : والقوة هي القدرة التي تحدث أثرا وهي القوة المادية . وقد تكون بمعنى قوة القلب ، أى الدافع على عمل معين ، وحينئذ يكون هذا الدافع داخليا ، أو تكون بدافع خارجي ، نحو قوله تعالى ﴿لو أن لي بكم قوة﴾ (٤) وقوله سبحانه ﴿ فأعينوني بقوة ﴾ (٥) . وقد تكون القوة نفسية تعتمد على التجارب الواعية ، واجتماعية حين تدفع إلى العمل الاجتماعي . والإسلام قوة بهذه المعاني كلها . فهو قوة معنوية تتمثل في الإيمان الداعي إلى العمل . وهو قوة مادية تتمثل في الجهاد في سبيل الله. وهو قوة نفسية نابعة من التجارب التي تجعل المسلم متمسكا بأخلاق الإسلام وسلوكه في كل أمر من أموره.", "(١) سورة المدثر : ٣٨.", "(٢) سورة النحل : ٩٠.", "(٣) سورة النحل : ٩٠.", "(٤) سورة هود : ٨٠.", "(٥) سورة الكهف : ٩٥."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0032.png"}, {"n": 33, "paras": ["وهو قوة اجتماعية تدفع الأفراد إلى فعل الخير وإيثاره وتقديمه للناس عموما. وإذا كان الخلق - كما قدمنا - فإنه دائما يحتاج إلى قوة تسانده وتدفع به في حياة الناس ، فإن خلق القرآن الذي هو خلق المسلم بحاجة كذلك إلى قوة تسانده وتؤيده وتعلي قيمه وتفرضه على الناس فرضا لأنه الحق الذي جاء من عند الله لصالح الناس في معاشهم ومعادهم ، وذلك من معاني تكامل الإسلام. والخلق والقوة لازمان معاً حتى تستقيم حياة الناس . ب - والإسلام رحمة وعدالة :", "* الرحمة الإسلام رحمة بمعنى أن فيه رقة تقتضى الإحسان إلى المرحوم ، ورحمة الله إحسان ولا توصف برقة ، فالله سبحانه ركز في طباع الناس الرقة وتفرد بالإحسان وبهذا المعنى روى : أن الرحمة من الله إنعام وإفضال ، ومن الناس رقة وتعطف. والإسلام رحمة بمعنى أنه الدين الذي يأمر أتباعه بالرحمة ويوجبها عليهم ، أى الرقة في التعامل مع الناس والترفق بهم والإحسان إلى من يستحق الإحسان منهم ، إنها رحمة تستهدف الوصول بالإنسان إلى ما ينفعه في دنياه وآخرته ، مع رقة به وتعطف عليه ، فإن كان شارداً عن الحق ظللنا به نشجعه ونبين له العواقب في رقة وتعطف ، وإن كان معاندا ظللنا به نوضح له أثر العناد وعاقبته الوخيمة ، وأن الذي يعاند الحق إنما يعاند إنسانيته ومجتمعه وحاضره ومستقبله ، وكل ما يحيط به ، ويجلب بهذا العناد لنفسه ولغيره الضرر ، ويضره غيره كذلك . وإن كان مع الحق لكنه لا يصبر عليه ولا على التمسك به ، أوضحنا له أن التمسك بالحق يكمله التواصى به والتواصى بالصبر عليه ، فقوة المؤمن العمل الصالح والتواصى بالحق والتواصى بالصبر وهكذا حتى تستقيم البشرية على الحق وعلى التمسك به والصبر عليه. وفى كل ذلك نجد الإسلام رحيما بهؤلاء الناس عطوفا عليهم محسنا لهم"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0033.png"}, {"n": 34, "paras": ["بهدايتهم إليه .", "* والإسلام عدالة - مع هذه الرحمة - : العدالة تعنى المساواة بين الناس في كل ما من شأنه أن يساوى فيه بينهم . والعدل نوعان :", "- عدل مطلق ، يقتضى العقل حسنه كالإحسان إلى من أحسن إليك وكف الأذى عمن كف أذاه عنك .", "- وعدل يلزم به الشرع ، كالقصاص وأروش الجنايات(١) . والمقصود من أن الإسلام عدل أى أنه يساوى في المكافأة مع الخير خيرا ، ومع الشر شرا . فالمحسن : يكون من العدل أن يكافأ خيرا . والمسيء : يكون العدل معه أن يكافأ شرا ، وهكذا . ولو أن الإسلام رحمة فقط بدون عدل لأدى ذلك إلى طمع المسيء وفتور المحسن ، ولما قامت حياة الناس على ما يصلح معاشهم ومعادهم . وهذه من علامات شمول الإسلام وكونه نظاما شاملا للحياة الإنسانية كلها ، فهو رحمة وعدالة ، وبيهما معا تستقيم حياة الإنسان ، وذلك أيضا هو من معانى تكامل الإسلام أى أن بعضه لا يغنى عن بعض ، أو أنه لا يحتاج إلى سواه من النظم والنظريات لأنه كامل متكامل . ولمثل هذه الصفات الجامعة جعله الله خاتم الأديان وأتمها ، ورضيه للبشرية كلها دينا وكان التمسك بمنهجه هو الحل الحقيقى لكل أمور المجتمع الإنساني .", "(١) جمع أرش : وهو دية الجراحات في باب القصاص من كتب الفقه."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0034.png"}, {"n": 35, "paras": ["٣ - « الإسلام ثقافة وقانون أو علم وقضاء » أ - الإسلام ثقافة وقانون :", "* الإسلام ثقافة بمعنى أنه مبادئ ونظم ومنهج يدركه المسلم ببصره إذا حدق نظره ، ويدركه ببصيرته إذا تفتح قلبه بهدى من الله . وإذا كانت الثقافة - كما يرى علماء الاجتماع - هي البيئة بما فيها من منتجات مادية وغير مادية ، متضمنة الأنماط السلوكية ظاهرها وباطنها المكتسبة عن طريق الرموز ، والمكونة من العلوم والمعتقدات والفنون والقيم والقوانين والعادات ، والتي تنتقل من جيل إلى آخر . إذا كانت الثقافة هي ذاك ، فإن للإسلام بهذا المعنى ثقافة تشتمل على كل ذلك ، وتزيد عليه أن المعتقدات فيها خالية من الخرافة والوهم ، وأن القيم فيها كلها خيرة ، وأن القوانين السائدة فيها ليست من وضع البشر وإنما هي شرع الله ومنهجه ونظامه . إن الإسلام غنى تماما بكل مفردات الثقافة التي أشار إليها علماء الاجتماع ، بل متميز في هذه المفردات بأن كل مفرده من مفرداته لم يتوصل إليها الناس اعتباطا ولا استجابة لوسوسات الشياطين ولا نتيجة للاحتكاكات والصراعات ، وإنما هي مفردات يؤدى الأخذ بها إلى إستقرار المجتمع ، وإلى أن تسدد فيه كل أنواع الخير والبر، وأن تنكمش فيه أو تمحى منه كل أقذار الشر والفسق والفجور.", "* وأما أن الإسلام قانون : فهذا يعنى أنه مجموعة من المبادئ التي تضبط السلوك الاجتماعي وترشده . وإذا كان القانون عند علماء السياسة والاجتماع هو قمة التنظيم الاجتماعي للسلوك الإنساني من حيث إنه يحدد في صراحة ووضوح ما يجب على الفرد عمله وما يجب عليه الامتناع عنه ، ويحدد بحسم ووضوح العقوبات التي توقع"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0035.png"}, {"n": 36, "paras": ["على من يخالف هذا القانون ... إذا كان القانون كذلك ، فإن الإسلام يعد أفضل قانون من حيث قدرته على ضبط السلوك الاجتماعي وترشيده ، لأنه يضبط ويرشد لا عن رهبة وخوف من العقوبة لمن يخالف ، ولكن يتم ذلك بوازع ذاتي وإحساس بالتبعة والمسئولية ، وإيمان بأن الله رقيب حسيب ، وأنه إذا جاز لمنحرف أن يغافل القانون فإنه لن يستطيع أن يغافل رب العالمين بحال من الأحوال .", "إن القانون في الإسلام يوجه الثقافة ويضبطها ، كما يوجه المجتمع ويضبطه ، ومن خلال هذا الضبط هنا وهناك تكون الحياة الإسلامية الراشدة . فالثقافة وحدها لا تكفى بل تحتاج إلى قانون ينظمها . والقانون وحده لا يكفى وإنما ينبغى أن تكون له خلفية ثقافية تمده بروافده التي لا يستغنى عنها . ولعلني بذلك أكون قد أوضحت أن الإسلام ثقافة وقانون .", "ب - والإسلام علم وقضاء : والعلم : إدراك الشئ بحقيقته سواء أكان إدراكا لذات الشئ أو حكما عليه . والعلم : نظرى وعملى . فالنظرى إذا علم فقد كعلم بموجبات العالم . والعملى ما لا يتم إلا بأن يعمل ، كالعلم بالعبادات مثلا . والعلم : عقلى وسمعى . فالعقلى ما يدرك بالعقل ، والسمعى ما يدرك عن طريق الوحى .", "والإسلام : علم بكل معنى من هذه المعاني جميعا . وإذا كان العلم في مفهوم علماء الاجتماع هو مجموعة المعارف المتكاملة"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0036.png"}, {"n": 37, "paras": ["والمبادئ والكليات المتعلقة بحقيقة ظاهرة معينة ، ويقوم على أساس الملاحظة والتجربة ، ولا يستند إلى الميول الفردية أو الآراء الشخصية .", "وإذا كانت مفردات العلم هي : بترتيب تنازلي : المنطق فالحساب فالهندسة فعلم الحركة فعلم الميكانيكا فالعلوم الطبيعية فعلم الفلك والجيولوجيا فالكيمياء فالبيولوجيا علم النفس فعلم الإجتماع إذا كان العلم هو ذاك وإذا كانت مفرداته هي تلك ، فالإسلام علم بمعنى أنه مجموعة من المعارف المتكاملة والمبادئ المتعلقة بالحياة نفسها ، وهو يدعو إلى البحث والدراسة والتعمق في كافة العلوم والمعارف ، ويرى فيها وسيلة لإقدار الإنسان على الاستفادة من كل ما سخر الله له في الحياة ، ويطالب المسلم بأن يتعلم العلم ويرز فيه ما وجد إلى ذلك الوسيلة المشروعة ، ولا يدع طلب العلم حتى يلقى الله .", "الإسلام علم بهذا المعنى ، وهو علم بالناس بما يصلحهم وما يفسدهم ، وبالحياة الدنيا ما يصلح لها وما لا يصلح ، وعلم بالمبادئ والنظريات التي يراها أفضل ما يجب في حياة الناس .", "هكذا نجد الإسلام علما بهذا المعنى .", "* والإسلام قضاء : والقضاء هو : الفصل في الأمر قولا كان ذلك الفصل أو فعلا .", "وكل من هذين على نوعين : قضاء إلهي : أى أمر إلهي نحو قوله تعالى : ﴿ وقضى ربك ألا تعبدوا إلا إياه﴾(١) .", "وقضاء بشرى : مثل قضاء الحاكم بكذا من الأمور .", "(١) سورة الإسراء : ٢٣ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0037.png"}, {"n": 38, "paras": ["والإسلام قضاء بمعنى أنه بما يحتوى عليه من مبادئ وقيم يستطيع الفصل في القضايا كلها ، الاجتماعية والسياسية والاقتصادية والفكرية والثقافية ، بل أى قضية تتصل بالحياة الإنسانية في مختلف شعبها. وهو قضاء مبنى على علم ، فالإسلام علم وقضاء ، ولا يمكن أن يستغنى واحد منهما عن الآخر ، كما أوضحنا ذلك فيما سبق ، فلا قضاء بغير علم ، ولا علم لا يخدمه القضاء فيفصل فيه بين الأمور بموضوعية وأمانة. وهذا أيضا دعم لتكامل الإسلام وشموليته لكل ما له علاقة بالإنسان ، وهو ما يؤكد قول الإمام المؤسس رحمه الله عن الإسلام : إنه نظام شامل يتناول مظاهر الحياة جميعا .", "٤ - « الإسلام مادة وثروة أو كسب وغنى » أ - الإسلام مادة وثروة :", "* المادة هي : كل شئ يكون مددا لغيره .", "- وكل جسم ذى امتداد ووزن ويشغل حيزا من الفراغ.", "- ومادة الشئ أصوله وعناصره التي يتكون - حسية كانت أو معنوية - كمادة الخشب ، ومادة البحث العلمي .", "- ومواد القانون : الجمل التي تتضمن أحكامه. والمقصود بأن الإسلام مادة أنه ليس معنويات فقط ، وإنما هو إلى جانب ذلك ماديات ، لأن الحياة البشرية لا تصلح ولا تستقيم إلا بالاثنين معا ، بل لا تتم الحياة ولا تكون إلا بهما ، والإسلام دين الحياة . وإذا كانت المادة هي الموجودات غير العقلية أى تقابل العقلانيات فإن الإسلام كذلك ماديات وعقلانيات معا ، وإنما كان ذلك لأن الحياة البشرية لا تستقيم"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0038.png"}, {"n": 39, "paras": ["إلا بهما معا ، والإسلام دين الحياة كما قلنا أو أفضل منهج للحياة. وإذا كانت المادة هي الأصول والعناصر التي تتكون منها الأشياء حسية كانت أو معنوية ، فإن الإسلام في مجمله هو عناصر الحياة البشرية وأصولها ، بمعنى أنها لا تستغنى عنه فتكون حياة نافعة للناس ، مستقيمة يرضى الله سبحانه وتعالى عنها ، ويجازى عليها أحسن الجزاء . وإذا كانت الحياة الإنسانية تقوم على المادة والروح فإن الإسلام ليس روحانيات فقط ، وإنما يعنى كذلك بالجانب المادى من الإنسان ومن حياته ويوجهه أحسن التوجيه .", "* وأما أن الإسلام ثروة : فإن الثروة في اللغة هي : الكثير من المال والناس ، وقد جاء هذا المعنى في الحديث الشريف « ما بعث الله نبيا من بعد لوط إلا في ثروة من قومه » . والثروة في علم الاقتصاد هي : الأموال القابلة للتملك والتقويم المحدودة الكمية . وإذا قيل : الثروة القومية فإنها تعنى مجموعة القوى المنتجة في الدولة - كما رأى ذلك مجمع اللغة العربية بمصر . وفي تفصيل أكثر لمعنى الثروة في الاقتصاد يقال ، إن الثروة نوعان : الثروة الفردية : وتعنى الموارد الصالحة لإشباع الحاجات سواء أكانت سلعا مادية أم حقوقا قبل الآخرين . والثروة على مستوى المجتمع : وتعنى الموارد الطبيعية والسلع المملوكة ملكية جماعية كالمرافق العامة والطرق والمناجم وغير ذلك ... وقد تكون الثروة في بعض الاستعمالات مادية كرأس المال مع فارق بينهما هو أن الثروة تعطى معنى القابلية للإشباع في حين يركز رأس المال على الطاقة"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0039.png"}, {"n": 40, "paras": ["الإنتاجية للرصيد من الأشياء ذات القيمة الإقتصادية . ومعنى أن الإسلام ثروة هو أنه غنى يحقق الإشباع لحاجات الفرد والمجتمع المادية والمعنوية والبدنية والروحية والعقلية ، فهو ثروة لا تعدلها ثروة في هذا المجال، ويرعى هذه الثروة ويطالب بالمحافظة عليها وتنميتها وتوجيهها لخدمة الفرد والمجتمع ، سواء أكان ذلك على مستوى الفرد أم على مستوى المجتمع . ولعل في هذه النظرة الشاملة الواعية للثروة ما يرد على أولئك الذين يتهمون الأديان عموما والإسلام خصوصا بأنه يقوم على الزهادة والعزوف عن كل ما هو مادى ، لأن تلك أفكار شائهة إن صدقت على دين أو مذهب فلن تصدق على الإسلام أبدا ، لأن الإسلام نظام يتناول مظاهر الحياة جميعا ، ولا شك أن من مظاهر الحياة تلك الأمور المادية والثروات والموارد والطاقات ، فلابد أن يكون الإسلام شاملا لها جميعا ومنظما وموجها لأهدافها ووسائلها . وما أظن اتهام بعض الأديان بالترهد والابتعاد عن متع الحياة يتجاوز أن يكون اتهاما لا يملك دليلا قويا ، وذلك أن الأديان السماوية المعروفة التي جاءت من عند الله سبحانه لم يلغ فيها الجانب المادى من الحياة ، وكيف يلغى ولا تستقيم الحياة إلا به ؟. وبالتالي فلا يمكن تصور أن دينا من الأديان قد ألغى الثروة أو أهملها . والإسلام مادة وثروة بمعنى أنه يقيم الوزن الصحيح لكل ما هو مادى في حياة الإنسان ويوظف الثروة في أحسن ما توظف فيه لصالح الحياة الإنسانية كلها . ب - الإسلام كسب وغنى :", "* الكسب هو : ما يتحراه الإنسان مما فيه اجتلاب نفع وتحصيل حظ ككسب المال . وقد يقال : فيما يظن الإنسان أنه يجلب منفعة ثم تستجلب به مضرة ، وفى الحديث الشريف سئل النبي ﷺ : أى الكسب أطيب ؟ قال : « عمل الرجل بيده » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0040.png"}, {"n": 41, "paras": ["كما روى عنه ﷺ أنه قال : « إن أطيب ما يأكل الرجل من كسبه وإن ولده من كسبه » والكسب : يدخل فيه - كذلك - ما يتحراه الإنسان من مكاسب أخروية. ولعلماء الاقتصاد تعريف الكسب هو : ما يحصل عليه الفرد من مال عن طريق العمل دون الاستعانة برأس المال . ومعنى أن الإسلام كسب أنه يأمر الإنسان بالعمل والكسب ، ويطالبه بألا يعيش عالة على سواه ، وذلك أن الإسلام يشرف العمل ويرفع من قدره ومن قدر العاملين ويؤكد أن أنبياء الله صلوات الله عليهم وسلامه كانوا عمالا أصحاب حرف . والإسلام كسب بمعنى أن في الأخذ به والتزام منهجه ونظامه اجتلاب النفع للإنسان في الدنيا والآخرة ، ولا يسمح الإسلام لأحد بأن يقعد عن العمل والكسب منتظرا أن تمطر السماء عليه ذهبا أو فضة ، كما وردت هذه الكلمة الحكيمة على لسان عمر بن الخطاب رضى الله عنه ، وإنما يوجب على الإنسان أن يعمل وأن يتقى الله في علمه وأن يحسن عمله ويجوده ويكسب منه ما ينفعه في دنياه وفي آخرته ، وهذا - أيضا - يؤكد أن الإسلام نظام يتناول مظاهر الحياة كلها .", "* وأما أن الإسلام غنى : فلأن الغنى يتناول معاني ثلاثة هي : غنى ، عن كل الحاجات ، وليس ذلك إلا لله سبحانه وتعالى فهو الغنى بهذا المعنى للغنى بل هو الغنى وحده بهذا المعنى وغنى ، عن بعض الحاجات والمشار إليه في قوله تعالى : ﴿ ووجدك عائلا فأغنى ﴾ (١) ومنه قول الرسول ﷺ : « الغنى غنى النفس » أي الاستغناء عن بعض الحاجات .", "(١) سورة الضحى : ٨."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0041.png"}, {"n": 42, "paras": ["وغنى ، بمعنى كثرة المقتنيات لدى الإنسان . الإسلام غنى بهذا المعنى ينضم إلى أنه كسب كما أوضحنا آنفا ، وإلى أنه مادة وثروة كما قدمنا ، وكل ذلك يدعم شمول الإسلام لهذه المفردات ، ويؤكد أنه يتناول بالتنظيم الدقيق كل مظاهر الحياة الإنسانية . وكل ما يدعى على الإسلام مما يخالف ذلك هو مجرد دعاوى توجهها الأحقاد عند الراغبين في تشويه الإسلام منهجه ونظامه ، دعاوى لا يقوم عليها دليل عقلى أو نقلى ولا يستطيع أن يساندها شئ من تاريخ ممارسة الإسلام للحياة في تلك الفترة الطويلة نسبيا التي عايش فيها الإسلام مظاهر الحياة يحكمها بمنهج الله ونظامه . ومن سوء حظ هذه الدعاوى أنها ستظل أبدا دعاوى لافتقارها دائما إلى الأدلة والبراهين التي لم يكن لها وجود في الماضى ولا يمكن أن يكون لها وجود في الحاضر أو المستقبل ، طالما أن الإسلام هو الإسلام . ه - « الإسلام جهاد ودعوة أو جيش وفكرة » أ - الإسلام جهاد ودعوة : الجهاد والمجاهدة : هو استفراغ الوسع في مدافعة العدو ، وهو ثلاثة أنواع : الأول : مجاهدة العدو الظاهر ، والثاني : مجاهدة العدو المستتر « الشيطان » . والثالث : مجاهدة النفس . وكلها تدخل في قوله تعالى : ﴿ وجاهدوا في الله حق جهاده ﴾ (١) . وفي قوله سبحانه : ﴿ وجاهدوا بأموالكم وأنفسكم في سبيل الله ﴾ (٢) .", "(١) سورة الحج : ٧٨ .", "(٢) سورة التوبة : ٤١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0042.png"}, {"n": 43, "paras": ["وقد قال رسول الله ﷺ : « جاهدوا أهواءكم كما تجاهدون أعداءكم » . والمجاهدة تكون باليد واللسان ، قال رسول الله ﷺ : « جاهدوا الكفار بأيديكم وألسنتكم » .", "* ومعنى أن الإسلام جهاد أنه مجاهدة للشيطان وللنفس التي تأمر بالسوء فضلا عن كونه جهادا لكل عدو من أعداء الإسلام . وهذا الجهاد بأنواعه الثلاثة ماض إلى يوم القيامة لا يسقط أبدا حتى تقوم الساعة ، لأن الله سبحانه أمر به كما أوضحت ذلك الآيات التي قدمنا ، ولأن الإسلام دين الحق ولابد أن يتصدى له أعداء الحق في كل زمان ومكان ولا مدافعة لهؤلاء الأعداء إلا بالجهاد - وقد أوسعنا موضوع الجهاد بحثا في كتابنا فقه الدعوة إلى الله(١) فليرجع إليه من أراد أن يلم بأطرافه . وإذا قعد المسلمون عن الجهاد في سبيل الله بأنواعه الثلاثة فقد أثموا وعصوا الله لأنه أمرهم به ، وقد ضعفوا وذلوا وطمع فيهم أعداؤهم وتخطفوهم من كل جانب ، كما هو مشاهد اليوم ، فإن هذا الضعف الذي عليه العالم الإسلامي ليس له سبب أهم من ترك الجهاد في سبيل الله ، وتعطيل تلك الفريضة الفاعلة الداعية إلى العلم والعمل والصبر .", "* والإسلام دعوة : وذلك أن الإسلام دعوة إلى الله إلى الحق ، إلى عبادة الله وحده وفق ما شرع. ودعوة إلى الخير والهدى ، ودعوة إلى القيام بكل معروف والانتهاء عن كل منكر. الإسلام يوظف كل مسلم ومسلمة للدعوة إلى الله ، ما دام هذا الداعي على بصيرة بما يدعو إليه ، فالدعوة واجب كل مسلم قادر عليها يملك البصيرة بما يدعو إليه . يفهم ذلك من قول الله تعالى مخاطبا نبيه ﷺ : ﴿ قل هذه سبيلي", "(١) الفصل الرابع من الباب الأول - نشر دار الوفاء."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0043.png"}, {"n": 44, "paras": ["أدعو إلى الله على بصيرة أنا ومن اتبعني (١) فهي توجب على كل من اتبع محمدا ﷺ من رجل أو امرأة أن يدعو إلى الله ، فإن لم يفعل فلم يتخذ سبيل رسول الله ﷺ سبيلا له . والجهاد نفسه بأنواعه الثلاثة موظف من أجل الدعوة ، فجهاد النفس لتتخلص من أهوائها وتستقيم على الحق وعلى ما أمر الله به دعوة إلى الله تعالى : ﴿وأما من خاف مقام ربه ونهى النفس عن الهوى فإن الجنة هي المأوى﴾ (٢) وجهاد الشيطان وهو العدو المبين لكل الناس من صميم الدعوة قال الله تعالى : ﴿يأيها الذين آمنوا ادخلوا في السلم كافة ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين ﴾ (٣) . وجهاد العدو دعوة إلى الله كذلك ، لأن العدو هنا عدو الحق وعدو الله وعدو الإسلام والمسلمين ، قال الله تعالى : ﴿إنما المؤمنون الذين آمنوا بالله ورسوله ثم لم يرتابوا وجاهدوا بأموالهم وأنفسهم في سبيل الله أولئك هم الصادقون﴾ (٤) . وجهاد العدو يتضمن نشر الدعوة إلى الإسلام فيمن قبلها من الناس إذ له ما للمسلمين وعليه ما عليهم ، ومن أبى قبولها فإن كان من أهل الكتاب ترك وما يدين على أن يدفع الجزية إن كان يعيش في كنف الدولة الإسلامية ، فإن أبى قوتل بعد إنذاره ، وإن كان من غير أهل الكتاب أُنذر ثم قوتل ، وإنما كان الإنذار في هاتين الحالتين لأن الإسلام لا يأخذ أحدا على غرة ولا يطعن من الخلف ولا يكره أحداً على الدخول فيه.", "(١) سورة يوسف : ١٠٨.", "(٢) سورة النازعات : ٤٠.", "(٣) سورة البقرة : ٢٠٨.", "(٤) سورة الحجرات : ١٥."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0044.png"}, {"n": 45, "paras": ["ب - والإسلام جيش وفكرة :", "* الجيش بلغتنا المعاصرة هو القوات البرية المسلحة التي تخضع للتنظيم الدائم، ثم أصبح الجيش يضم القوات الجوية والبحرية . وكان عمر بن الخطاب رضى الله عنه أول من وضع ديوانا ونظاما للجند في الإسلام ، وكان الجيش على عهد النبي ﷺ يضم كل مسلم قادر على القتال في سبيل الله . ولذلك فإن الإسلام بكل أفراده الذين يدينون به يمثل جيشا له كل مقومات الجيش وكل اختصاصاته ، ويجمع كل قادر على القتال ، ويتجاوز عن أصحاب الأعذار . ومعنى ذلك أن الإسلام قوة لأن الجيش قوة ، لكن الإسلام يجعلها قوة موظفة للحق وليست قوة عدوان أو بغى أو توسع في الأرض على حساب الآخرين ، إنه قوة تحمى الإنسان من نفسه ومن شيطانه ومن عدوه الذي يعتدى عليه . والجيش في الإسلام لا يكون التجنيد فيه إجباريا إلا لضرورة ، لأن الجهاد في سبيل الله عبادة يتقرب بها الإنسان إلى ربه ويجاهد في سبيله لتكون كلمة الله هي العليا محتسبا الأجر والثواب عند الله سبحانه إلا إذا دعت ضرورة إلى حشد كل القادرين على القتال بأمر الحاكم المسلم . إن الإسلام بهذا المعنى جيش قوى يحمى المبدأ ويحرس القيم الخلقية الفاضلة التي جاء بها الإسلام ، ويعمل على نشرها وإذاعتها في الناس ، ويحارب الشر والباطل وكل منكر ، لأن تلك آفات تضر بالمجتمع وتسئ إليه . يقوم الجيش الإسلامي بهذا وذاك ليمكن الناس من الحياة الكريمة اللائقة بالإنسان ، المتبعة للمنهج الذي نظم به الإسلام كل شأن من شئون الحياة الدنيا والآخرة . والجيش الإسلامي يرد عن الأمة المسلمة أعداءها الطامعين فيها المعتدين عليها"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0045.png"}, {"n": 46, "paras": ["سواء أكان العدوان ماديا يقتطع الأرض ، أو معنويا يتحدى المنهج والنظام إن كل هؤلاء الأعداء يجب على الجيش المسلم أن يتصدى لهم. وهذا هو معنى أن الإسلام جيش .", "* الإسلام فكرة : الفكر والفكرة في اللغة : إعمال النظر في الشيء ، والفكرة : قوة مطرقة للعلم إلى المعلوم ، الفكر : ظاهرة عقلية تنتج عن عمليات التفكير القائم على الإدراك والتحليل والتعميم ، ويتميز الفكر عن العاطفة التي تصدر عن ميل انفعالي ، كما يتميز عن الإرادة التي ترمى إلى ترجيح كفة الميول القائمة على أحكام تقويمية . والإسلام فكرة تقوم على التوحيد ، توحيد الله سبحانه وتعالى إلها ورباً ، والإيمان به وبملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره . فكرة توجب على معتنقها أن يشهد أن لا إله إلا الله وأن محمدا رسول الله ، ويقيم الصلاة ويؤتى الزكاة ويصوم رمضان ويحج البيت إن استطاع إليه سبيلا . والإسلام فكرة توجب على معتنقها العدل والإحسان والأمر بالمعروف والنهي عن المنكر والجهاد في سبيل الله لتكون كلمة الله هي العليا ، والأخذ بمنهج الإسلام في كل شيئ في الحياة . الإسلام فكرة بمعنى أنه المنهج الذي يتناول بالتنظيم كل مظاهر الحياة الإنسانية - كما أوضحنا - وهذه الفكرة يجب أن تبلغ للناس في كل زمان ومكان، ومن أجل إبلاغها لابد أن توجد دعوة وعمل وتنظيم وجهاد بأنواعه الثلاثة التي تحدثنا عنها آنفا. ومعنى هذا أن توظف طاقات الأفراد ، وتوظف القوة « الجيش » المصاحبة"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0046.png"}, {"n": 47, "paras": ["للفكرة من أجل بلوغ هذا الهدف وهو دعوة الناس إلى عبادة الله وحده لا شريك له وفق ما شرع وأوحى إلى خاتم أنبيائه محمد ﷺ .", "٦ - « الإسلام عقيدة صادقة وعبادة صحيحة سواء بسواء » . أ - الإسلام عقيدة صادقة :", "* العقيدة هي الاعتقاد ، وهي المبدأ الذي يتمسك به الإنسان ويؤمن بصوابه. والإسلام عقيدة : بمعنى أنه مبدأ يشتمل على مفردات أساسية تتناول كل مظاهر الحياة الإنسانية ، يجب على المسلم أن يؤمن بها ويعتقد في صدقها وصوابها ، ويموت في سبيلها وعليها. وأساس العقيدة الإسلامية الاعتقاد في وجود الله ووصفه بصفاته وتسميته بأسمائه وتوحيده إلهاً ورباً ...، ويتفرع عن ذلك التوحيد مفردات كثيرة منها :", "- الإيمان بالملائكة والكتب والرسل أى الاعتقاد بوجودهم وبأنهم من عند الله سبحانه وبأن لهم وظائف أدوها أو يؤدونها ، والإيمان بصدقهم وأمانتهم وأن الله أرسلهم لصالح البشرية في معاشها ومعادها،", "- والإيمان باليوم الآخر وبكل ما فيه ،", "- والإيمان بالقضاء والقدر خيره وشره ،", "- والنطق بالشهادتين « لا إله إلا الله - محمد رسول الله » والعمل بمقتضاهما ، مع ضرورة تنفيذ أركان الإسلام الأخرى من صلاة وصيام … ألخ .", "- وممارسة العدل والإحسان ،", "- وممارسة الأمر بالمعروف والنهي عن المنكر ،"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0047.png"}, {"n": 48, "paras": ["- وممارسة الجهاد في سبيل الله ،", "- والالتزام بمنهج الإسلام في الحياة ونظامه لها. فالإسلام عقيدة تشمل كل ذلك ، وهي عقيدة صادقة في كل ما اشتملت عليه ، وآية صدق هذه العقيدة أنها من عند الله وأنها صالحة لكل زمان ومكان وأنها لا يأتيها الباطل من بين يديها ولا من خلفها ، وأن من تمسك بها حقق صالح معاشه ومعاده ، مهما تطاول الزمان واختلف المكان وزادت المتغيرات. والإسلام عقيدة صادقة جُرب صدقها في التاريخ حيث آمن بها وعمل بمقتضاها المسلمون في أطوار تاريخية عديدة دون تساهل أو إخلال بشيء من مفرداتها ، فسادوا وعزوا وملأوا الدنيا بها عدلا ورخاء ، فلها من رصيد التجارب البشرية حظ وفير .", "ب - والإسلام عبادة صحيحة :", "* الإسلام عبادة بمعنى أنه يقوم على عبادة الله وحده لا شريك له وفق ما شرع لرسوله الخاتم محمد ﷺ . والعبادة : أنماط من الأعمال والسلوك في الفعل والترك . والأصل فيها أن تكون تعبيرا عما في قلب المسلم من اعتقاد . وهذه العبادة - بمعناها العام في الإسلام يدخل فيها مع الفرائض الأعمال العادية إذا قصد بأدائها وجه الله - أو بمعنى ما تشتمل عليه من مفردات أوجب الإسلام تنفيذها وهي العبادة الصحيحة أى المبرأة من كل عيب الخالية من أى انحراف التي لا تقبل الأباطيل . وإنما كانت العبادة في الإسلام هكذا لأنها من عند الله ، ولأنها قد فُصّلت في شريعة الإسلام تفصيلا دقيقا يتناول كل مرافق الحياة الإنسانية ، وكل ما يجب أن يؤديه الإنسان من واجبات أو يمارسه من حقوق."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0048.png"}, {"n": 49, "paras": ["ولأن بعض القائلين قد يفصلون بين العقيدة الصادقة والعبادة الصحيحة فيرون أن العقيدة أمر قائم بذاته لا تترتب عليه عبادة أو عمل أو سلوك ، فإن الإمام المؤسس رحمه الله أراد أن ينفى هذا الفهم الخاطئ ، وينبه هؤلاء وأمثالهم من الغافلين ، فأكد أن الإسلام كما هو عقيدة صادقة فإنه في ذات الوقت عبادة صحيحة منبثقة عن تلك العقيدة الصادقة سواء بسواء . والمعنى الذي أراد الإمام أن يؤكده هو أن العقيدة مهما كانت صادقة فإنها لن تجدى إذا لم تعبر عنها العبادة الصحيحة وفق ما شرع الله . كما أن العبادة مهما بالغ فيها العباد فإنها إذا لم تكن نابعة عن العقيدة الصادقة فإنها هباء لا تجدى شيئا . هذا هو معنى : سواء بسواء . والله أعلم ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0049.png"}, {"n": 50, "paras": ["مقدمة تمهيد الفصل الأول: مفهوم التنمية البشرية المبحث الأول: تعريف التنمية البشرية المبحث الثاني: أهداف التنمية البشرية المبحث الثالث: أهمية التنمية البشرية الفصل الثاني: مقومات التنمية البشرية المبحث الأول: التعليم والتدريب المبحث الثاني: الصحة والرعاية الاجتماعية المبحث الثالث: التكنولوجيا والابتكار الفصل الثالث: تحديات التنمية البشرية المبحث الأول: الفقر والبطالة المبحث الثاني: التغيرات المناخية المبحث الثالث: الأزمات الاقتصادية والسياسية"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0050.png"}, {"n": 51, "paras": ["الأصل الثاني من أصول الفهم", "يقول الإمام المؤسس : « والقرآن الكريم والسنة المطهرة مرجع كل مسلم في تعرف أحكام الإسلام » « ويفهم القرآن الكريم طبقا لقواعد اللغة العربية من غير تكلف ولا تعسف ، ويرجع في فهم السنة المطهرة إلى رجال الحديث الثقات »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0051.png"}, {"n": 52, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0052.png"}, {"n": 53, "paras": ["أ - تعريف أحكام الإسلام : يقرر الإمام المؤسس في هذا الأصل أن أحكام الإسلام جميعها ، تعرف من الكتاب الكريم والسنة النبوية المطهرة ، بل هما مرجع كل مسلم يريد أن يعرف هذه الأحكام . والأحكام جمع حكم ، وهو القضاء على شئ ما بأنه كذا ، أو بأنه ليس بكذا ، سواء ألزمت غيرك بهذا الحكم أم لم تلزمه به . وأحكام الإسلام هي الأحكام الشرعية وهي خطاب الشارع المفيد فائدة شرعية كطلب فعل مجزوم به فهو الواجب الشرعي أو غير مجزوم به هو المندوب ، أو طلب ترك على جهة الجزم فهو الحرام ، أو على غير جهة الجزم فهو المكروه. وقد يكون الحكم الشرعي متعلقا بالتخيير بين الفعل والترك فهو المباح. ومصادر الأحكام الإسلامية أو الشرعية وأصولها هي : القرآن الكريم والسنة النبوية المطهرة ، وأما الإجماع فمستنده الكتاب والسنة فهو غير خارج عنهما ، وأما القياس والاستدلال ( الاجتهاد ) فيرجعان إلى التمسك بالنصوص من الكتاب والسنة أو إلى الإجماع وهو راجع إلى الكتاب والسنة . فالأحكام الإسلامية على كل مستوى من مستوياتها يرجع فيها إلى الكتاب والسنة ، وذلك أن القرآن الكريم أوضح بغير أدنى لبس أسس العقيدة ، وبين قواعد الشريعة وأصولها ، وذكر الأمور الكلية المتعلقة بالدين مبادئه وأسسه ، سواء أكان ذلك متعلقا بالإيمان والمعتقد أم متعلقا بالإسلام والعمل والسلوك. والسنة النبوية الصحيحة هي التي أخبرت عن القرآن وفصلت مجمله وفسرت ما يحتاج منه إلى تفسير."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0053.png"}, {"n": 54, "paras": ["والقرآن والسنة ما تركا من خير إلا وأمرا به ، وما تركا من شر إلا ونهيا عنه والإجماع والقياس والاجتهاد تدور دائما في فلك الكتاب والسنة فإن لم تدر مع الكتاب حيث دار ، فلا يرجع إليها في معرفة أحكام الإسلام . تلك أوليات أو بدهيات لا ينكرها أو يجادل فيها إلا جاهل أو قاصر في الفهم أو سيئ النية حاقد على الإسلام . أما القرآن الكريم : فقد قال بعض العلماء : إنما سمى الكتاب المنزل من الله على محمد ﷺ قرآنا من بين كتب الله ، لكونه جامعا لثمرة كتبه ، بل لجمعه ثمرة جميع العلوم كما أشار تعالى إليه بقوله : ﴿ ... ولكن تصديق الذي بين يديه وتفصيل كل شئ وهدى ورحمة لقوم يؤمنون ﴾ (١) ، وبقوله سبحانه : ﴿ ونزلنا عليك الكتاب تبيانا لكل شئ وهدى رحمة ... ﴾ (٢) . ب - حجية القرآن الكريم : وأما حجية القرآن الكريم ، فقد اتفق علماء الإسلام على أن القرآن الكريم حجة في التعرف على الدين الإسلامى أركانه وأصوله وكثير من فروعه. وبيان ذلك كما قال الإمام الشافعي رضى الله عنه : أن النبي ﷺ كان مكلفا من قبل الله تبارك وتعالى بإلقاء ما أنزل عليه من القرآن على طائفة تقوم الحجة القاطعة بقولهم ، ومن تقوم الحجة القاطعة بقولهم لا يتصور عليهم التوافق على عدم نقل ما سمعوه منه » . وقال ابن حزم : « ولما تبين بالبراهين والمعجزات أن القرآن هو عهد الله إلينا، والذي ألزمنا الإقرار به ، والعمل بما فيه ، وصح بنقل الكافة الذي لا مجال للشك فيه أن هذا القرآن هو المكتوب في المصاحف المشهور في الآفاق كلها", "(١) سورة يوسف : ١١١.", "(٢) سورة النحل : ٨٩."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0054.png"}, {"n": 55, "paras": ["وجب الانقياد لما فيه فكان هو الأصل المرجوع إليه لأننا وجدنا فيه : ﴿ ما فرطنا في الكتاب من شيء ﴾ فما في القرآن من أمر أو نهى فواجب الوقوف عنده(١) . ثم يواصل ابن حزم موضحا حجية القرآن الكريم قائلا : « ولا خلاف بين أحد من الفرق المنتمية إلى المسلمين من أهل السنة والمعتزلة والخوارج والمرجئة والزيدية في وجوب الأخذ بما في القرآن وأنه هو المتلو عندنا نفسه . وإنما خالف في ذلك قوم من غلاة الروافض هم كفار بذلك مشركون عند جميع أهل الإسلام »(٢) . والقرآن الكريم أول أصل من أصول التشريع الإسلامي ، وهي حجة علماء التوحيد والفقه ، بل حجة علماء اللغة العربية ، ما يمارى في ذلك أحد . ولكن القرآن الكريم يفهم طبقا لقواعد اللغة العربية من غير تكلف ولا تعسف ، ويرجع إلى علوم اللغة العربية في فهمه وهي : علم النحو . وعلم الصرف . وعلم فقه اللغة . وعلم البيان . وعلم المعاني . وعلم البديع ، وغيرها كالشعر العربي وأمثال العرب … الخ . ودراسة هذه العلوم هي التي تعطى لمن أراد أن يفهم القرآن ويحتج به قدرة على فهمه من غير تكلف ولا تعسف ، وبخاصة إذا استصحب معه بعض كتب التفسير المعتمدة .", "(١) ابن حزم : الإحكام : ٩٠/١ نشر دار الحديث بالقاهرة ١٤٠٤ ه - ١٩٨٤م .", "(٢) المرجع السابق ٩١/١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0055.png"}, {"n": 56, "paras": ["وهذا يعنى أن القرآن الكريم يجب أن يكون مرجع كل مسلم في التعريف على أحكام الإسلام في العقائد والعبادات والمعاملات والحلال والحرام وما يجوز وما لا يجوز ، بل هو على وجه الوجوب لا الندب مرجع كل مسلم في الأخلاق والآداب .", "* وأما السنة النبوية المطهرة : فهي مجموع أقوال الرسول ﷺ وأفعاله وتقريراته وقد لقيت من عناية العلماء اهتماما بالغا ، أمكن به أن تصلنا صحيحة النسبة إليه ﷺ . مبرأة من الدس والوضع والكذب ، مجموعة في كتب صحيحة مسندة جامعة أجمعت الأمة الإسلامية على قبولها والأخذ بها ، وقد اشتهر من هذه الكتب عدد كبير في مقدمته :", "- الكتاب الجامع الصحيح للإمام البخاري المشهور بصحيح البخاري .", "- والكتاب الجامع الصحيح للإمام مسلم المشهور بصحيح مسلم .", "- والكتاب الجامع الصحيح للإمام الترمذى المشهور بسنن الترمذى أو صحيح الترمذى .", "- والكتاب الجامع الصحيح للإمام أبي داود المشهور بسنن أبي داود .", "- والكتاب الجامع الصحيح للإمام النسائي المشهور بسنن النسائي .", "- والكتاب الجامع الصحيح للإمام ابن ماجه المشهور بسنن ابن ماجه .", "- وموطأ الإمام مالك .", "- ومسند الإمام أبي حنيفة .", "- ومسند الإمام الشافعي .", "- ومسند الإمام أحمد بن حنبل ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0056.png"}, {"n": 57, "paras": ["- ومسند الإمام الدارمي . وما لا يحصى هنا من كتب السنة الصحيحة ، والكتب التي جمعت الأحاديث الموضوعة المكذوبة على رسول الله ﷺ . ج - حجية السنة النبوية المطهرة : والسنة النبوية المطهرة حجة شرعية في فهم أحكام الإسلام ، فهي تعتبر مرجعا مفصلا ومفسرا لكل مسلم في التعرف على أحكام الإسلام بعامة ، وعلى الأحكام التي أجملها القرآن الكريم . وقد أجمع أهل السنة والجماعة والصحابة والتابعون والسلف الصالح وجميع علماء الإسلام على مر العصور المتتالية أن السنة المطهرة هي الأصل الثاني بعد القرآن الكريم ، وأن واجب كل مسلم أن يرجع إليها للتعرف على أحكام الإسلام . ولم ينازع في ذلك إلا من لا يعتد برأيه لشذوذ أو علة ، أو شطط في الفكر أو فساد في العقيدة ، أو حقد على الإسلام والمسلمين . ومع هذا فقد شغب هؤلاء على المسلمين ووجهوا للسنة اتهامات باطلة كلها واضحة البطلان ، وأقوى ما ذهبوا إليه - على ضعفه - هو تضعيف في سند أو شذوذ في متن ، وهي قضية عولجت وميز صحيحها من سقيمها من مئات السنين على أيدى جهابذة علم الحديث دراية ورواية . والاحتجاج بالسنة على أنها المرجع الثانى في التعرف على أحكام الإسلام - كما أن القرآن الكريم هو المرجع الأول في ذلك - أصل من الأصول التي أجمعت عليها الأمة الإسلامية ، فالسنة هي المصدر الثاني للتشريع الإسلامي ، ويجب الإيمان بذلك ومنكره كافر لأنه ينكر معلوما من الدين بالضرورة ، حتى إن العلماء قالوا : إن من أنكر عدد ركعات الفرائض فقد أنكر معلوما من الدين بالضرورة ، فكيف بمن ينكر السنة أو لا يحتج بها ؟ وهي التي علمنا منها عدد"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0057.png"}, {"n": 58, "paras": ["ركعات الفرائض. قال ابن حزم : « ولما بينا أن القرآن هو الأصل المرجوع إليه في الشرائع نظرنا فيه فوجدنا فيه إيجاب طاعة ما أمرنا به رسول الله ﷺ ، ووجدناه عز وجل يقول فيه واصفا لرسوله ﷺ ﴿وما ينطق عن الهوى إن هو إلا وحي يوحى﴾(١) فصح لنا بذلك أن الوحى ينقسم من الله عز وجل إلى رسوله ﷺ إلى قسمين : أحدهما : وهو متلو مؤلف تأليفا معجز النظام وهو القرآن . والثاني : وحى مروى منقول غير مؤلف ولا معجز النظام ولا متلو كذلك لكنه مقروء وهو الخبر الوارد عن رسول الله ﷺ وهو المبين عن الله عز وجل مراده منا ، قال الله تعالى : ﴿ لتبين للناس ما نزل إليهم ﴾(٢) . ووجدناه تعالى قد أوجب طاعة هذا الثانى كما أوجب طاعة القسم الأول الذى هو القرآن ولا فرق ، فقال تعالى : ﴿ أطيعوا الله وأطيعوا الرسول ﴾(٣) . ثم قال الإمام المؤسس في تعقيبه على السنة « ويرجع في فهم السنة المطهرة إلى رجال الحديث الثقات » وهم علماء الحديث الذين جمعوا السنة النبوية وأشهرهم البخارى ومسلم والترمذى والنسائى وابن ماجه وأبو داود ، وموطأ مالك ومسانيد أبي حنيفة والشافعي وأحمد بن حنبل رضى الله عنهم.", "(١) سورة النجم : ٣ - ٤. (٢) سورة النحل : ٤٤ .", "(٣) سورة النساء : ٥٩."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0058.png"}, {"n": 59, "paras": ["الأصل الثالث من أصول الفهم", "« للإيمان الصادق والعبادة الصحيحة والمجاهدة نور وحلاوة يقذفها الله في قلب من يشاء من عباده . ولكن الإلهام والخواطر والكشف والرؤى ليست من أدلة الأحكام الشرعية ولا تعتبر إلا بشرط عدم اصطدامها بأحكام الدين ونصوصه »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0059.png"}, {"n": 60, "paras": ["- أن يكون الميت قد أوصى بثلث ماله أو أقل، فإن أوصى بأكثر من الثلث، فلا تنفذ الزيادة إلا بإجازة الورثة.", "- أن يكون الموصى له غير وارث، فإن كان وارثاً، فلا تنفذ الوصية إلا بإجازة بقية الورثة؛ لقول النبي صلى الله عليه وسلم: \"لا وصية لوارث\".", "- أن يكون الموصى له ممن يصح تمليكه، فلا تصح الوصية لجهة لا تملك، كالمعاصي والبدع.", "- أن لا تكون الوصية في معصية، كأن يوصي ببناء كنيسة أو طباعة كتب ضلالة، فلا تنفذ؛ لأنها إعانة على الإثم والعدوان.", "- أن يكون الموصى له معيناً، أو جهة عامة معلومة، كأن يوصي للفقراء أو لطلبة العلم."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0060.png"}, {"n": 61, "paras": ["إن التدقيق في الفرق بين أدلة الأحكام الشرعية واجب رئيسي في فقه الإسلام وفقه أدلته وأحكامه ، وإن التدقيق لا يدع مجالا أن يدعى على الإسلام ما ليس بصحيح ، ومن أجل هذا كان لابد لنا أن نفرق بين ما أثاره الإمام المؤسس من نور وحلاوة يقذفها الله في قلب من يشاء من عباده ، وبين الإلهام والخواطر والكشف والرؤى ، على النحو التالي : نور الإيمان الصادق : إذا قوى الإيمان في قلب مؤمن وترجمت عنه الأعمال ، وشفع بالإقبال على النوافل ودعم بتقوى الله حق تقواه فربما كان لبعض هؤلاء الصالحين في الدنيا كرامة من الله تجعل بعضهم ينظر بعين الله ويسمع بأذنه ويبطش بيده ويمشى برجله فيكون في ذلك من الموفقين المرضى عنهم . أقول إذا كان ذلك كذلك وكان لهؤلاء الصالحين الملتزمين نور وحلاوة يقذفها الله في قلوبهم ، وبدا للناس أنهم ممن تجرى على أيديهم محاسن الأعمال ، فإن ذلك - كما قال أسلافنا من العلماء لا يعدو أن يكون كرامة يظهرها الله على يد ظاهر الصلاح غير مدع للنبوة . وعلى الرغم من ذلك فليس من حق واحد من أصحاب هذه الكرامات أن يضيف إلى الدين شيئا أدنى شيء أو ينقص منه شيئا أدنى شيء ، أو أن يدعى لنفسه شيئا مما استأثر الله بعلمه . ومن رحمة الله بالمسلمين أنه لم يخل زمنا من أزمانهم على مر تاريخ الإسلام في هذه القرون الأربعة عشر من صالحين أتقياء متقيدين بالشريعة يجرى على أيديهم الخير ولو أقسم أحدهم على الله لأبره . إنهم هؤلاء في كل عصر علامات على أن المسلمين لا يزالون بخير ، وأن الخير حقا في محمد ﷺ وفي أمته إلى يوم القيامة ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0061.png"}, {"n": 62, "paras": ["إن هؤلاء الذين يقذف الله في قلوبهم نور الإيمان ويذيقهم حلاوة التوكل واليقين هم الذين تتقى بهم المكاره وتسد بهم الثغور وإذا حضروا لم يعرفوا وإذا غابوا لم يفتقدوا ويموت أحدهم وحاجته في نفسه لا يستطيع لها قضاء حياء من الله ومن الناس . هؤلاء الأولياء لله ليس لهم أبدا أن يتظاهروا بهذا الذي يجرى على أيديهم من خير واستجابة فضلا عن أن يدعوا أو يتبجحوا ، كما أنه ليس لأحد من المسلمين أن يتوسل بهم إلى الله أو يبنى مساجد تشتمل على مقابرهم ليزورها الناس أو تسمى المساجد بأسمائهم ، إن هذا غير جائز شرعا ، بل إن فاعله عاص آثم داخل في الشرك في بعض ما يعتقد أو يعمل والعياذ بالله من الشرك الخفى .", "ما لا يتخذ دليلا شرعيا . إن الإسلام حرر عقول الناس من هذه الأوهام والأباطيل والضلالات بأن أوضح بما لا يدع مجالا للشك أفعال الله وأفعال العباد ، وبذلك حارب الخرافة والدجل ومن يعتبرون أنفسهم وسطاء بين الله والناس ، ويدعون القدرة على منح الناس العفو والمغفرة ، أو منع الشر والضرر عنهم ، إن الإسلام وضع كل هؤلاء الناس وأتباعهم في دائرة الذين افتروا على الله الكذب ، فقال تعالى ﴿ فمن أظلم ممن افترى على الله كذبا ليضل الناس بغير علم إن الله لا يهدى القوم الظالمين﴾(١). وبعد فما مفردات هذه الأمور التي يفترى الناس فيها الكذب على الله ، ويرونها من الأدلة الشرعية وهي ليست كذلك ولا يمكن أن تسمو إلى ذلك ؟. إنها ما يدعونه من : الإلهام ،", "(١) سورة الأنعام : ١٤٤ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0062.png"}, {"n": 63, "paras": ["والخواطر ، والكشف ، والرؤى ، ولكل واحدة منها حديث وجيز يكشف عن أصلها وحقيقتها . أ - الإلهام الإلهام : إلقاء الشئ في الروع ، ويختص ذلك بما كان من جهة الله تبارك وتعالى وجهة الملأ الأعلى .", "- ويعبر عنه إسلاميا - أحيانا - بلمة الملك .", "- وأحيانا يعبر عنه بالنّفث في الروح . وعلماء الاجتماع يعرفون الإلهام CHARISMA ، بأنه صفة أو خاصة غير عادية تتحقق لدى الفرد ، فتجعل قدراته خارقة للعادة ، ويعنى هذا المصطلح من الناحية اللفظية « هبة الله » أى من ترسله العناية الإلهية لإنقاذ أمته ، وهو زعيم يتحلى بقوة خارقة وصفات نادرة وقدرات روحية . وهم في هذا التعريف يقتربون من كثير من صفات النبوة ، في حين أن النبوة نبوة وليست إلهاما . والملهم هو ذلك الذي يدعى أن الله ألهمه كذا أو كذا ، وليس أوحى إليه ، وقد يكون ذلك صحيحا ويكون من الملهمين الموفقين في أقوالهم وأعمالهم لما فيه من صلاح وتقوى . لكن هل يسوغ لنا أن نعتبر إلهاماته من الأدلة الشرعية فنأخذ بها ؟ اللهم .. لا . لأن الإلهام ليس من الأدلة الشرعية ، بل ولا يعتبر في حد ذاته دون أن يستدل به إلا إذا لم يتصادم مع أحكام الدين ونصوصه الشرعية ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0063.png"}, {"n": 64, "paras": ["ب - الخواطر : الخواطر : جمع خاطرة وهي الهاجس أو ما يتحرك في القلب من رأى ومعنى. والهاجس كل ما يحدث به الإنسان نفسه في صدره مثل الوسواس، والخاطرة كل ما يقع في خلد الإنسان أى « باله » وقد يخطر لأحد الناس من الصالحين ما يحدث به نفسه من قول أو عمل فيكون الواقع مصدقا لهذا الخاطر أو الهاجس ، وهذا دليل على صلاح الرجل وتقواه . ولكنه لا يجوز لنا ولا لصاحب الخاطر أن يتخذ من ذلك دليلا شرعيا بحال من الأحوال ، ولو فعل فإنه يفقد صفة الصلاح والتقوى ، ويدخل في زمرة الضالين المضلين ، ولو فعل ذلك أحد الناس لأدخل في دين الله ما ليس منه أو أخرج من دين الله ما هو منه ، وكلاهما كفر والعياذ بالله تعالى . ج - الكشف : والكشف كما عرفه علماء الاجتماع هو : إدراك العلاقات أو الظواهر التي لم تعرف من قبل ، ولكى يكون للكشف معنى إجتماعي يجب أن يتصل بالأنساق الموجودة والخاصة بالعقائد والمعرفة ، وبالتالى يندمج الكشف في الثقافة. وللكشف معنى صوفي خلاصته : أن أحد الناس من الصالحين يدعى أنه قد كشف له من المغيبات ما لم يكشف مثله للناس عادة . وهذا إن كان صالحا ظاهر الصلاح ملتزما بفرائض الإسلام مواظبا على الجمع والجماعات فلعل هذا يكون تكريما من الله تعالى . وإن كان من غير الصالحين الظاهري الصلاح فإنه من الدجاجلة المسمون بالعرافين أو الكهان أو المنجمين ، وهؤلاء قد نهى النبي ﷺ عن سؤالهم وإتيانهم. روى الإمام أحمد بسنده عن أبي هريرة رضى الله عنه أن النبي ﷺ قال : « من"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0064.png"}, {"n": 65, "paras": ["أتى عرافا أو كاهنا فصدقه بما يقول فقد كفر بما أنزل على محمد » وروى أحمد بسنده عن عائشة رضى الله عنها قالت : سئل رسول الله ﷺ عن الكهان فقال : ليسوا بشيء ، فقالوا يا رسول الله إنهم يحدثون أحيانا بشيء يكون حقا ؟ فقال رسول الله ﷺ : « تلك الكلمة من الحق يخطفها الجنى فيقرها في أذن وليه فيخلطون فيها أكثر من مائة كذبة »(١) . والكشف كالإلهام والخواطر ليس من أدلة الأحكام الشرعية .", "د - الرؤى : الرؤى : جمع رؤية وهى إدراك المرئى ، وذلك أنواع بحسب قوى النفس الإنسانية وما ترى : الأول : إدراك بالحاسة وما يجرى مجراها نحو : ﴿ لترون الجحيم ثم لترونها عين اليقين ﴾(٢) . والثاني : إدراك بالوهم والتخيل نحو : أرى أن زيدا منطلق ، والثالث : إدراك بالتفكير نحو : ﴿ إني أرى ما لا ترون ﴾(٣) . والرابع : إدراك بالعقل وعلى ذلك قوله تعالى : ﴿ما كذب الفؤاد ما رأى﴾(٤). ويمكن أن تكون الرؤى : جمع رؤيا وهى : ما يُرى في المنام ، وقد روى : لم يبق من مبشرات النبوة إلا الرؤيا ، قال الله تعالى : ﴿لقد صدق الله رسوله الرؤيا﴾(٥) . وهذا الذي يرى الرؤيا :", "(١) أحمد : مسنده : ١٩١/٢ - ١٩٢ والبخاري فتح البارى : ٤٩١/١٠ .", "(٢) سورة التكاثر : ٦ - ٧ . (٣) سورة الأنفال : ٤٨ .", "(٤) سورة النجم : ١١ . (٥) سورة الفتح : ٢٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0065.png"}, {"n": 66, "paras": ["إن كان صالحا ظاهر الصلاح ملتزما بفرائض الإسلام وآدابه ، فإن هذه الرؤيا تدل على أنه رجل صالح ، لكن ما ينبغي أن يترتب عليها شئ من الأدلة الشرعية في الأحكام بأي حال من الأحوال ، فإن ادعى شيئا من ذلك فليست هي الرؤيا التي عدها النبي ﷺ من مبشرات النبوة وإنما هي من تلبيسات الشياطين . وإن كان الذى رأى الرؤيا غير صالح ظاهر الصلاح ، فلا يلتفت إليه ولا إلى رؤياه . وبعد : فلقد أفاض علماء الإسلام في ذم هؤلاء الناس الذين يرون في الإلهامات والخواطر والكشف والرؤى أدلة على الأحكام الشرعية ، فأخرجوهم من حيز الإيمان وأدخلوهم في مجال الكفر ، وهم جديرون بذلك . قال أبو جعفر الطحاوى (١) : في التبرؤ من هؤلاء المدعين ومن الفرق الضالة كلها : « ... فهذا ديننا واعتقادنا ظاهرا وباطنا ، ونحن برءاء إلى الله تعالى من كل من خالف الذي ذكرناه وبيناه . ونسأل الله تعالى أن يثبتنا على الإيمان ويختم لنا به ويعصمنا من الأهواء المختلفة والآراء المتفرقة والمذاهب المروية مثل : المشبهة والمعتزلة والجهمية والجبرية والقدرية وغيرهم من الذين خالفوا الجماعة وحالفوا الضلالة ونحن منهم براء وهم عندنا ضلال أردياء ، وبالله العصمة والتوفيق » (١) . وبعد هذه الجولة في التعريف بهذه الكلمات : الإلهام والخواطر والكشف والرؤى نؤكد ما قاله الإمام البنا رحمه الله فيها : « ولكن الإلهام والخواطر والكشف والرؤى ليست من أدلة الأحكام الشرعية ، ولا تعتبر إلا بشرط عدم اصطدامها بأحكام الدين ونصوصه » .", "(١) ولد الطحاوى في عام ٢٢٧ ه وتوفى ٣٢١ه ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0066.png"}, {"n": 67, "paras": ["هذا هو الأصل الثالث من الأصول العشرين لركن الفهم الذي هو الركن الأول من أركان البيعة العشرة التي حددها الإمام المؤسس رضى الله عنه."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0067.png"}, {"n": 68, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0068.png"}, {"n": 69, "paras": ["الأصل الرابع من أصول الفهم", "« والتمائم والرقى والودع والرمل والمعرفة والكهانة وادعاء معرفة الغيب ، وكل ما كان من هذا الباب منكر تجب محاربته ، إلا ما كان من آية من قرآن أو رقية مأثورة »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0069.png"}, {"n": 70, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0070.png"}, {"n": 71, "paras": ["ولنلق ضوءا على كل واحدة من هذه المنكرات المنكرات التي يجب محاربتها أ - التمائم التمائم : جمع تميمة وهي ما يعلق في العنق لدفع العين . ويعرفها علماء الاجتماع بأنها : جسم طبيعي أو صناعي حي أو جماد يسود الاعتقاد بأنه يشتمل على قوة غير طبيعية فعالة ، خاصة إذا كان أثره يرجع إلى حلول الروح فيه وبالتالي فإنه ينشد استرضاء هذه الروح . وتستخدم التمائم لأغراض سحرية لطرد الشر . والاعتماد على مثل هذه الوسائل شائع في التاريخ البشرى معظمه وفي ثقافات كبيرة .", "- وقد استعمل التمائم قدماء المصريين بأساليب متعددة ،", "- واستخدمها العبرانيون وجعلوا فيها نصوصا من التوراة ،", "- واستخدمها النصارى منذ قديم في ديانتهم وجعلوا الصليب تميمة في بعض الأحيان وجعلوها أحجبة تضم بعض الأشياء المقدسة أو تضم نصوصا دينية. وتختلف مادة التميمة حيث تتخذ من : أسنان الحيوان أو الأحجار الكريمة ، وأحيانا تنقش عليها رموز مثل : عجلات إله الشمس ، والصليب المعقوف . والفرق بين التميمة والطوطم ، أن التميمة تشير إلى شئ معين كشجرة بعينها، أما الطواطم فيشير إلى نوع ما من النبات أو الحيوان. والتمائم عموما تدل على نوع من المادية في الدين أو الاتجاه إلى أن الألوهية"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0071.png"}, {"n": 72, "paras": ["جسم أو قوة طبيعية . وقد عرف العرب التمائم في جاهليتهم وتحدثت عنها أشعارهم فقال شاعرهم: وإذا المنيّةُ أنشبت أظفارها ألفيت كل تميمة لا تنفع وقد نهى الإسلام عن التعلق بهذه الأباطيل ، فقد جاء في الحديث النبوي ما رواه الإمام أحمد بسنده أن النبي ﷺ قال : « من علق تميمة فلا أتم الله له » . فهي منكر تجب محاربته . وروى أبو داود بسنده عن زينب زوج عبد الله عن عبد الله رضي الله عنه قال: سمعت رسول الله ﷺ يقول : « إن الرقى والتمائم والتولة شرك » . والرقية هي : قراءة شئ والحرام منه ما كان بغير لسان العرب . والتولة : ضرب من السحر ، أو خيط يقرأ فيه من السحر ، أو قرطاس يكتب فيه شئ من للمحبة وغيرها . ب - الرقى : الرقى جمع رقية وهي العوذة التي يُرقى بها المريض ونحوه. ويرى علماء الاجتماع أنها : التعويذة وهي العبادات والصيغ الشفهية المحددة التي يتلوها الساحر ليحدث أثرا سحريا . وتعتبر من أهم أركان السحر بل هي القوة الفعالة فيه ، وتلك القوة منحصرة في صيغتها اللفظية بحيث يقال : إن أقل تعديل فيها تغير من طبيعتها ويفقدها فاعليتها . بل يبالغ بعضهم فيقول : إن أى تغيير فيها يودى بحياة من أخطأ أو غيّر فيها"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0072.png"}, {"n": 73, "paras": ["والإسلام أجاز الرقية بالقرآن الكريم وبالأدعية المأثورة . روى أبو داود بسنده عن خارجة بن الصلت عن عمه أنه أتى رسول الله ﷺ فأسلم ، ثم أقبل راجعا من عنده ، فمر على قوم عندهم رجل مجنون موثق بالحديد فقال أهله : إنا حدثنا أن صاحبكم هذا قد جاء بخير ، فهل عندك شئ تداويه ؟ فرقيته بفاتحة الكتاب فبرأ ، فأعطوني مائة شاة ، فأتيت رسول الله ﷺ فأخبرته فقال : « هل إلا هذا » وفي رواية : « هل قلت غير هذا » ؟ قلت : لا ، قال : خذها فلعمري لمن أكل برقية باطل ، لقد أكلت برقية حق » (١) . ومن الأدعية المأثورة في الرقية ما رواه أبو داود بسنده عن أنس رضي الله عنه أنه قال لثابت : ألا أرقيك برقية رسول الله ﷺ ؟ قال : بلى قال : ، فقال : « اللهم رب الناس مذهب الباس اشف أنت الشافي لا شافي إلا أنت ، اشفه شفاء لا يغادر سقما » (٢) . وروى أبو داود بسنده عن أبي الدرداء رضي الله عنه قال : سمعت رسول الله ﷺ يقول : « من اشتكى منه شيئا أو اشتكاه أخ له فقال : « ربنا الله الذي في السماء تقدس اسمك ، أمرك في السماء والأرض ، كما رحمتك في السماء فاجعل رحمتك في الأرض ، اغفر لنا حوبنا وخطايانا ، أنت رب الطيبين أنزل رحمة من رحمتك وشفاء من شفائك على هذا الوجع فيبرأ » (٣) . وروى ابن ماجه بسنده عن أبي هريرة رضي الله عنه قال : جاء النبي ﷺ يعود لى فقال : « ألا أرقيك برقية جاءني بها جبريل ؟ فقلت : بأبي وأمى ، بلى يا رسول الله قال : « بسم الله أرقيك والله يشفيك من كل داء فيك ، ومن شر النفاثات في العقد ومن شر حاسد إذا حسد ثلاث مرات » (٤) . هذا ما أجازه الإسلام في الرقية ، وما عداه باطل ومنكر تجب محاربته .", "(١) أبو داود : سننه : ١٣/٤ . (٢) السابق : ١١/٤ .", "(٣) السابق : ١٢/٤ . (٤) ابن ماجه : سننه : ٣٥٩/٢ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0073.png"}, {"n": 74, "paras": ["ج - والودع : والودع : خرز أبيض جوف في بطونها شق كشق النواة ، تتفاوت في الصغر والكبر. وبعض الدجالين يستنبئ الودع عن الماضي أو الحاضر أو المستقبل ، وكل ذلك جهل وخرافة وخداع للناس ، ولا يجوز لمسلم أن يصدق شيئا من ذلك ولا أن يلجأ إليه ، فإنه منكر تجب محاربته. د - والرمل : ويقال : علم الرمل : وهو علم يبحث فيه عن المجهولات والمغيبات . وهو خرافة وضلال لا يجوز ممارسته ولا يجوز اللجوء إلى أحد ليضر به له ، فيزعم علم شيء من الغيب . وكل هذه ضلالات ومنكرات حاربها الإسلام ، ويجب على كل مسلم أن يحاربها ، فهي منكر منهى عنه . ه - والمعرفة : والمعرفة هي : ما يقوله « العراف » وهو المنجم الذي يدعى معرفة الغيب ، أو هو الكاهن الذي يدعى ذلك أيضا .", "- والعرافة : أعمال يزاولها العراف وتهدف إلى التنبؤ بالمستقبل بمعاونة الوسائل الخارقة للعادة ، أو التشاؤم بملاحظة الطيور أو استحضار الأرواح .", "- وقد تكون العرافة عن طريق قراءة شروخ العظام من الحيوانات بعد حرقها .", "- وقد تكون العرافة بفتح المندل أو رمى الزهر.", "- وقد تكون العرافة عن طريق ورق اللعب."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0074.png"}, {"n": 75, "paras": ["وكل ذلك باطل وصاحبه دجال لا يجوز تصديقه ، ولا يجوز الالتجاء إليه فهو صاحب منكر تجب محاربته شرعا . و - والكهانة : الكهانة : كالمعرفة التي تحدثنا عنها آنفا :", "- والكاهن : العراف ، وهو كل من تعاطى علما دقيقا .", "- والعرب تسمى « المنجم » كاهنا ، وكذلك تسمى الطبيب « كاهنا » .", "- والكاهن : عند اليهود والنصارى من ارتقى عندهم إلى درجة الكهنوت .", "- وعند أهل الديانات الأخرى غير المسلمين : الكاهن : من ساغ له أن يقدم القرابين والذبائح ويتولى القيام بأداء الشعائر.", "- والكهانة : حرفة الكاهن .", "- والكهنوت : وظيفة الكاهن .", "- ورجال الكهنوت : هم رجال الدين - وهي تسمية عند النصارى واليهود", "- ولا يعرفها الإسلام والمسلمون . والكهانة : كالعرافة تقوم على مطالعة الغيب وكشف حجبه ، والإخبار بالحوادث المستقبلية والماضية . ويُعزى للكاهن استطلاع ما يأتي به القدر من الأحداث ، ويزعمون أن لكل كاهن رئياً من الجن يتبعه ، ويسترق إليه السمع ، ويأتيه بالأخبار. والإسلام حرم الالتجاء إلى الكهان أو تصديق ما يقولون ، بل كره أسلوبهم في الكلام ونفر منه المتكلمين الذي يحذون حذوهم . روى أبو داود بسنده عن أبي هريرة رضى الله عنه أن رسول الله ﷺ قال : « من أتى كاهنا فصدقه بما يقول ، أو أتى امرأة حائضا ، أو في دبرها فقد برئ"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0075.png"}, {"n": 76, "paras": ["مما أنزل على محمد » (١) . وروى أبو داود بسنده عن ابن عباس رضي الله عنهما قال : قال رسول الله ﷺ « من اقتبس علما من النجوم اقتبس شعبة من السحر زاد ما زاد » (٢) . وروى الإمام مالك بسنده عن أبي هريرة رضي الله عنه أن امرأتين من هذيل رمت إحداهما الأخرى فطرحت جنينها فقضى فيه رسول الله ﷺ بغرة عبد أو وليدة » وفي رواية فقال الذي قضي عليه : كيف أغرم ما لا شرب ولا أكل ، ولا نطق ولا استهل ، ومثل ذلك يطل - أو دمه يطل - ، فقال رسول الله ﷺ : « إنما هذا من إخوان الكهان » (٣) .", "(١) أبو داود : سننه : ١٥/٤ .", "(٢) السابق : ١٥/٤ .", "(٣) الإمام مالك : الموطأ : ١٨٤/٢ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0076.png"}, {"n": 77, "paras": ["الأصل الخامس من الأصول العشرين لركن الفهم", "« ورأى الإمام أو نائبه فيما لا نص فيه ، وفيما يحتمل وجوها عدة وفي المصالح المرسلة معمول به ما لم يصطدم بقاعدة شرعية ، وقد يتغير بحسب الظروف والعرف والعادات . والأصل في العبادات التعبد دون الالتفات إلى المعاني ، وفي العادات الالتفات إلى الأسرار والحكم والمقاصد »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0077.png"}, {"n": 78, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0078.png"}, {"n": 79, "paras": ["عمود هذا الأصل الخامس ومصدره الشرعي الذي يؤول إليه ، هو حديث نبوي شريف رواه أبو داود وغيره من علماء الحديث ، فيما يتصل بالاجتهاد فيما لا نص فيه . روى أبو داود بسنده عن أناس من أهل حمص من أصحاب معاذ بن جبل رضي الله عنه أن رسول الله ﷺ لما أراد أن يبعث معاذا إلى اليمن قال : « كيف تقضى إذا عرض لك قضاء ؟ » قال : أقضى بكتاب الله . قال : فإن لم تجد في كتاب الله ؟ قال : فبسنة رسول الله . قال : فإن لم تجد في سنة رسول الله ؟ ولا في كتاب الله ؟ قال : اجتهد ولا آلو . فضرب رسول الله ﷺ صدره وقال : الحمد لله الذي وفق رسول رسول الله لما يرضى رسول الله » (١) . وإلقاؤ الضوء على هذا الأصل يستدعى أن نتحدث فيه عن أمرين : الأول : الاجتهاد ، والثاني : موقف المسلمين من العبادات والعادات . أ - الاجتهاد : الاجتهاد هو : أخذ النفس ببذل الطاقة وتحمل المشقة . والفقهاء يعرفون الاجتهاد بأنه :", "(١) أبو داود : سننه : ٣٠٣/٤ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0079.png"}, {"n": 80, "paras": ["استفراغ الفقيه الوسع ليحصل له ظن بحكم شرعي ، أي يستنبط الأحكام من أدلتها وتطبيقها .", "- والأصل في الاجتهاد أن يكون مطلقا أي غير متقيد بمذهب . وقد يكون مقيدا بمذهب معين .", "- كما أن الأصل ألا يخلو عصر من عصور المسلمين من اجتهاد ومجتهدين استوفوا شروط الاجتهاد ، يفتون للناس فيما لا نص فيه من كتاب أو سنة مما دخل عليهم حياتهم . وإذا كان الاجتهاد عمل الفقيه ، فإن الإمام أو نائبه لهما أن يجتهدا فيما لا نص فيه ، وكل ما يصل إليه المجتهد أو الإمام أو نائبه في أمر من الأمور أو قضية من القضايا مقبول ومعمول به ما دام المجتهد قد استوفى شروط الاجتهاد ولكن بشرطين : أحدهما : أن لا يكون فيما اجتهد فيه نص من نصوص الدين - الكتاب والسنة - لأنه لا اجتهاد مع النص ، مهما تكن مكانة المجتهد ولو كان الإمام نفسه الذي استوفى كل شروط الإمامة ، لأن النص يغنى عن الاجتهاد . والثاني : ألا يصطدم ما اجتهد فيه أو ما وصل إليه من حكم مع قاعدة من قواعد الشريعة الإسلامية . وعلى كل مسلم أن يفهم الإسلام في إطار أن نصوصه من الكتاب والسنة واجبة الالتزام والتنفيذ ، وليس لأحد من المسلمين مجتهدا أو غير مجتهد أن يعطل نصاً أو يحور فيه أو يؤل . وإنما على كل راغب في فهم النص أن يخضع لقواعد اللغة العربية من غير تكلف ولا تعسف . وهذا شرط جوهري في فهم النص ، ولكل من الكلمتين معنى نحب أن"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0080.png"}, {"n": 81, "paras": ["نوضحه فيما يلى : فالتكلف : تحميل النص ما لا يحتمل ، والاستدلال به على ما لا يدل عليه ، وكأن المتكلف يخرج النص عما يعنيه ويقصده إلى مراد بعيد يتكلفه . والتكلف : اسم لما يصنع بمشقة أو تصنع وهو نوعان : محمود ومذموم . فالمحمود : ما يتحراه الإنسان ليتوصل به إلى أن يصير الفعل الذي يقوم به سهلا عليه محبوبا لديه ، ومنه : التكلف في تكليف العبادات . والمذموم : ما يتحراه الإنسان مراءاة ، وإياه عنى في قوله تعالى : ﴿ قل ما أسألكم عليه من أجر وما أنا من المتكلفين ﴾(١) وقوله ﷺ « أنا وأتقياء أمتى براء من التكلف » . وإذا لم تكن هناك نصوص من الكتاب والسنة في قضية من القضايا أو أمر من الأمور انفتح على المسلم الفاهم باب الاجتهاد ، لأنه من المقرر لدى أسلافنا من العلماء أنه لا اجتهاد مع النص ، فإذا لم يكن نص اجتهد المسلم الفقيه المستوفى شروط المجتهد ولا يألو جهدا في اجتهاده . وهذا الاجتهاد الذى توصل إليه الإمام أو نائبه فيما لا نص فيه ، يعمل به في المكان والزمان الذى تم فيه الاجتهاد ، فإذا بدا للإمام أن يغير فيه أو يبدل خضوعا لظروف فيها تحقيق مصلحة للمسلمين ، فله أن يغير ما أوصله إليه اجتهاده وعلى المسلمين أن يقبلوا منه هذا التغيير، لأنه كان واستمر بناء على قاعدة « أنه لا اجتهاد مع النص » . ويقبل هذا الاجتهاد فيما يحتمل وجوها عدة . أما ما لا يحتمل سوى وجه واحد فلا يقبل إذا خالف هذا الوجه الواحد ، ولأنه والحالة هذه يكون قد ارتكب التكلف أو الاعتساف فشذ في اجتهاده عن الأصل .", "(١) سورة ص : ٨٦ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0081.png"}, {"n": 82, "paras": ["كذلك يقبل اجتهاده في المصالح المرسلة - العامة - لأنها تحقق للمسلمين منفعة في دنياهم أو أخراهم . هذا ما أجمع عليه معظم العلماء المسلمين في عصورهم المختلفة فلا ينبغي تجاهله.", "ب - موقف المسلمين من العبادات والعادات : من أصول فهم الإسلام فهما صحيحا أن يأخذ المسلمون العبادات كما وردت توقيفية لا يبحثون فيها عن العلل والأسباب ، لأن المقصود منها هو التعبد بها كما جاءت وعدم إعنات الفكر والنفس بالبحث وراء أسرارها ومقاصدها ، لأنه لا يمكن الوصول من وراء ذلك إلى شئ ذي بال ، ومهما حاول الإنسان في هذا المجال وخيل إليه أنه وصل إلى السر والمقصد فإن غيره من الناس قد ينازعه فيما وصل إليه ، ويصل هو إلى غير ذلك . وعلى سبيل المثال : عدد ركعات الفرائض الخمس التي فرض الله علينا في اليوم والليلة لا يمكن الوصول إلى سرها ومقصدها . أما الأمور العادية في الحياة التي يمارسها الناس في يومهم وليلتهم ، فينبغي أن يبحثوا فيها عن العلل والأسرار والأسباب والحكم والمقاصد ، ويستطيعون أن يصلوا إلى كثير من أسرارها ومقاصدها ، فيمارسونها عن اقتناع ويقبلون عليها بتجاوب (١) . ذلك هو الأصل في فهم الإسلام على وجهه الصحيح ، وهذا ما قرره أهل السنة والجماعة والسلف الصالح من علماء المسلمين وفقهائهم ، وما شذ عنهم إلا الذين ضلوا سواء السبيل واتبعوا غير سبيل المؤمنين .", "(١) الإمام الشاطبي : الموافقات : ٣٠٠/٢ باختصار وتصرف ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0082.png"}, {"n": 83, "paras": ["الأصل السادس من أصول الفهم", "« وكل واحد يؤخذ من كلامه ويترك إلا المعصوم ﷺ ، وكل ما جاء عن السلف رضوان الله عليهم موافقا للكتاب والسنة قبلناه ، وإلا فكتاب الله وسنة رسوله أولى بالاتباع ، ولكنا لا نعرض للأشخاص فيما اختلف فيه بطعن أو تجريح ، ونكلهم إلى نياتهم وقد أفضوا إلى ما قدموا »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0083.png"}, {"n": 84, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0084.png"}, {"n": 85, "paras": ["أ- العصمة من الخطأ الفقه الصحيح للإسلام هو الاعتقاد بأن أحدا من المسلمين خاصتهم وعامتهم ، أئمتهم وفقهائهم ليس معصوما من الخطأ ، لأن كل ابن آدم خطاء ، وبالتالى فلا يؤخذ من كلامهم إلا ما كان موافقا لكتاب الله وسنة رسوله ﷺ . ومهما يبلغ فقه الفقيه من التبحر والتعمق في الدين ، فإنه لا يجوز أن يؤخذ كل كلامه على أنه صواب ، يدخل في ذلك أئمة المذاهب أنفسهم ، وإنما يقبل من كلامهم ما كان موافقا لكتاب الله وسنة رسوله ﷺ . أما الذي له العصمة ، ويؤخذ كل كلامه فهو محمد ﷺ وحده لأن الله تبارك وتعالى عصمه ، إذ هو المبلغ عن ربه الصادق الأمين المعصوم عن الخطأ والهوى . وقد بلغ محمد ﷺ عن ربه القرآن الكريم وأحاديثه النبوية الشريفة ، فهذان لهما العصمة لصدورهما ومعرفتنا بهما عن طريق المعصوم ﷺ . وكل واحد من المسلمين الصحابة والتابعين وتابعيهم وأئمة المذاهب وعلماء الحديث والفقه والسلف جميعا ، بل كل عالم من علماء الإسلام في مختلف العصور والأزمان يؤخذ من كلامه ما كان موافقا للكتاب والسنة أو ما كان اجتهادا فيما لا نص فيه بشرط ألا يصطدم مع قاعدة شرعية . وهؤلاء جميعا يترك من كلامهم ما كان مخالفا للكتاب والسنة أو ما كان اجتهادا مع وجود النص ، أو ما كان اجتهادا فيما لا نص فيه ولكنه يصطدم مع قاعدة شرعية . تلك قاعدة عند علماء الشريعة لا يستثنى منها أحد . ولكن من ترك كلامه أو اجتهاده لأن فيه اختلافا ، لا يجوز لنا أن نطعن فيه"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0085.png"}, {"n": 86, "paras": ["ولا أن نجرحه ، لأنه اجتهد فأخطأ ، وبخاصة إذا كان قد اجتهد فيما لا نص فيه.", "ب- حرمة تجريح المسلم والمسلم لا يحل له أن يجرح ولا أن يلمز ولا أن يعيب ، وإنما يترك ما خالف كتاب الله وسنة نبيه ﷺ ، أو ما كان اجتهادا مصطدما مع قاعدة شرعية ، وإنما على المسلم أن يكل أمر أصحاب هذا الرأى أو ذاك أى الاجتهاد إلى نياتهم، والله سبحانه يحاسبهم على ذلك ، وهو أعلم بهم وبنياتهم ، وقد أفضوا إلى ربهم بما قدموا.", "هذا هو أدب الإسلام في الأخذ عن الآخرين في العلم أو العمل ، ما ينبغى أن يحيد عنه مسلم يخاف الله.", "ولقد كان أئمة المذاهب جميعا يرددون ذلك ويصرحون دائما بأنه إذا صح لديهم نص تنازلوا عن اجتهادهم الذى اجتهدوا فيه قبل أن يتبين لهم النص أو تتبين لهم صحته. ولهم في ذلك مواقف تدل على الورع والتقوى بمقدار ما تدل على الحيدة والموضوعية والاتجاه إلى الحق والاعتراف بالخطأ عند الوقوع فيه.", "إن أئمة المذاهب جميعا ما أثر عن أحدهم كلمة تنبئ عن حملهم أحدا من الناس على الأخذ بمذهبهم ، وإنما كانت المقولة الشائعة عندهم هي : مذهبنا صواب يحتمل الخطأ ومذهب غيرنا خطأ يحتمل الصواب .", "ولولا أن نطيل لذكرنا كلمات كثيرة ورائعة لهم جميعا في هذا المجال ، ولكنا نحيل من يرغب في ذلك إلى الكتب الى أرخت لهم وسردت حياتهم ، فإنه واجد فيها شيئا كثيرا ، ومستفيد منها فائدة عظيمة بإذن الله تعالى ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0086.png"}, {"n": 87, "paras": ["الأصل السابع : من أصول الفهم", "« ولكل مسلم لم يبلغ درجة النظر في أدلة الأحكام الفرعية أن يتبع إماما من أئمة الدين ، ويحسن مع هذا الاتباع أن يجتهد ما استطاع في تعرف أدلته ، وأن يتقبل كل إرشاد مصحوب بالدليل متى صح عنده صلاح من أرشده وكفايته ، وأن يستكمل نقصه العلمي إن كان من أهل العلم حتى يبلغ درجة النظر »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0087.png"}, {"n": 88, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0088.png"}, {"n": 89, "paras": ["إن الإمام المؤسس يطرح في هذا الأصل قضايا هامة ، في الإسلام وفقهه ، وفي الأتباع ، وفي الاجتهاد ، وفي تقبل النصح والإرشاد ، وفي استكمال النقص العلمي . وسوف نلقى عليها بعض الضوء على النحو التالي : أ - الاتباع : مَن الذي يتبع إماما من أئمة المذاهب ولا يعتمد على نفسه في فهم الدين؟. إنه المسلم الذي لم يبلغ بعد درجة النظر . فما درجة النظر هذه ؟ إنها القدرة على فهم الأحكام من أدلتها الشرعية ، وهذه القدرة قريبة في المعنى من كلمة « الفقه » لأن الفقه توصل إلى علم غائب بعلم شاهد ، والنظر في الأدلة للوصول إلى حكم شرعى ، هو نفسه التوصل إلى علم غائب بعلم شاهد. ولكل مسلم لم يبلغ هذه الدرجة أن يتبع إماما من أئمة الدين يأخذ الأحكام الشرعية عنه ، غير أن هذا وحده لا يكفى . إذ عليه أن يجتهد ما استطاع في التعرف على أدلة الإمام الذي اتبعه إذا كان من أهل القدرة على ذلك . إنما وجب على المتبع لإمام من الأئمة الاجتهاد إن كان قادراً عليه ، لأن التقليد لهذا الإمام لا يكفى في أمور العقيدة ، بل لا يكفى في أمور الدين والتدين والعبادات . كما أن عليه أن يتقبل برضا نصح الناصحين وإرشاد المرشدين ، ما دام قد اطمأن إلى صلاح المرشد الناصح وإخلاصه في نصحه ، واطمأن كذلك إلى أنه من أهل النصح والإرشاد ، وأنه لا ينصح إلا بما يعلم ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0089.png"}, {"n": 90, "paras": ["وهكذا تكون العلاقة بين الناصح والمنصوح في ظل هذا الأصل العظيم من أصول الركن الأول - الفهم - من أركان البيعة . ب - واجبات الاتباع : كما أن المسلم مطالب بأن يتتبع في نفسه كل نقص علمي في دينه أو فقهه وأن يحاول استكمال هذا النقص بالقراءة والثقافة والعلم والتعلم - إن كان من أهل القدرة على ذلك - . وعليه أن يستمر في هذه الدراسة والتعلم حتى يبلغ درجة النظر في أدلة الأحكام الفرعية ، ليصل إلى هذه الأحكام . ج - بلوغ درجة النظر : ولبلوغ درجة النظر أدوات تعين على الوصول إليها نذكر منها : أ - المداومة على تدبر تلاوة القرآن الكريم ، مع التأمل فيما تقصد آياته الكريمة، ومن فضل الله تعالى على الناس أن يسر القرآن للذكر . ب - والمطالعة المستمرة في أحاديث الرسول ﷺ فهي تعين على فهم القرآن الكريم من ناحية ، وتساعد المسلم على أن يتعرف بدقة على مقاصد الإسلام في الحياة الإنسانية كلها . ج - ومصاحبة السيرة النبوية في كتب السنة أو في كتاب معتمد من كتب السيرة وهي كثيرة أولاها بالقبول عندى « إمتاع الأسماع ... للمقريزى » مع ضرورة التأمل في أحداث السيرة النبوية وأخذ القدوة من مواقفها النبوية . د - والمعرفة الجيدة بعلوم اللغة العربية من نحو وصرف وبلاغة فهي مفاتيح القرآن الكريم ، ولا يفهم إلا بها . ه - والإلمام الجيد بالعلوم التالية :", "- علم أصول التفسير ومذاهبه ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0090.png"}, {"n": 91, "paras": ["- وعلم أصول الحديث - علم الحديث دراية - .", "- وعلم أصول الفقه .", "- وعلم الفقه في كتاب وسيط غير مختصر ، والكتاب الذي أرشحه لذلك كتاب « فقه السنة للشيخ سيد سابق » في طبعاته الأخيرة . و- المعرفة الجيدة بالشعر العربي القديم فهو مفتاح لفهم العربية كلها وفهم الكتاب والسنة . وبعد فهذه هي الأدوات التي تمكن المسلم في هذه المرحلة - من مراحل الدعوة - من أن يبلغ بهذا الجهد درجة النظر ، وما لم يبلغها - وكان من أهل القدرة على القراءة والعلم - فلا يزال به الطلب على وجه الوجوب أو الندب - حسب حاله - حتى يبلغها . هكذا كانت تربي الجماعة أفرادها في هذا المستوى من العضوية تريد منهم أن يبلغوا درجة النظر أي يصيروا فقهاء في الدين ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0091.png"}, {"n": 92, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0092.png"}, {"n": 93, "paras": ["الأصل الثامن : من أصول ركن الفهم :", "« الخلاف الفقهى فى الفروع لا يكون سببا للتفرق فى الدين ، ولا يؤدى إلى خصومة ولا بغضاء ، ولكل مجتهد أجره ، ولا مانع من التحقيق العلمى النزيه فى مسائل الخلاف ، في ظل الحب فى الله ، والتعاون على الوصول إلى الحقيقة ، من غير أن يجر ذلك إلى المراء المذموم والتعصب » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0093.png"}, {"n": 94, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0094.png"}, {"n": 95, "paras": ["وهذا أيضاً أصل عظيم من أصول فهم الإسلام ، يُعد المسلمون في كل زمان ومكان في مسيس الحاجة إليه ، لأن الخلاف بين الناس في الفهم والاستنتاج أمر وارد دائما ، وما دام كذلك فما هي ضوابط هذا الخلاف التي لا تخرج به إلى حد البغضاء والتنافر بل التعصب ، وبخاصة أن المسلمين رموا من هذا الخلاف بدواه في تاريخهم . ولكي نوضح هذا الأصل من أصول الفهم ، وهو أصل يمكن أن نطلق عليه مطمئنين أدب الخلاف في الإسلام ، فإن علينا أن نتحدث تحت عنوانين هما : أنواع الاختلاف ، وأدب الاختلاف . أ - أنواع الاختلاف حفل تاريخ المسلمين بالاختلاف الفقهي فيما بينهم ، وكان ذلك الاختلاف قدرا في تاريخ المسلمين ، وقد تحدث عنه الرسول ﷺ قبل أن يقع ووضع اللبنة الأولى لأدبه . فقد روى أبو داود بسنده عن أبي هريرة رضى الله عنه قال : قال رسول الله ﷺ : « افترقت اليهود على إحدى وسبعين فرقة أو اثنتين وسبعين فرقة ، وتفرقت النصارى على إحدى أو اثنتين وسبعين فرقة ، وتفترق أمتى على ثلاث وسبعين فرقة » وزاد أبو داود بسنده عن معاوية بن أبي سفيان رضى الله عنهما : « ثنتان وسبعون في النار وواحدة في الجنة وهي الجماعة » (١) . وقد حدث هذا التفرق في تاريخ المسلمين منذ عهد الصحابة والتابعين رضوان الله عليهم ، في العقيدة نفسها حيث ظهرت فرق أساسية في هذا التفرق", "(١) أبو داود : سننه : ٤ / ١٩٨ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0095.png"}, {"n": 96, "paras": ["والاختلاف مثل : المشبهة ، والمعتزلة ، والجهمية ، والجبرية ، والقدرية ، وغيرها . قال أبو جعفر الطحاوى : « ثم إن أنواع الافتراق والاختلاف في الأصل قسمان : اختلاف تنوع ، واختلاف تضاد . واختلاف التنوع على وجوه :", "- منه ما يكون كل واحد من القولين أو الفعلين حقا مشروعا كما في القراءات التي اختلف فيها الصحابة رضوان الله عليهم ، حتى زجرهم النبي ﷺ وقال : « كلاكما محسن ولا تختلفوا فإن من كان قبلكم اختلفوا فهلكوا »(١) . ومثله اختلاف الأنواع في صفة الأذان والإقامة والاستفتاح ومحل سجود السهو والتشهد ، وصلاة الخوف ، وتكبيرات العيد ، ونحو ذلك مما قد شرع جميعه ، وإن كان بعض أنواعه أرجح وأفضل . ثم نجد لكثير من الأمة في ذلك من الاختلاف ما أوجب اقتتال طوائف منهم على شفع الإقامة وإيتارها ونحو ذلك ، وهذا عين المحرّم . وكذا تجد كثيراً منهم في قلبه من الهوى لأحد هذه الأنواع ، والإعراض عن الآخر والنهى عنه ؛ ما دخل به فيما نهى عنه النبي ﷺ .", "(١) رواه البخارى بتمامه الحديث رقم ٢٤١٠ ورواه أحمد : ٣٩٣/١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0096.png"}, {"n": 97, "paras": ["- ومنه ما يكون كل من القولين هو في المعنى القول الآخر ، لكن العبارتان مختلفتان ، كما قد يختلف كثير من الناس في ألفاظ الحدود ، وصوغ الأدلة ، أو التعبير عن المسميات . ونحو ذلك . ثم الجهل أو الظلم يحمل - صاحبه - على حمل إحدى المقالتين وذم الأخرى والاعتداء على قائلها ، ونحو ذلك . وأما إختلاف التضاد فهو :", "- القولان المتنافيان إما في الأصول وإما في الفروع ، عند الجمهور الذين يقولون : المصيب واحد . والخطب في هذا أشد ، لأن القولين يتنافيان . لكن نجد كثيرا من هؤلاء قد يكون القول الباطل الذي مع منازعه فيه حق ما ، أو معه دليل يقتضي حقا ما ، فيرد الحق مع الباطل ، حتى يبقى هذا مبطلا في البعض كما كان الأول مبطلا في الأصل . وهذا يجرى كثيرا لأهل السنة . وأما أهل البدعة فالأمر فيهم ظاهر . ومن جعل الله له هداية ونورا رأى من هذا ما يبين له منفعة ما جاء في الكتاب والسنة من النهى عن هذا وأشباهه ، وإن كانت القلوب تنكر هذا ، لكن : نور على نور. والاختلاف الأول الذي هو اختلاف التنوع : الذم فيه واقع على من بغى على الآخر فيه ، وقد دل القرآن على حمد كل واحدة من الطائفتين في مثل ذلك ، إذا لم يحصل بغى كما في قوله تعالى : ﴿ ما قطعتم من لينة أو تركتموها قائمة على أصولها فبإذن الله ﴾(١) وقد كانوا اختلفوا في قطع", "(١) سورة الحشر : ٥ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0097.png"}, {"n": 98, "paras": ["الأشجار فقط مع قوم وترك آخرون ... وكما في إقرار النبي ﷺ يوم بني قريظة لمن صلى العصر في وقتها ولم أخرها إلى أن وصل إلى بني قريظة . وكما في قوله - ﷺ - : « إذا اجتهد الحاكم فأصاب فله أجران ، وإذا اجتهد فأخطأ فله أجر » . والاختلاف الثاني : هو ما حمدت فيه إحدى الطائفتين وذمت الأخرى ، كما في قوله تعالى ﴿ ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينات ولكن اختلفوا فمنهم من آمن ، ومنهم من كفر ﴾(١) . وأكثر الاختلاف الذي يؤول إلى الأهواء بين الأمة - من القسم الأول - وكذلك إلى سفك الدماء ، واستباحة الأموال والعداوة والبغضاء ، لإن إحدى الطائفتين لا تعترف للأخرى بما معها من الحق ، ولا تنصفها ، بل تزيد على ما مع نفسها من الحق زيادات من الباطل ، والأخرى كذلك ، ولذلك جعل الله مصدر البغى في قوله : ﴿ وما اختلف فيه الذين أتوه من بعد ما جاءتهم البينات بغيا بينهم ﴾(٢). لأن البغى مجاوزة الحد ، وذكر ذلك في غير موضع من القرآن الكريم ليكون عبرة لهذه الأمة . وقريب من هذا الباب ما خرجاه في الصحيحين عن أبي الزناد وعن الأعرج عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال : « ذروني ما تركتكم فإنما هلك من كان قبلكم بكثرة سؤالهم واختلافهم على أنبيائهم ، فإذا نهيتكم عن شيء فاجتنبوه وإذا أمرتكم بأمر فأتوا منه ما استطعتم » . فأمرهم بالإمساك عما لم يؤمروا به معللا سبب هلاك الأولين بأنهم كانوا يكثرون السؤال ويختلفون مع أنبيائهم ... » (٣) .", "(١) سورة البقرة : ٢٥٣ .", "(٢) سورة البقرة : ٢١٣ .", "(٣) الطحاوى - الطحاوية : ٧٧٨/٢ - ٧٨٣ باختصار وتصرف ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0098.png"}, {"n": 99, "paras": ["ب - أدب الاختلاف : اتضح لنا مما سبق أن الخلاف الفقهي في الفروع وارد بين المسلمين ، وأن كثيرا منه غير ذميم ، وأن معظمه إنما يقوم على الاجتهاد ، ولذلك فإن لهذا الاختلاف الواقع بين المسلمين أدب ينبغي الالتزام به ، وقد أشار الإمام المؤسس إلى مفردات هذا الأدب على النحو الذي نذكره فيما يلي :", "١ - لا ينبغي أن يكون الاختلاف في الفروع سببا للفرقة بين المسلمين في الدين لأن الفرقة في الدين تؤدى إلى كثير من الشقاق والنزاع ، والأصل في المسلمين أن لا يتنازعوا فيفشلوا وتذهب ريحهم.", "٢ - وعلى المسلمين أن يحترم كل منهم من اجتهد في أمر من أمور الدين فأخطأ لأنه مأجور عند الله ، فكيف يكون مأجورا ثم يخاصم ويعادى ويبغض؟.", "٣ - والتسامح بين المسلمين فيما اختلفوا فيه من فروع لا يمنع أبدا من قيام بعض العلماء بالتحقيق العلمى النزيه في مسائل الخلاف ، على أن يكون رائد المحققين هو الحب في الله والتعاون من أجل إظهار الحقيقة .", "٤ - وما ينبغي أن يجر الخلاف بين المسلمين في الفروع الفقهية إلى المراء - وهو المحاجة والمجادلة فيما فيه تردد - وهو مذموم لا يتصف به المسلم . حتى لو ترك المسلم وهو على حق لكان خيرا له ، ذاك هو أدب الإسلام في المراء .", "٥ - ولا يجوز أن يجر الخلاف الفقهي في الفروع بين المسلمين إلى التعصب أى أن يتعصب كل فريق لما رأى ، فإن التعصب دائما يعمى عن الحق ولنا في أسلافنا رضوان الله عليهم وتاريخهم المشهود في التاريخ ما ينفرنا من التعصب وما يجر إليه من شر."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0099.png"}, {"n": 100, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0100.png"}, {"n": 101, "paras": ["الأصل التاسع من أصول ركن الفهم :", "« وكل مسألة لا ينبنى عليها عمل ، فالخوض فيها من التكلف الذي نهينا عنه شرعا . ومن ذلك كثرة التفريعات للأحكام التي لم تقع ، والخوض في معاني الآيات القرآنية الكريمة التي لم يصل إليها العلم بعد ، والكلام في المفاضلة بين الأصحاب رضوان الله عليهم وما شجر بينهم من خلاف ، ولكل منهم فضل صحبته وجزاء نيته ، وفى التأول مندوحة » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0101.png"}, {"n": 102, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0102.png"}, {"n": 103, "paras": ["وقد سبق لنا الحديث عن التكلف ، ورأينا هناك أنه نوعان : محمود ومذموم . ومن المذموم منه ، ما اعترض الإمام المؤسس على وروده في هذه الحالات التي ذكرها في هذا الأصل من أصول الفهم . وسوف نتحدث عن هذه الحالات التي ذكرها في نقاط ثلاثة : الأولى : الخوض في مسائل لا ينبنى عليها عمل ، وعن أحكام لم تقع بعد . والثانية : الخوض في معاني الآيات القرآنية الكريمة التي لم يصل إليها العلم بعد والثالثة : الخوض في المفاضلة بين الأصحاب وما شجر بينهم من خلاف . أ- الخوض في مسائل لا ينبنى عليها عمل ، وعن أحكام لم تقع بعد : من المتفق عليه بين المسلمين أن الخوض في المسائل والأمور التي لا يترتب عليها عمل مضيعة للوقت وتبديد للجهد دون طائل ، بل اعتبروا ذلك من التكلف الذي نهينا عن شرعا . وكذلك الشأن في الخوض في أحكام فرعية لم تقع بعد ، قال الله تعالى على لسان نبيه محمد ﷺ : ﴿ قل ما أسألكم عليه من أجر وما أنا من المتكلفين إن هو إلا ذكر للعالمين ولتعلمن نبأه بعد حين ﴾(١) . ويقول الرسول ﷺ : « أنا وصالح أمتى براء من التكلف » وفي الرواية التي سقناها آنفا : « وأتقياء أمتى ... » . ويقول صلوات الله عليه وسلامه « سيكون في أمتى أقوام يتعاطى فقهاؤهم عضل المسائل أولئك شر أمتى »(٢) .", "(١) سورة ص : ٨٦ - ٨٨ . (٢) الطبراني ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0103.png"}, {"n": 104, "paras": ["وقد علمنا الإسلام أدب السؤال وتخير وقته وتخير لفظه ، ونهانا عن التكلف والتنطع والسؤال فيما لم يقع و قال الله تعالى : ﴿ يأيها الذين آمنوا لا تسألوا عن أشياء إن تبد لكم تسؤكم ، وإن تسألوا عنها حين ينزل القرآن تبد لكم ، عفا الله عنها والله غفور حليم ، قد سألها قوم من قبلكم ثم أصبحوا بها كافرين ﴾ (١) . قال المفسرون : كان بعض الصحابة يكثرون على رسول الله ﷺ من السؤال عن أشياء لم ينزل الله تعالى فيها أمرا أو نهيا ، وكان بعضهم يلحف في الطلب لتفصيل أمور وتشقيقها ، يكون القرآن الكريم قد أجملها وجعل في إجمالها رحمة وسعة للناس ، كما كان بعضهم يستفسرون عن أمور لا ضرورة للسؤال عنها أو كشفها ، لما يترتب على ذلك من تضييق أو أذى لسائل ، أو بالمسلمين عامة ، فعلمهم الإسلام أن لا يسألوا عن هذه الأشياء . ومن أمثلة ذلك أنه لما نزلت الآية التي جعلت الحج فريضة على القادرين من المسلمين وهي قوله تعالى : ﴿ ولله على الناس حج البيت من استطاع إليه سبيلا ... ﴾ (٢) سأل أحد الصحابة : رسول الله ﷺ قائلا : أفى كل عام ؟ فسكت رسول الله ﷺ ، فقالوا : أفى كل عام ؟ قال : « لا . ولو قلت نعم لوجبت ، ولو وجبت ما أطلقتموها ، ولو لم تطيقوها لكفرتم » فأنزل الله تعالى : ﴿ يأيها الذين آمنوا لا تسألوا عن أشياء إن تبد لكم تسؤكم ﴾ (٣) . وروى ابن جرير بسنده عن أبي هريرة رضى الله عنه قال : خرج رسول الله ﷺ - وهو غضبان محمار وجهه حتى جلس على المنبر - فقام إليه رجل فقال : أين أنا ؟ قال : « في النار » فقام آخر فقال : من أبي ؟ فقال : « أبوك حذافة »", "(١) سورة المائدة : ١٠١ - ١٠٢ . وانظر لنا : تفسير سورة المائدة نفس الآية نشر دار التوزيع والنشر الإسلامية ١٩٩٣م .", "(٢) سورة آل عمران : ٩٧ . (٣) سورة المائدة : ١٠١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0104.png"}, {"n": 105, "paras": ["فقام عمر بن الخطاب - رضي الله عنه - فقال : رضينا بالله ربا وبالإسلام دينا وبمحمد ﷺ - نبيا ورسولا وبالقرآن إماما. إنا يا رسول الله حديثوا عهد بجاهلية وشرك ، والله أعلم من آباؤنا ، قال فسكن غضبه ، ونزلت هذه الآية ﴿ يأيها الذين آمنوا لا تسألوا عن أشياء إن تبد لكم تسؤكم ... ﴾ . وروى مجاهد عن ابن عباس - رضي الله عنهما - أنها نزلت في قوم سألوا رسول الله ﷺ - عن البحيرة والسائبة والوصيلة والحام - وهو قول سعيد بن جبير ، وقال : ألا ترى أن بعده : ﴿ ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام ﴾(١) . ثم ضرب الله لهم المثل ببني إسرائيل لما شددوا فشدد عليهم ، أو ضيقوا فضيق عليهم ، فقد قيل لهم : اذبحوا بقرة ، فلو ذبحوا أي بقرة لأجزأتهم ، ولكنهم أخذوا يشققون ويقولون في لونها وعمرها وصفاتها الخاصة ، فضيق عليهم فيها على النحو المعروف في تاريخهم والذى حكاه القرآن الكريم في قوله تعالى : ﴿ قد سألها قوم من قبلكم ثم أصبحوا بها كافرين ﴾ . وقد ورد في هذا المعنى عدد من الأحاديث النبوية نذكر منها ما يلي : روى الإمام مسلم بسنده عن عامر بن سعد عن أبيه قال : قال رسول الله ﷺ : « إن أعظم المسلمين في المسلمين جرما من سأل عن شئ لم يحرم على المسلمين فحرم عليهم من أجل مسألته » . وروى الحاكم في المستدرك بسنده عن أبي ثعلبة رضي الله عنه قال : قال رسول الله ﷺ إن الله حد حدودا فلا تعتدوها وفرض فرائض فلا تضيعوها وحرم أشياء فلا تنتهكوها ، وترك أشياء من غير نسيان من ربكم ولكن رحمة منه لكم فاقبلوها ولا تبحثوا عنها » . وفي الصحيح : « ذروني ما تركتكم ، فإنما أهلك من كان قبلكم كثرة سؤالهم واختلافهم على أنبيائهم » .", "(١) سورة المائدة : ١٠٣ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0105.png"}, {"n": 106, "paras": ["وذكر الزهري عن عمار بن ياسر رضي الله عنهما وقد سئل عن مسألة ، فقال : هل كان هذا بعد ؟ قالوا : لا . قال : دعونا حتى يكون ، فإذا كان تجشمناها لكم » . وروى الدارمي بسنده عن ابن عباس - رضي الله عنهما - قال : ما رأيت قوما كانوا خيرا من أصحاب رسول الله ﷺ ، ما سألوه إلا عن ثلاث عشرة مسألة حتى قبض كلهن في القرآن منهن : ﴿ ويسألونك عن الشهر الحرام ﴾ ويسألونك عن المحيض ﴾ وشبهه ، وما كانوا يسألون إلا عما ينفعهم . وإكمالا للفائدة نذكر هذه المسائل الثلاث عشرة ، هي :", "١ - قال الله تعالى : ﴿ يسألونك عن الأهلة ... ﴾ (١) .", "٢ - وقال تعالى : ﴿ يسألونك ماذا ينفقون ... ﴾ (٢) .", "٣ - وقال سبحانه : ﴿ يسألونك عن الشهر الحرام ... ﴾ (٣) .", "٤ - وقال تعالى : ﴿ يسألونك عن الخمر والميسر ... ﴾ (٤) .", "٥ - وقال سبحانه : ﴿ ويسألونك عن اليتامى ... ﴾ (٥) .", "٦ - وقال تعالى : ﴿ ويسألونك عن المحيض ... ﴾ (٦) .", "٧ - وقال جلا وعلا : ﴿ يسألونك ماذا أحل لهم ... ﴾ (٧) .", "٨ - وقال تعالى : ﴿ يسألونك عن الساعة أيان مرساها ... ﴾ (٨) .", "٩ - وقال سبحانه : ﴿ يسألونك كأنك حفى عنها ... ﴾ (٩) .", "(١) سورة البقرة : ١٨٩ . (٢) سورة البقرة : ٢١٥ .", "(٣) سورة البقرة : ٢١٧ . (٤) سورة البقرة : ٢١٩ .", "(٥) سورة البقرة : ٢٢٠ . (٦) سورة البقرة : ٢٢٢ .", "(٧) سورة المائدة : ٤ . (٨) سورة الأعراف : ١٨٧ .", "(٩) سورة الأعراف : ١٨٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0106.png"}, {"n": 107, "paras": ["١٠ - وقال تعالى : ﴿ يسألونك عن الأنفال ... ﴾ (١) .", "١١ - وقال تعالى : ﴿ ويسألونك عن الروح ﴾ (٢) .", "١٢ - وقال تعالى : ﴿ ويسألونك عن ذي القرنين ﴾ (٣) .", "١٣ - وقال تعالى : ﴿ ويسألونك عن الجبال ... ﴾ (٤) . ب- والخوض في معاني الآيات القرآنية الكريمة التي لم يصل إليها العلم بعد : وهذه الآيات القرآنية الكريمة التي لم يصل إليها العلم بعد هي المتشابه من القرآن الكريم لدى بعض العلماء ، فقد قال الله تعالى : ﴿ هو الذي أنزل عليك الكتاب منه آيات محكمات هن أم الكتاب وأخر متشابهات ، فأما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تأويله وما يعلم تأويله إلا الله والراسخون في العلم يقولون آمنا به كل من عند ربنا وما يذكر إلا أولو الألباب ﴾ (٥) . وذلك أن الصحيح من أقوال العلماء أن القرآن الكريم ينقسم إلى : محكم ومتشابه : وقد اختلف في تعيين المحكم والمتشابه على أقوال من أشهرها : أن المحكم هو ما عرف المراد منه إما بالظهور وإما بالتأويل . والمتشابه ما استأثر الله بعلمه كقيام الساعة وخروج الدجال والحروف المقطعة في أوائل السور .", "(١) سورة الأنفال : ١ .", "(٢) سورة الإسراء : ٨٥ .", "(٣) سورة الكهف : ٨٣ .", "(٤) سورة طه : ١٠٥ .", "(٥) سورة آل عمران : ٧ .", "(٦) السيوطي : الاتقان في علوم القرآن : ٤/٢ . ط الحلبي مصر ١٣٧٠ه -"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0107.png"}, {"n": 108, "paras": ["وأخرج الحاكم بسنده عن ابن مسعود رضي الله عنه عن النبي ﷺ قال : « كان الكتاب الأول ينزل من باب واحد على حرف واحد ، ونزل القرآن على سبعة أبواب على سبعة حروف : زاجر وآمر وحلال وحرام ومحكم ومتشابه وأمثال . فأحلوا حلاله وحرموا حرامه وافعلوا ما أمرتم به وانتهوا عما نهيتم عنه واعتبروا بأمثاله واعملوا بمحكمه وآمنوا بمتشابه وقولوا آمنا به كل من عند ربنا»(١).", "وأخرج الدارمي عن عمر بن الخطاب - رضي الله عنه - قال : إنه سيأتيكم ناس يجادلونكم بمشتبهات القرآن ، فخذوهم بالسنة ، فإن أصحاب السنن أعلم بكتاب الله »(٢).", "وأخرج الدرامي في مسنده عن سليمان بن يسار أن رجلا يقال له : صبيغ قدم المدينة فجعل يسأل عن متشابه القرآن ، فأرسل إليه عمر وقد أعد له عراجين النخل ، فقال : من أنت ؟ قال : أنا عبد الله بن صبيغ ، فأخذ عمر عرجونا من تلك العراجين فضربه حتى دمى رأسه - وفي رواية عنده - : فضربه بالجريد حتى ترك ظهره دبرة ، ثم تركه حتى برأ ثم عاد ثم تركه حتى برأ ، فدعا به ليعود فقال : إن كنت تريد قتلى فاقتلني قتلا جميلا ، فأذن له إلى أرضه وكتب إلى أبي موسى الأشعري ، لا يجالسه أحد من المسلمين »(٣).", "كل هذه الآيات والآثار تدل على أن الخوض في معاني الآيات القرآنية الكريمة التي لم يصل إليها العلم يعد تكلفا منهيا عنه .", "ج - والخوض في المفاضلة بين الأصحاب وما شجر بينهم من خلاف إن الكلام في تفضيل أحد الصحابة على غيره - رضي الله عنهم أجمعين -", "(١) السيوطي : الاتقان في علوم القرآن : ٤/٢ . ط الحلبي مصر ١٣٧٠ه - ١٩٥١م.", "(٢) السابق : ٤/٢ .", "(٣) السابق : ٥/٢ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0108.png"}, {"n": 109, "paras": ["عمل ينطوي على تضييع للوقت في غير فائدة إذ كلهم عند الله له مكانته. كما أن الخوض فيما شجر بينهم من خلاف ، لابد أن يترتب عليه حرج لمن خاض وخروج عن أدب الإسلام في وجوب احترام الصحابة جميعا ، وهذا ليس بجائز شرعا ، وكيف يجوز لأحد وقد أثنى الله على الصحابة رضوان الله عليهم كما أثنى عليهم النبي ﷺ ، لقد وعدهم الله بالحسنى في قوله تعالى: ﴿ والسابقون الأولون من المهاجرين والأنصار والذين اتبعوهم بإحسان رضى الله عنهم ورضوا عنه ، وأعد لهم جنات تجري تحتها الأنهار خالدين فيها أبدا ذلك الفوز العظيم ﴾ (١). وقال سبحانه : ﴿ محمد رسول الله والذين معه أشداء على الكفار رحماء بينهم تراهم ركعا سجدا يبتغون فضلا من الله ورضوانا سيماهم في وجوههم من أثر السجود ذلك مثلهم في التوراة ، ومثلهم في الإنجيل كزرع أخرج شطأه فآزره فاستغلظ فاستوى على سوقه يعجب الزراع ليغيظ بهم الكفار ، وعد الله الذين آمنوا وعملوا الصالحات منهم مغفرة وأجرا عظيما ﴾ (٢). وأما ما ورد عنهم في السنة النبوية فمنه ما يلي : ما رواه الإمام مسلم بسنده عن أبي سعيد الخدري عن النبي ﷺ أنه قال : « لا تسبوا أصحابي ، فإن أحدكم لو أنفق مثل أحد ذهبا ما أدرك مد أحدهم ولا نصيفه » . وفي الصحيحين عن عمران بن حصين وغيره أن رسول الله ﷺ قال : « خير الناس قرني ثم الذين يلونهم ثم الذين يلونهم ، قال عمران ، فلا أدرى أذكر بعد قرنه قرنين أو ثلاثة » . وروى الترمذي عن عبد الله بن مغفل قال : سمعت رسول الله ﷺ يقول : « الله الله في أصحابي ، لا تتخذوهم غرضا بعدى ، فمن أحبهم فبحبي أحبهم ،", "(١) سورة التوبة : ١٠٠ . (٢) سورة الفتح : ٢٩"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0109.png"}, {"n": 110, "paras": ["ومن أبغضهم فبغضى أبغضهم ، ومن آذاهم فقد آذاني ومن آذاني فقد آذى الله تعالى ومن آذى الله يوشك أن يأخذه » (١) . وهكذا ترسم الآيات القرآنية والأحاديث النبوية أسلوب التعامل مع الصحابة رضوان الله عليهم ، بحيث لا يجوز لمسلم أن يحاسبهم على ما قدموا ، لأن ذلك موكول إلى الله تعالى وحده . والله تبارك وتعالى قد رضى عنهم ورضوا عنه وأعد لهم جنات تجرى من تحتها الأنهار وجعلهم خالدين فيها كما دلت على ذلك الآية الأولى . كما وعدهم سبحانه مغفرة وأجرا عظيما ، كما دلت على ذلك الآية الثانية . ذلك أدب الإسلام في الحديث عن الصحابة رضوان الله تعالى عليهم ، فكيف بذلك الذي يخوض فيما شجر بينهم من خلاف ؟. وكيف بمن يتعصب لبعضهم ، ويزرى ببعض ؟. وكيف بمن يسبهم أو يوجه إليهم اتهامات لا تحركها إلا الأحقاد والشياطين ؟ أين أولئك جميعا من تحذير الرسول ﷺ بقوله : « لا تسبوا أصحابي » ؟ إن أدب الإسلام ومنهجه ونظامه ، وهذا الأصل العظيم من أصول فهم الإسلام يستوجب على كل مسلم ألا يخوض في تفضيل بعض الصحابة على بعض ، فضلا عن أن يخوض فيما شجر بينهم من خلاف .", "(١) الترمذى : سننه : ٤ / ٣٦٠ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0110.png"}, {"n": 111, "paras": ["الأصل العاشر من أصول ركن الفهم :", "« معرفة الله تبارك وتعالى وتوحيده وتنزيهه أسمى عقائد الإسلام ، وآيات الصفات وأحاديثها الصحيحة وما يليق بذلك من التشابه ، نؤمن بها كما جاءت من غير تأويل ولا تعطيل ، ولا نتعرض لما جاء فيها من خلاف بين العلماء ، ويسعنا ما وسع رسول الله ﷺ وأصحابه ﴿ والراسخون في العلم يقولون آمنا به كل من عند ربنا ﴾ (١) .", "(١) سورة آل عمران : ٧."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0111.png"}, {"n": 112, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0112.png"}, {"n": 113, "paras": ["هذا الأصل هو أساس الاعتقاد الصحيح في الله سبحانه وتعالى ، وهو الذي يقوم عليه التوحيد كله ؛ وذلك أن أعرف الناس بالله سبحانه مَن كان متبعا للطريق الذي يوصل إليه سبحانه ، وهذا الطريق هو ما جاء به محمد ﷺ ، ولذلك سمى الله ما أنزل على محمد ﷺ روحا ونورا لتوقف الحياة والهداية عليه قال الله تعالى : ﴿ وكذلك أوحينا إليك روحا من أمرنا ، ما كنت تدرى ما الكتاب ولا الإيمان ولكن جعلناه نورا نهدى به من نشاء من عبادنا وإنك لتهدى إلى صراط مستقيم صراط الله الذي له ما في السموات وما في الأرض ألا إلى الله تصير الأمور ﴾(١).", "- فلا روح إلا فيما جاء به الرسول الخاتم ﷺ .", "- ولا نور إلا في الاهتداء به والتعرف بضوئه على كل ما في الحياة الدنيا من خير وبر .", "- ومعنى قوله تعالى : ﴿ ما كنت تدرى ما الكتاب ﴾ أى ما كنت تعرف القرآن قبل أن نوحى إليك .", "- ومعنى قوله : ﴿ ولا الإيمان ﴾ أى ما كنت تدرى الدعوة إلى الإيمان ، أو ما كنت تدرى شرائع الإيمان ومعالمه ومفرداته قبل أن نوحى إليك . ومن أجل ذلك نلقى ضوءا على هذا الأصل الهام من أصول فهم الإسلام ، نتحدث في نقطتين بارزتين : إحداهما : الطريق الصحيح إلى معرفة الله . والثانية : أبرز قضايا التوحيد .", "(١) سورة الشورى : ٥٢ - ٥٣ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0113.png"}, {"n": 114, "paras": ["أ - الطريق الصحيح إلى معرفة الله سبحانه وتعالى : دون دخول في متاهات الفلاسفة ، ودون استعانة بمراسم المتصوفة ، نؤكد أن معرفة الله تبارك وتعالى حق المعرفة ليس لها سوى طريق واحد هو : الاتباع والالتزام بكل ما جاء به محمد ﷺ من روح ونور وشفاء وهدى ورحمة .", "ومن لم يتبع ويلتزم ويسلم بذلك ، ولجأ إلى طريق آخر فقد ضل مهما استدل، وقد فجر مهما نظر ، لأنه معرض عن كتاب الله ، والإعراض عن كتاب الله ضلال عن معرفته سبحانه ، كما جاء ذلك في قوله تعالى : ﴿ فإما يأتينكم مني هدى ، فمن اتبع هداي فلا يضل ولا يشقى ، ومن أعرض عن ذكرى فإن له معيشة ضنكا ونحشره يوم القيامة أعمى ، قال رب لم حشرتني أعمى وقد كنت بصيرا قال كذلك أتتك آياتنا فنسيتها وكذلك اليوم تنسى ﴾ (١) .", "وأخرج عبد الرازق في المصنف من طريق ابن عيينة عن عطاء بن السائب قال: قال ابن عباس ، من قرأ القرآن فاتبع ما فيه هداه الله من الضلالة في الدنيا ووقاه يوم القيامة الحساب . وذلك أن الله تعالى يقول : ﴿ فمن اتبع هداي فلا يضل ولا يشقى ﴾ .", "واتباع ما جاء به الرسول ﷺ من روح ونور وشفاء هو التوحيد لله سبحانه، توحيد ربوبية وتوحيد ألوهية ، وذلك واجب كل مسلم مكلف ، وهو أول ما يدخل به الإنسان في الإسلام وآخر ما يخرج به من الدنيا كما قال رسول الله ﷺ : « من كان آخر كلامه عند الموت لا إله إلا الله دخل الجنة يوما من الدهر وإن أصابه ما أصابه » (٢) .", "(١) سورة طه : ١٢٣ - ١٢٦ .", "(٢) ابن حبان : صحيحه : بسنده عن أبي هريرة ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0114.png"}, {"n": 115, "paras": ["هذا هو الطريق الصحيح إلى معرفة الله تبارك وتعالى معرفة صحيحة تدخل في الإسلام وتنجى من عذاب النار ، ودع ما وراء ذلك مهما كان . ب - أبرز قضايا التوحيد : لا أدعى أني في هذه العجالة سأعالج أبرز قضايا التوحيد ، فإن لذلك مظانه من المطولات ، ولكني سأشير إلى أبرز هذه القضايا إشارات دالة وموجهة وهذا حسبى في هذا المجال من الكلام . اتفق علماء الإسلام على أن التوحيد يتضمن موضوعات ثلاثة : أولها : الكلام في صفات الله سبحانه . وثانيها : توحيد الربوبية وبيان أن الله وحده خالق كل شيئ . وثالثها : توحيد الإلهية وهو استحقاقه سبحانه أن يعبد وحده لا شريك له . وأوجبوا تنزيه الله تبارك وتعالى بتوحيده بكل هذه الأنواع من التوحيد ، والإيمان بها ، ولتوضيح ذلك قالوا : النقطة الأولى : الكلام في صفات الله : يجب الإيمان بصفات الله وأسمائه كما وردت عن المعصوم ﷺ دون تعطيل ولا تشبيه، لأن كلاً من التعطيل والتشبيه باطل يخرج عن الملة والعياذ بالله تعالى. فالذين عطلوا الصفات أو نفوها ضل ضلالهم ، وأدخل عليهم الشيطان الزيف والباطل فيما قالوا ، إذ قالوا : إن إثبات الصفات يستلزم تعدد واجب الوجود أى تعدد الله سبحانه وتعالى ، ولذلك نفوا الصفات كلها جريا وراء هذا الضلال.", "- وقد أفضى هذا القول بطائفة منهم إلى القول بالحلول أو الاتحاد ، وهذا أقبح من كفر النصارى الذي قالوا : إن الله ثالث ثلاثة .", "- ومما ترتب على قولهم ذاك أن فرعون وقومه كاملو الإيمان عارفون بالله على الحقيقة ،"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0115.png"}, {"n": 116, "paras": ["- وأن عباد الأصنام على الحق والصواب وأنهم إنما عبدوا الله لا غيره ،", "- وأنه لا فرق في التحريم بين الأم والأخت والأجنبية ،", "- ولا فرق بين الماء والخمر والنكاح والسفاح إذ الكل من عين واحدة. لا، بل قالوا : إنها هي العين الواحدة . فالذين نفوا الصفات أو عطلوها مخالفون للكتاب والسنة ، ولما كان عليه الصحابة والتابعون والسلف الصالح رضوان الله عليهم أجمعين . وأما المشبهة الذين يشبهون الله سبحانه بمخلوقاته ، ويصفونه بما يوصف به الناس ، فهم أمثال نفاة الصفات أو معطلوها ، لأن الله تبارك وتعالى يقول في نفسه { ليس كمثله شئ وهو السميع البصير } (١) . فهذه الآية الكريمة في صدرها { ليس كمثله شئ } رد على من شبهوا الله بمخلوقاته ومثلوه بهم ، فزعموا أنه له يدا ورجلا ورضا وغضبا ونزولا واستعلاء إلى غير ذلك من الصفات . وهذا ضلال عن سبيل الله وعما كان عليه رسول الله ﷺ وصحابته وما كن عليه ولا يزال عليه صالحو المؤمنين إلى يوم يقوم الناس لرب العالمين . وأما نهاية الآية : { وهو السميع البصير } فهي رد على من نفوا الصفات أو عطلوها ، وهم ضلال يتبعون غير الحق ويكفرون بالله وكتابه ورسله . فمن جعل صفات الله صفات خلقه فهو المشبه المبطل المذموم . ومن جعل صفات المخلوق مثل صفات الخالق فهو نظير النصارى في كفرهم. وقد اتفق أهل السنة على أن الله سبحانه ليس كمثله شئ لا في ذاته ولا في صفاته ولا في أفعاله .", "(١) سورة الشورى : ١١."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0116.png"}, {"n": 117, "paras": ["والأصل أن تثبت لله الصفات والأسماء دون تعطيل ولا تشبيه ، وإنما نصفه بما وصف به نفسه ، ويسعنا في هذا ما وسع رسول الله ﷺ وأصحابه كما قال تعالى : ﴿ والراسخون في العلم يقولون آمنا به كل من عند ربنا ﴾(١) . وفي قضية الصفات مذهبان : مذهب السلف : وخلاصته الإيمان بما ورد من هذه الصفات والأسماء في الكتاب والسنة ، مع ترك المقصود بها لله تبارك وتعالى ، فهم يثبتون العين واليد والاستواء والضحك والتعجب لله بمعان لا ندركها ويتركون الإحاطة بها إلى علم الله . وحجتهم في ذلك قول الرسول ﷺ : « تفكروا في خلق الله ولا تتفكروا في الله فإنكم لن تقدر وه قدره » . ومذهب الخلف : وخلاصته أنهم يؤمنون بهذه الصفات والأسماء كما وردت في القرآن الكريم ولكن لا يراد بها ظواهرها ، فهي من المجاز . وبناء على ذلك فهو يؤولون « اليد » بالقدرة و« الوجه » بالذات و« الاستواء » بالاستيلاء ، ويرون أنفسهم بذلك قد خرجوا من دائرتي التشبيه والتعطيل . ومن الواضح أن رأى السلف أقرب إلى ما كان عليه رسول الله ﷺ وأصحابه والتابعون رضوان الله عليهم ، والله سبحانه وتعالى أعلم بما يريد . النقطة الثانية : توحيد الربوبية : وهو : الإقرار بأن الله خالق كل شيء ، وأنه ليس للعالم صانعان متكافئان في الصفات والأفعال .", "(١) سورة آل عمران : ٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0117.png"}, {"n": 118, "paras": ["وهذا التوحيد حق لا ريب فيه ، وهو الغاية عند كثير من أهل النظر والكلام وطائفة من الصوفية . وهذا التوحيد لم يذهب إلى نقيضه طائفة معروفة من بني آدم ، بل القلوب مفطورة على الإقرار به أعظم من كونها مفطورة على الإقرار بغيره من الموجودات ، كما قالت الرسل عليهم السلام فيما حكى الله عنهم : ﴿ قالت رسلهم أفي الله شك فاطر السموات والأرض ﴾(١). وأشهر من عرف تجاهله وتظاهره بإنكار الصانع فرعون ، وقد كان مستيقنا به في الباطن ، كما قال له موسى عليه السلام : ﴿ لقد علمت ما أنزل هؤلاء إلا رب السموات والأرض بصائر ﴾(٢). النقطة الثالثة : توحيد الألوهية أو الإلهية : وهو الإقرار بأن الله وحده هو المستحق للعبادة ، أي يشهد ألا إله إلا الله أي لا معبود بحق إلا الله . وهذا التوحيد متضمن لتوحيد الربوبية الذي قدمنا ، وليس العكس ، فإن الكفار والمشركين يوحدون توحيد ربوبية فيقرون بأن الله خالق كل شئ ، لكن التوحيد الذي جاءت به الرسل عليهم السلام هو توحيد الإلهية المتضمن توحيد الربوبية . قال تعالى : ﴿ فأقم وجهك للدين حنيفا فطرة الله التي فطر الناس عليها لا تبديل لخلق الله ذلك الدين القيم ولكن أكثر الناس لا يعلمون ﴾(٣). وعبادة الله وحده لا شريك له لها إلتزامات كثيرة يمكن تلخيصها في كلمات", "(١) سورة إبراهيم : ١٠.", "(٢) سورة الإسراء : ١٠٢ نقلا عن : الطحاوي : شرح الطحاوية : ٢٦/١.", "(٣) سورة الروم : ٣٠."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0118.png"}, {"n": 119, "paras": ["هي : اتباع ما جاء به محمد ﷺ خاتم أنبياء الله ورسله ، وما يترتب على هذا الاتباع من التزام بالمنهج. ونختم الكلام في هذا الأصل العاشر من أصول ركن الفهم بقول الطحاوي رحمه الله : « ودين الله في الأرض والسماء واحد وهو دين الإسلام ، كما قال تعالى : ﴿ إن الدين عند الله الإسلام ﴾ (١). وقال تعالى : ﴿ ورضيت لكم الإسلام دينا ﴾ (٢). وهو بين الغلو والتقصير ، وبين التشبيه والتعطيل ، وبين الجبر والقدر وبين الأمن والإياس » (٣) .", "(١) سورة آل عمران : ١٩ .", "(٢) سورة المائدة : ٣", "(٣) الطحاوي : شرح الطحاوية : ٧٨٦/٢ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0119.png"}, {"n": 120, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0120.png"}, {"n": 121, "paras": ["الأصل الحادي عشر من أصول ركن الفهم", "« وكل بدعة في دين الله لا أصل لها - استحسنها الناس بأهوائهم سواء بالزيادة فيه أو النقص منه - ضلالة تجب محاربتها والقضاء عليها بأفضل الوسائل التي لا تؤدى إلى ما هو شر منها »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0121.png"}, {"n": 122, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0122.png"}, {"n": 123, "paras": ["ولكي نوضح هذا الأصل نقول : أ - تعريف البدعة : البدعة : الحدث وكل ما ابتدع في الدين بعد الإكمال . والفقهاء وعلماء الإسلام في تفسير البدعة على رأيين : الأول : للذين توسعوا في فهم مدلولها . حيث أطلقوها على كل حادث لم يوجد في الكتاب والسنة ، سواء أكان في العبادات أم العادات ، وسواء أكان مذموما أم غير مذموم . ومن أصحاب هذا الرأي : الشافعي ، والعز بن عبد السلام ، والنووي وغيرهم . ب - تقسيم البدعة :", "١ - بدعة واجبة : كالاشتغال بعلم النحو الذي يفهم به كلام الله تعالى فذلك واجب لأنه لابد منه لحفظ الشريعة ، وما لا يتم الواجب إلا به فهو واجب.", "٢ - وبدعة مُحَرَّمة : كمذهب القدرية والجبرية والمرجئة والخوارج.", "٣ - وبدعة مندوبة : مثل إحداث المدارس وبناء القناطر وصلاة التراويح جماعة في المسجد بإمام واحد .", "٤ - وبدعة مكروهة : مثل زخرفة المساجد وتزويق المصاحف .", "٥ - وبدعة مباحة : مثل المصافحة عقب الصلوات ، ومنها التوسع في اللذيذ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0123.png"}, {"n": 124, "paras": ["من المأكل والمشارب والملابس . ولهم في هذه التقسيمات أدلة وشواهد ، وقد روى في السنة ما يفيد تقسيم البدعة إلى حسنة وسيئة ، روى الإمام مسلم بسنده : « من سن سنة حسنة فله أجرها وأجر من عمل بها إلى يوم القيامة ، ومن سن سنة سيئة فعليه وزرها ووزر من عمل بها إلى يوم القيامة » . والثاني : من الرأيين للذين ضيقوا مفهومها وحصروها كلها في الضلالة وهؤلاء يرون أن كل أنواع البدعة ضلالة سواء ما كان منها في العبادات أو العادات . ومنه هؤلاء : الإمام مالك ، والشاطبي وغيرهما . ولهم في ذمها أدلة وشواهد كذلك ، ومن أبرز أدلتهم : ما أخرجه ابن ماجه بسنده عن العرباض بن سارية قال : قال رسول الله ﷺ : « ... وإياكم ومحدثات الأمور فإن كل محدثة بدعة وكل بدعة ضلالة » . والبدعة المحرمة أو المكروهة هي التي لا أصل لها ومع ذلك استحسنها الناس بأهوائهم ، فهي محرمة أو مكروهة لأنها لا أصل لها في الدين . هذه البدعة يجب محاربتها لأنها ضلالة زادت على الدين ما ليس منه أو نقصت منه ما هو منه ، كما يجب القضاء عليها بالوسيلة الملائمة التي لا تؤدى إلى ما هو شر منها . وذلك أن أصلا من أصول ديننا وركنا من أركانه وجزءاً رئيسا من منهجه : النهى عن المنكر ، ومع ذلك فإن النهى عن المنكر إذا كان يتسبب في منكر أشد يسكت عنه - كما أوضحنا في كتابنا فقه الدعوة إلى الله(١) - وهذا السكوت", "(١) الفصل الأول من الباب الرابع من هذا الكتاب : نشر دار الوفاء ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0124.png"}, {"n": 125, "paras": ["إلى حين تسنح الفرصة هو من صميم الحكمة التي طولبنا بها ونحن ندعو إلى الله على بصيرة ، كما جاء ذلك في قوله تعالى {ادع إلى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي أحسن} (١). وما يراه الإمام المؤسس في هذا الأصل هو من أبرز العوامل التي تؤدى إلى النجاح والفلاح في محاربة البدعة ، وعدم السكوت عليها من جانب وفى الدعوة إلى الله بالحكمة والموعظة الحسنة من جانب آخر . ولقد عرف عن الإمام أحمد بن تيمية رحمه الله أنه كان ينهى تلاميذه عن نهى التتار عن شرب الخمر ، لأن التتار كانوا إذا سكروا ناموا فخف شرهم عن المسلمين في سكرهم ونومهم ، ولكنهم إذا استيقظوا ولم يكن لهم شغل هتكو ا أعراض المسلمين أو سلبوا أموالهم أو قتلوهم . فيا سبحان الله !!! ما أعجب هذا الفقه وما أحكم هذا الفقيه !!!.", "(١) سورة النحل : ١٢٥."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0125.png"}, {"n": 126, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0126.png"}, {"n": 127, "paras": ["الأصل الثاني عشر من أصول الفهم :", "« والبدعة الإضافية والتركية ، والالتزام في العبادات المطلقة خلاف فقهي ، لكل فيه رأيه ، ولا بأس بتمحيص الحقيقة بالدليل والبرهان »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0127.png"}, {"n": 128, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0128.png"}, {"n": 129, "paras": ["ولابد لنا هنا من أن نذكر الحكم التكليفي للبدعة . أ - الحكم التكليفي للبدعة في العقيدة والعبادة والعادة وقد أشرنا من قبل إلى أن منها ما هو واجب ، ومنها ما هو مندوب وما هو حرام وما هو مكروه وما هو مباح ، وضربنا على ذلك الأمثلة ، ونحن نتحدث في الأصل الحادي عشر من أصول الفهم . ونضيف هنا أنواعا أخرى للبدعة هي :", "١ - البدعة في العقيدة : وهي محرمة بل قد تصل إلى الكفر ، وهي التي تؤدى إلى مخالفة معلوم من الدين بالضرورة ، كبدعة أهل الجاهلية التي حكى القرآن الكريم أمرها في قوله تعالى : ﴿ ما جعل الله من بحيرة ولا سائبة ولا وصيلة ولا حام ﴾(١) . وقد حدد العلماء لهذه البدعة المكفرة ضابطا هو أن يتفق العلماء على أن هذه البدعة كفر صراح لا شبهة فيه .", "٢ - والبدعة في العبادات : وهي قد تكون محرمة وقد تكون مكروهة وقد تكون مباحة : أ - أما المحرمة : فمثل التبتل والصيام قائما في الشمس والخصاء لقطع الشهوة في الجماع ، لما جاء في السنة من حديث الرهط الذين سألوا عن أعمال النبي ﷺ فكأنهم قد تقالوها ، إذ قالوا : وأين نحن من النبي ﷺ وقد غفر الله له ما تقدم من ذنبه وما تأخر ، فقال أحدهم : أما أنا فإني أصلى الليل أبدا ، وقال الآخر : أنا أصوم الدهر ولا أفطر ، وقال الآخر : أنا أعتزل النساء فلا أتزوج أبدا . فلما علم رسول الله ﷺ بذلك قال لهم : « أنتم الذين قلتم كذا وكذا .. أما", "(١) سورة المائدة : ١٠٣ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0129.png"}, {"n": 130, "paras": ["والله إني لأخشاكم لله وأتقاكم له ، ولكني أصوم وأفطر وأصلى وأرقد وأتزوج النساء ، فمن رغب عن سنتي فليس مني (١) . ب - وأما البدعة المكروهة فمثل الاجتماع عشية عرفة للدعاء لغير الحجاج فيها ، ومثل ذكر السلاطين في خطبة الجمعة للتعظيم ، أما الدعاء فسائغ ، ومثل زخرفة المساجد . ج - وأما البدعة المباحة ، فقد ضربنا لها مثلين أحدهما : المصافحة بين المسلمين عقب الصلوات ، إذ لا بأس بذلك وإن كنا لم نسمع عنه في حياة الرسول ﷺ وصحابته رضوان الله عليهم . ومثل التوسع في لذيذ المطاعم والمشارب والملابس بشرط ألا يصل إلى حد الإسراف لأن الإسراف مكروه في هذه المجالات .", "٣- والبدعة في العادات : وهي نوعان : أ- قد تكون مكروهة كالإسراف في المأكل والمشارب ونحوها . ب- وقد تكون مباحة كالتوسع في اللذيذ من المأكل والمشارب والملابس والمساكن ، ولبس الطيالسة وتوسيع الأكمام من غير إسراف ولا اختيال . وذهب قوم إلى أن الابتداع في العادات التي ليس لها تعلق بالعبادات جائز ، لأنه لو جازت المؤاخذة في الابتداع في العادات لوجب أن تعد كل العادات التي حدثت بعد الصدر الأول من المأكل والمشارب والملابس والمسائل النازلة بدعا مكروهات ، والتالي باطل لأنه لم يقل أحد بأن تلك العادات التي برزت بعد الصدر الأول مخالفة لهم ، ولأن العادات من الأشياء التي تدور مع الزمان والمكان (٢) .", "(١) رواه البخاري وغيره من أئمة الحديث .", "(٢) الموسوعة الفقهية ط ٢ الكويت ١٤٠٦ه - ١٩٨٦م بتصرف ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0130.png"}, {"n": 131, "paras": ["ب - حكم البدعة الإضافية والبدعة التركية : ونعود إلى ما أشار إليه الإمام البنا في تقسيمه للبدعة إلى : إضافية وتريكة ، فنقول : البدعة الإضافية : هي إضافة شيء لم يكن موجودا على وجه الابتداع . والبدعة التركية : هي ترك شيء كان موجودا على وجه الابتداع كذلك . وهما في الحكم سواء ، أى أن كلا منهما قد تكون : واجبا ، أو مندوبا ، أو حراما ، أو مكروها ، أو مباحا، وذلك حسب تقدير نوع البدعة . غير أن كلام الإمام المؤسس في هذا الأصل عن نوع البدعة الذي هو مكروه أو مندوب أو مباح ، بدليل أنه قال : خلاف فقهى ، ولم يختلف الفقهاء في الواجب والحرام ، وإنما كان اختلافهم فيما دون ذلك . وكذلك الشأن في الالتزام في العبادات : كأن يلزم الإنسان نفسه بأذكار بعينها أو أوراد بعينها . أو يلزم نفسه بصلاة أو صيام على وجه النافلة . فذلك كله موضع اختلاف بين الفقهاء ، ولا بأس في هذه الحالة من تمحيص الأدلة ثم الالتجاء إلى ما كان أقوى دليلا وأنصع برهانا ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0131.png"}, {"n": 132, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0132.png"}, {"n": 133, "paras": ["الأصل الثالث عشر من أصول الفهم", "« محبة الصالحين واحترامهم والثناء عليهم بما عرف من طيب أعمالهم قربة إلى الله تبارك وتعالى . والأولياء هم المذكورون في قوله تعالى ﴿ الذين آمنوا وكانوا يتقون﴾(١) . والكرامة ثابتة لهم بشرائطها الشرعية مع اعتقاد أنهم رضوان الله عليهم لا يملكون لأنفسهم نفعا ولا ضرا في حياتهم أو بعد مماتهم فضلا عن أن يهبوا شيئا من ذلك لغيرهم » .", "(١) سورة يونس : ٦٣ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0133.png"}, {"n": 134, "paras": ["هذا الكتاب هو الجزء الأول من سلسلة \"موسوعة الفقه الإسلامي\"، وهو يغطي أبواب الطهارة والصلاة.", "وقد اعتمدنا في إعداده على أمهات الكتب الفقهية، مع مراعاة التيسير والتبسيط ليكون مرجعاً لكل مسلم.", "نسأل الله أن ينفع به، وأن يجعله خالصاً لوجهه الكريم.", "المؤلف"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0134.png"}, {"n": 135, "paras": ["ولكي نوضح هذا الأصل فإن علينا أن نتحدث عن قضايا ثلاثة تتصل بهذا الأصل هي : الأولى : من هم الأولياء ؟ والثانية : ما الكرامات التي تثبت لهم شرعا ؟ والثالثة : ما موقف المسلمين منهم ؟. أما القضية الأولى وهي : أ- من هم الأولياء ؟ فنقول : الأولياء : كما جاء في كتب اللغة جمع ولي ، وهو القريب أو الناصر أو المقرب أو المنصور ، فإذا أضيفت الكلمة فقيل : ولى الله ، فمعناه : من ينصر الله بالالتزام بدينه أو من ينصره لأنه وليه المؤمن ، وقد وعد الله بنصره . أو القريب إلى الله باجتهاده في العبادة ، أو الذي قربه الله منه لأنه يجده دائما حيث أمره ولا يجده حيث نهاه . والآيات القرآنية الدالة على ذلك كثيرة ، قال الله تعالى : ﴿ إلا إن أولياء الله لا خوف عليهم ولا هم يحزنون الذين آمنوا وكانوا يتقون لهم البشرى في الحياة الدنيا وفي الآخرة ﴾(١) .. وقال تعالى : ﴿ واعتصموا بالله هو مولاكم فنعم المولى ونعم النصير ﴾(١). وقال سبحانه : ﴿ الله ولى الذين آمنوا يخرجهم من الظلمات إلى النور", "(١) سورة يونس : ٦٢ -٦٤. (٢) سورة الحج : ٧٨."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0135.png"}, {"n": 136, "paras": ["والذين كفروا أولياؤهم الطاغوت يخرجونهم من النور إلى الظلمات (١). وفى السنة النبوية أحاديث كثيرة نذكر منها : ما رواه البخارى بسنده عن أبي هريرة رضي الله عنه قال : قال رسول الله ﷺ : « لقد كان فيما قبلكم من الأمم ناس محدثون ، فإن يكن في أمتي أحد فإنه عمر» ورواه مسلم أيضا . وروى البخارى بسنده عن جابر بن عبد الله عنهما قال : لما حضرت أحد ، دعاني أبي من الليل ، فقال : ما أراني إلا مقتولا في أول من يقتل من أصحاب النبي ﷺ ، وإني لا أترك بعدى أعز منك غير نفس رسول الله ﷺ ، وإن على ديناً فاقضه ، واستوص بإخوانك خيراً . فأصحبنا فكان أول قتيل ، ودفنت معه آخر في قبره ، ثم لم تطب نفسي أن أتركه مع آخر فاستخرجته بعد ستة أشهر فإذا هو كيوم وضعته غير أذنه فجعلته في قبر على حدة » . وروى البخارى بسنده عن أنس رضي الله عنه أن رجلين من أصحاب النبي ﷺ خرجا من عند النبي في ليلة مظلمة ، ومعهما مثل المصباحين بين أيديهما ، فلما اقتربا صار مع كل واحد منهما واحد ، حتى أتى أهله « وفي رواية البخارى أيضا . أن الرجلين هما : أسيد بن حضير ، عباد بن بشر رضي الله عنهما . وروى البخارى بسنده عن عروة بن الزبير رضي الله عنه أن سعيد بن زيد بن عمرو بن نفيل رضي الله عنه خاصمته أمرأة هي - أروى بنت أوس - إلى مروان بن الحكم ، وادعت أنه أخذ شيئا من أرضها ، فقال سعيد : أنا كنت آخذ من أرضها شيئا بعد الذي سمعت من رسول الله ﷺ ؟ قال : ماذا سمعت من رسول الله ﷺ ؟", "(١) سورة البقرة : ٢٥٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0136.png"}, {"n": 137, "paras": ["قال : سمعت رسول الله ﷺ يقول : « من أخذ شبرا من أرض ظلما طوقه إلى سبع أرضين » . فقال له مروان : لا أسألك بينة بعد هذا . فقال : سعيد ، اللهم إن كانت كاذبة فأعم بصرها واقتلها في أرضها ، فقال : فما ماتت حتى ذهب بصرها ، وبينما هي تمشى في أرضها إذ وقعت في حفرة فماتت » ورواه مسلم أيضا عن طريق آخر . وفي هذا المجال أحاديث كثيرة صحيحة تثبت لبعض عباد الله الذين والوه ، كرامات رآها الناس رأى العين . أما تعريف الولى شرعا - كما جاء في كتب العقيدة وكتب الفقه - فهو : « العارف بالله وبصفاته المواظب على الطاعة المجتنب للمعصية - حسب الإمكان - المعرض عن الانهماك في اللذات والشهوات المباحة » . وقد سمى وليا لأن الله تبارك وتعالى تولى أمره ، فلم يكله إلى نفسه ولا لغيره لحظة ، لأنه يتولى عباده على الدوام . والآيات القرآنية الكريمة التي ذكرناها والأحاديث النبوية الشريفة التي سقناها آنفا ، تسهم في توضيح هذا التعريف . وأما القضية الثانية فهي : ب- وما الكرامات التي تثبت لهم شرعا ؟ فيقتضينا توضيحها أن نقول : الكرامة في الشريعة هي : « أمر خارق للعادة غير مقرون بدعوى النبوة ، ولا هو مقدمة لها ، يظهره الله على يد عبد صحيح الاعتقاد ظاهر الصلاح .", "- فالأمر الخارق للعادة : يشمل كل الخوارق ، ويخرج منه السحر والشعوذة، وغرائب المخترعات فليست خارقة للعادة بل معتادة وتعرف بالتعلم ، ولها قواعد"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0137.png"}, {"n": 138, "paras": ["يعرفها بعض الناس ، ويجهلها كثير منهم إلا أنها غريبة بالنسبة لمن يجهل قواعدها.", "- وأما أنه غير مقرون بدعوى النبوة : فلكي تخرج المعجزة فإنها مقرونة بدعوى النبوة .", "- وأما أنه ليس مقدمة لدعوى النبوة : فليخرج به الإرهاص ، والإرهاص أمر خارق للعادة يظهره الله قبل بعثة نبي تأسيسا للنبوة وتمهيدا لها كإظلال الغمامة لنبينا ﷺ قبل إرساله .", "- وأما أنه أمر يظهره الله على يد عبد صحيح الاعتقاد : فلكي تخرج عن ذلك الإهانة والاستدراج ، إذ الإهانة تظهر على يد مدعى النبوة كذبا ، والاستدراج يظهر على يد مدع الألوهية ، فهذان اعتقادهما فاسد لكفرهما .", "- وأما أمر يظهره الله عى يد عبد ظاهر الصلاح : فلكي يستثنى منه المعونة ، فإنها كذلك أمر خارق للعادة يظهره الله عى يد عبد مستور الحال - أى غير ظاهر الصلاح . فالكرامات بهذا التحديد الشرعى ثابتة للأولياء ، ما داموا صحيحى الاعتقاد ظاهرى الصلاح لا يدعون النبوة . وقد قام خلاف بين العلماء في إثباتها نشير إلى أبرز ما فيه فيما يلى : أولا : جمهور أهل السنة : وهؤلاء يرون أن الكرامة ممكنة عقلا وواقعة فعلا ، ويستدلون على إمكانها بأنها أمر لا يلزم من فرضه وقوع محال ، وكل ما كان كذلك فهو ممكن عقلا. ويستدلون على وقوعها بماجاء في القرآن الكريم من قصة السيدة مريم ، أم المسيح عليه السلام ، فإنها كانت في كفالة زكريا عليه السلام ، وكان لا يدخل عليها غيره ، وكان يجد عندها فاكهة الشتاء في الصيف ، وفاكهة الصيف في"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0138.png"}, {"n": 139, "paras": ["الشتاء ، قال الله تعالى : ﴿ كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يا مريم أنى لك هذا قالت هو من عند الله ... ﴾(١) . كما يستدلون على وقوعها بما جاء في القرآن الكريم من قصة أصحاب الكهف - وهم سبعة من أشراف الروم خافوا على دينهم من ملكهم بعد عيسى، فخرجوا من المدينة ودخلوا غارا ولبثوا فيه بلا طعام ولا شراب ثلاثمائة وتسع سنين نياما بلا آفة ، وبقصة آصف - وزير سليمان عليه السلام - وكان يعرف الاسم الأعظم فدعا الله أن يأتي بعرش بلقيس فأتى الله به في الحال ، وبما وقع من كرامات لبعض الصحابة رضوان الله عليهم ، مما ورد في الأحاديث النبوية التي ذكرنا آنفا . ثانيا : المعتزلة وبعض أهل السنة : وهؤلاء ذهبوا إلى عدم جواز الكرامة ، واستدلوا على ذلك بأن الكرامة لو ظهرت لكثرت بكثرة الأولياء ، فلا تكون خارقة للعادة ، وتخرج عن كونها كرامة. وأنها لو ظهرت لالتبست بالمعجزة فيلتبس النبي بالولى . وهذا رأى مرجوح . لأن الكرامة لو ظهرت لم تلتبس بالمعجزة للفرق الذي أوضحناه بينهما آنفا ، وبالتالى فلا يلتبس النبي بالولى . وأما أن كثرة الكرامات لكثرة الأولياء تخرجها عن كونها خارقة للعادة فهذا غير صحيح ، وإنما يترتب عليه فقط كثرة الخوارق ، ولا مانع من ذلك ولا ضرر فيه .", "(١) سورة آل عمران : ٣٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0139.png"}, {"n": 140, "paras": ["وأما القضية الثالثة وهي : ج - وما موقف المسلمين من هؤلاء الأولياء ؟ فيستدعينا أن نقول : إن على المسلمين أن يحبوا هؤلاء الأولياء الصالحين وأن يثنوا عليهم بما عرف عنهم من طيب أعمالهم ، وهذه المحبة لهم والثناء عليهم تقرب إلى الله سبحانه ، لأن الله يحب أولياءه ويحب فيهم عباده ، فحبهم والثناء عليهم بما هم أهل له قربة إلى الله تعالى .", "- غير أن ذلك الحب وذاك الثناء لا يبيح للمسلم أن يبالغ في حبهم أو يغالي في الحديث عما ثبت لهم من الكرامة والتكريم ، فإن هذا حرام منهى عنه لما يترتب عليه أحيانا من تقديس هؤلاء الأولياء أو وصفهم بصفات ليست لهم ، كما حدث ذلك في بعض الأحيان في تاريخ المسلمين ، مما أدى إلى كثير من الضلالات كاتخاذ المساجد على قبورهم ، وشد الرحال إليهم لزيارة قبورهم وهذا كله حرام لا خلاف في حرمته .", "- كذلك لا يجوز أن يثبت المسلم لهم الكرامات إلا بشرائطها الشرعية التي ذكرناها آنفا . كما لا يجوز لمسلم أن يعتقد أن أحد هؤلاء الأولياء الذين تثبت لهم هذه الكرامات يستطيع أن يملك لنفسه نفعا أو ضرا في الدنيا أو في الآخرة ، فضلا عن أن يستطيع ذلك لغيره من الناس ، وبالتالى فمن المحرم الالتجاء إليهم أو الاستشفاع بهم فضلا عن النذر لهم والذبح عند قبورهم ، كما يفعل من لا يعرفون الحلال والحرام من الناس . وبعد : فهذا الأصل من أصول فهم الإسلام - كما أوضحه الإمام المؤسس هو الذي"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0140.png"}, {"n": 141, "paras": ["يحرر عقيدة المسلم من الوهم والخرافة والدجل ، ويحول بينه وبين إضفاء بعض أفعال الله سبحانه على بعض عباده مهما كانوا أولياء صالحين ظاهرى الصلاح."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0141.png"}, {"n": 142, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0142.png"}, {"n": 143, "paras": ["الأصل الرابع عشر من أصول الفهم :", "« وزيارة القبور أيا كانت سنة مشروعة بالكيفية المأثورة ، ولكن الاستعانة بالمقبورين أيا كانوا ونداءهم لذلك وطلب قضاء الحاجات منهم عن قرب أو بعد والنذر لهم وتشييد القبور وسترها وإضاءتها والتمسح بها ، والحلف بغير الله ، وما يحلق بذلك من المتبدعات ؛ كبائر تجب محاربتها ، ولا نتأول لهذه الأعمال سدا للذريعة » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0143.png"}, {"n": 144, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0144.png"}, {"n": 145, "paras": ["زيارة القبور سنة من السنن التي هدانا إليها المعصوم ﷺ ، بل هي لون من ألوان تربية النفس ، وتذكيرها بالمصير المحتوم وهو الموت فالحساب فالجنة أو النار . والناس يلهيهم الأمل والتعلق بالحياة الدنيا عن الحياة الآخرة ، فإذا ما زاروا القبور رأوا بأعينهم مصائرهم ، وزال عنهم شدة تعلقهم بأعراض الحياة الدنيا - ذلك التعلق المهلى - ورضوا عنها بما يرضى الله سبحانه ، ويكون فيه اتباع لسنة المصطفى ﷺ . أ- مشروعية زيارة القبور : وقد اهتم بعض العلماء بزيارة القبور لما فيها من فوائد ، حتى بوب لها الإمام النووى في كتابه الجامع ، الوجيز : « رياض الصالحين من كلام سيد المرسلين : بباب : « استحباب زيارة القبور للرجال وما يقوله الزائر » . وقد وردت في زيارة القبور أحاديث نبوية كثيرة نذكر منها : ما رواه الإمام مسلم بسنده عن بريدة رضى الله عنه قال رسول الله ﷺ : « كنت نهيتكم عن زيارة القبور فزوروها » وفي رواية : « فمن أراد أن يزور القبور فليزر فإنها تذكرنا الآخرة » . وما رواه مسلم أيضا بسنده عن عائشة أم المؤمنين رضى الله عنها قالت : كان رسول ﷺ كلما كان ليلتها من رسول الله ﷺ يخرج من آخر الليل إلى البقيع فيقول : « السلام عليكم دار قوم مؤمنين وأتاكم ما توعدون ، غدا مؤجلون ، وإنا إن شاء الله بكم لاحقون ، اللهم اغفر لأهل بقيع الغرقد » . وما رواه الترمذى بسنده عن ابن عباس رضى الله عنهما قال : مر رسول الله ﷺ بقبور المدينة فأقبل عليهم بوجهه فقال : « السلام عليكم يا أهل القبور يغفر الله لنا ولكم ، أنتم سلفنا ونحن بالأثر » . وما رواه الإمام مسلم بسنده عن بريدة رضى الله عنه قال : كان النبي ﷺ"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0145.png"}, {"n": 146, "paras": ["يعلمهم إذا خرجوا إلى المقابر أن يقول قائلهم : « السلام عليكم يا أهل الديار من المؤمنين والمسلمين ، وإنا إن شاء الله بكم لاحقون ، أسأل الله لنا ولكم العافية ». ولقد ابتلى الناس بفتنة في زيارة قبور الصالحين ، حتى اتخذ بعض الناس هذه القبور مزارات ، بل عبد بعض الناس بعض المقبورين ، فأشركوا بالله ما لم ينزل به سلطانا. ولقد ابتليت الأمة الإسلامية بشئ من ذلك جر عليها شرا كثيرا. ومن أجل ألا يضل المسلمون في زيارة القبور ، نهى رسول الله ﷺ عن اتخاذ القبور مساجد محذرا أن يقع المسلمون في هذا الباطل والشر. فقد روى الإمام مسلم بسنده عن جندب بن عبد الله رضي الله عنه قال : سمعت رسول الله ﷺ قبل أن يموت بخمس وهو يقول : « إن من كان قبلكم كانوا يتخذون القبور مساجد ، فإني أنهاكم عن ذلك ». وقال : « لعن الله اليهود والنصارى اتخذوا من قبور أنبيائهم مساجد » . قال الإمام ابن تيمية رحمه الله : « وقد اتفق أئمة الإسلام على أنه لا يشرع بناء هذه المشاهد التي على القبور ولا يشرع اتخاذها مساجد ، ولا تشرع الصلاة عندها ، ولا يشرع قصدها لأجل التعبد عندها بصلاة واعتكاف أو استغاثة وابتهال ونحو ذلك ، وكرهوا الصلاة عندها ، ثم كثير منهم قال : الصلاة باطلة لأجل النهي عنها . وإنما السنة إذا زار مسلم قبر مسلم ميت إما نبي أو رجل صالح أو غيرهما ، أن يسلم عليه ويدعو له بمنزلة الصلاة على جنازته ، كما جمع الله بين هذين حيث يقول في المنافقين : ﴿ ولا تصل على أحد منهم مات أبدا ولا تقم على قبره﴾(١). فكان دليل الخطاب أن المؤمنين يصلى عليهم ويقام على قبورهم", "(١) سورة التوبة : ٨٤."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0146.png"}, {"n": 147, "paras": ["وفي السنن أن النبي ﷺ كان إذا دفن الميت من أصحابه يقوم على قبره ثم يقول : « سلوا له التثبيت فإن الآن يسأل » . وفي الصحيح أنه كان يعلم أصحابه أن يقولوا إذا رأوا القبور : « السلام عليكم أهل دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون ، ويرحم الله المستقدمين منا ومنكم والمستأخرين ، نسأل الله لنا ولكم العافية ، اللهم لا تحرمنا أجرهم ولا تفتنا بعدهم واغفر لنا ولهم » . وإنما دين الله تعالى تعظيم بيوت الله وهي المساجد التي تشرع فيه الصلوات جماعة وغير جماعة ، والاعتكاف وسائر العبادات البدنية والقلبية من القراءة والذكر والدعاء لله . وأما اتخاذ القبور أوثانا فهو من دين المشركين الذي نهى عنه سيد المرسلين ، والله تعالى يصلح حال جميع المسلمين (١) . هذا هو ما شرع في زيارة القبور كما قررته السنة النبوية وكما تحدث عنه العلماء المسلمون . ب - أهم الأعمال المحرمة بالنسبة للقبور : أما ما يحدث من جهلة الناس من أمور تتعلق بزيارة القبور قد يدخل بعضها في الشرك ، فيجب أن ننبه إلى هذه الأعمال المحرمة حتى تجتنب ، ومن هذه الأعمال:", "١ - الاستعانة بالمقبورين - وهذا حرام - لأن الاستعانة لا تكون إلا بالله سبحانه ، لقول الرسول ﷺ : « وإذا استعنت فاستعن بالله » . فلا يجوز الاستعانة بغير الله من نبي أو ولى فضلا عن صالحي المسلمين .", "٢ - والنداء على المقبورين للاستغاثة بهم ، والأصل كذلك أن الاستغاثة لا", "(١) ابن تيمية : مجموعة الرسائل والمسائل : ٥٩/١ - ٦٠ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0147.png"}, {"n": 148, "paras": ["تكون إلا بالله ، لأن الاستغاثة سؤال وطلب غوث ولا يملك الغوث إلا الله وقد جاء في الحديث الشريف : « ... إذا سألت فاسأل الله ... »", "٣- وطلب قضاء الحاجات منهم ، والأصل في ذلك كذلك ألا يكون إلا من الله سبحانه ، لأن الله سبحانه مالك كل شئ على وجه الحقيقة ومدبر كل أمر ، وطلب قضاء الحاجات من غيره سلب لملكه وإعجاز لغيره .", "٤- والنذر لهم ، والأصل في النذر أن يكون لله ، أما النذر لغيره سبحانه ففيه مظنة التقديس لغير الله وهو أدخل في الشرك منه في أي شئ آخر مهما حسنت النوايا. والنذر هو أن يوجب الإنسان على نفسه ما ليس بواجب ، وهو مشروع بالكتاب والسنة ، ففى الكتاب جاء قوله تعالى : ﴿ وما أنفقتم من نفقة أو نذرتم من نذر فإن الله يعلمه ﴾(١). وقوله تعالى : ﴿ يوفون بالنذر ويخافون يوما كان شره مستطيرا ﴾(٢) . وفى السنة : « من نذر أن يطيع الله فليطعه ومن نذر أن يعصيه فلا يعصه » رواه البخارى بسنده عن عائشة رضى الله عنها . والإسلام وإن كان شرع النذر إلا أنه لا يستحبه ، فقد روى البخارى بسنده عن ابن عمر رضى الله عنهما أن النبى ﷺ نهى عن النذر وقال : « إنه لا يأتى بخير ، وإنما يستخرج به من البخل » . ويصح النذر وينعقد إذا كان قربة لله تعالى ويجب حينئذ الوفاء به . ولا يصح إذا كان معصية ولا ينعقد كالنذر على القبور وعلى أهل المعاصى.", "٥- وتشييد القبور وسترها : فقد روى الإمام مسلم بسنده عن جابر رضى الله عنه قال : نهى رسول الله", "(١) سورة البقرة : ٢٧٠ . (٢) سورة الإنسان : ٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0148.png"}, {"n": 149, "paras": ["أن يجصص القبر ، وأن يُقعد عليه ، وأن يبنى عليه » . ومن السنة أن يرفع القبر عن الأرض قدر شبر ليعرف أنه قبر ويحرم رفعه زيادة على ذلك . روى الإمام مسلم بسنده عن أبي الهياج الأسدى قال : قال لى على بن أبى طالب : ألا أبعثك على ما بعثنى عليه رسول الله ﷺ : ألا تدع تمثالا إلا طمسته ولا قبرا مشرفا إلا سويته ، قال الترمذى : والعمل على هذا عند بعض أهل العلم يكرهون أن يرفع القبر فوق الأرض إلا بقدر ما يعرف أنه قبر ، لكيلا يوطأ ولا يجلس عليه » . ولا يحل ستر الأضرحة لما فيه من إنفاق المال في غير وجهه وفي غير غرض شرعى ، بل لما فيه من تضليل العامة من الناس . روى البخارى بسنده عن عائشة رضى الله عنها أن النبي ﷺ خرج من غزاة فأخذت غطاء فسترته على الباب فلما قدم رأى النمط فجذبه حتى هتكه ثم قال : « إن الله لم يأمرنا أن نكسو الحجارة والطين » .", "٦- وإضاءة القبور ، بوضع السرج فيها : فقد روى أحمد وأصحاب السنن إلا ابن ماجه عن ابن عباس رضى الله عنهما قال : لعن رسول الله ﷺ زائرات القبور والمتخذين عليها المساجد والسرج » .", "٧- والتمسح بالقبور والصلاة فيها ، فقد ورد أكثر من حديث نبوى ينهى عن اتخاذ القبور مساجد أو الصلاة في هذه القبور . فقد روى البخارى بسنده عن أبي هريرة - رضى الله عنه أن النبي ﷺ قال : « قاتل الله اليهود اتخذوا قبور أنبيائهم مساجد » وفى رواية : لعن الله اليهود ... » . كما حرم الإسلام الذبح عند القبور ، كما كان يفعل أهل الجاهلية ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0149.png"}, {"n": 150, "paras": ["فقد روى أبو داود بسنده عن أنس رضي الله عنه قال : قال رسول الله ﷺ : « لا عَقْرَ في الإسلام » قال عبد الرازق كانوا يعقرون عند القبر بقرة أو شاة .", "٨- والحلف بغير الله ، وذلك محرم نهى عنه النبي ﷺ . روى البخاري بسنده عن ابن عمر رضي الله عنهما عن النبي ﷺ قال : « إن الله تعالى ينهاكم أن تحلفوا بآبائكم ، فمن كان حالفاً فليحلف بالله أو ليصمت » . وروى أبو داود بسنده عن بريدة رضي الله عنها أن رسول الله ﷺ قال : « من حلف بالأمانة فليس منا » . وروى الترمذي بسنده عن ابن عمر رضي الله عنهما أنه سمع رجلا يقول : لا والكعبة ، فقال ابن عمر : لا تحلف بغير الله فإني سمعت رسول الله ﷺ يقول : « من حلف بغير الله فقد كفر أو أشرك » . وفسر بعض العلماء قوله : « كفر وأشرك » على التغليظ كما روى أن النبي ﷺ قال : « الرياء شرك » . وبعد : فكل هذه الأمور التي أشار إليها الإمام البنا في هذا الأصل - وهي التي شرحنا بهذا الإيجاز - وما يلحق بها من المبتدعات كبائر حرمها الله ، ويجب على كل مسلم أن يحاربها . وقد نبه الإمام المؤسس على أنه لا داعي للتأويل فيها أو في بعضها التماسا للأعذار ، وإنما الواجب ترك هذا التأول سدا للذريعة أي قطعا للشر والفساد. هذا هو السلوك الإسلامي الراشد البريء من الشوائب التي تجر إلى الكراهية أو الحرمة والمعصية ، بل ربما جرت إلى الكفر والشرك والعياذ بالله . وهكذا ينبغي أن يكون فهم الإسلام ، فهما يقوم على هذه الأصول العظيمة التي جمعها الإمام المؤسس من أمهات كتب العقيدة والفقه الإسلامي ، وبلغ بها عشرين أصلا ، على نحو ما سنوضح في الأصول التالية ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0150.png"}, {"n": 151, "paras": ["الأصل الخامس عشر من أصول ركن الفهم", "« والدعاء إذا قرن بالتوسل إلى الله بأحد من خلقه ، خلاف فرعى في كيفية الدعاء ، وليس من مسائل العقيدة » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0151.png"}, {"n": 152, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0152.png"}, {"n": 153, "paras": ["وحديثنا في هذا الأصل يتناول توضيح كلمتين : الدعاء ، والتوسل ، والله ولي التوفيق . أ- الدعاء : الدعاء في اللغة : الطلب . ودعا الله : ناداه واستعان به فيما يحتاج إليه ، ورجا منه الخير واستغاث به . ودعاه إلى الشيء حثه عليه ، قال تعالى : ﴿ قل أرأيتم إن أتاكم عذاب الله أو أتتكم الساعة أغير الله تدعون إن كنتم صادقين ﴾(١). وقال سبحانه : ﴿ وقال ربكم ادعوني استجب لكم ﴾(٢). وروى أبو داود بسنده عن النعمان بن بشير رضى الله عنهما عن النبي ﷺ قال : « الدعاء هو العبادة » . وللدعاء في الشريعة آداب عشرة كما عدها العلماء(٣) كل أدب منها يستند إلى حديث نبوى أو أكثر من حديث ، هذه الآداب العشرة هي :", "١- أن يترصد لدعائه الأوقات الشريفة كيوم عرفة وأيام رمضان ويوم الجمعة من كل أسبوع ووقت السحر من ساعات الليل .", "٢- وأن يغتنم الأحوال الشريفة ، كزحف الصفوف في سبيل الله ونزول الغيث وعند إقامة الصلوات المكتوبة .", "(١) سورة الأنعام : ٤٠ - ٤١. (٢) سورة غافر : ٦٠.", "(٣) للتوسع انظر إحياء علوم الدين للغزالي أبي حامد الجزء الأول."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0153.png"}, {"n": 154, "paras": ["٣- وأن يدعو مستقبل القبلة ويرفع يديه بحيث يرى بياض إبطيه .", "٤- وأن يخفض صوته بين المخافتة والجهر .", "٥- وأن لا يتكلف السجع في الدعاء لأن حال الداعي هو التضرع والسجع تكلف لا يناسب التضرع .", "٦- وأن يسيطر عليه التضرع والخشوع والرغبة والرهبة .", "٧- وأن يجزم في الدعاء ويوقن بالإجابة .", "٨- وأن يلح في الدعاء ويكرره ثلاثا ، وينبغي ألا يستبطئ الإجابة .", "٩- وأن يفتتح الدعاد بذكر الله فلا يبدأ بالسؤال .", "١٠- وأن يتخذ للدعاء أدبه الباطن وهو التوبة ورد المظالم والإقبال على الله. ب- التوسل : التوسل في اللغة : اتخاذ الوسيلة : والوسيلة ما يتقرب به إلى الغير ، وتوسل الإنسان إلى ربه أي تقرب إليه بعمل . وفي الشريعة : التوسل هو : التقرب إلى الله تعالى بطاعته وعبادته واتباع أنبيائه ورسله ، وبكل عمل يحبه الله ويرضاه قال الله تعالى : ﴿ يأيها الذين آمنوا اتقوا الله وابتغوا إليه الوسيلة وجاهدوا في سبيله لعلكم تفلحون ﴾(١) . وابتغوا إليه الوسيلة : أى اطلبوا ما يقربكم إليه وإلى ثوابه من فعل الطاعات والخيرات : وهذا التوسل نوعان : مشروع وغير مشروع", "(١) سورة المائدة : ٣٥."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0154.png"}, {"n": 155, "paras": ["فالتوسل المشروع : هو التوسل إلى الله بذاته وبأسمائه وصفاته العليا ، أو التوسل إليه بالطاعة والعمل الصالح ، أو التوسل إليه بدعاء أخيه المؤمن له . ولكل واحد من هذه التوسلات أدلة من الشرع :", "- فالتوسل إليه بذاته وأسمائه وصفاته ، أصله الشرعي قول الله تعالى : ﴿ ولله الأسماء الحسنى فادعوه بها وذروا الذين يلحدون في أسمائه سيجزون ما كانوا يعملون ﴾(١) . ، وما رواه أبو داود بسنده عن عبد الله بن بريدة - رضى الله عنه أن رسول الله ﷺ سمع رجلا يقول : اللهم إني أسألك بأني أشهد أنك الله لا إله إلا أنت الأحد الصمد الذي لم يلد ولم يولد ولم يكن له كفوا أحد ، فقال : « لقد سألت الله عز وجل باسمه الأعظم » وأخرجه الترمذى كذلك .", "- والتوسل إليه بالطاعة والعمل الصالح ، تأصيله الشرعي قول الله تعالى على لسان المؤمنين : ﴿ إياك نعبد وإياك نستعين ، اهدنا الصراط المستقيم صراط الذين أنعمت عيهم غير المغضوب عليهم ولا الضالين ﴾(٢) . ، فقدم الطاعة والعمل الصالح وهو : ﴿ إياك نعبد ﴾ - وعبادة الله أوسع في معناها من أداء الفرائض وحدها بل يدخل فيها كل عمل صالح شرعه الله - وروى الإمام مسلم بسنده عن ابن عباس رضى الله عنهما قال : كان رسول الله ﷺ إذا قام يتهجد قال : « اللهم ربنا لك الحمد أنت قيوم السموات والأرض ومن فيهن ، ولك الحمد أنت الحق ووعدك الحق ولقاؤك حق وقولك حق ، والجنة حق والنار حق والنبيون حق ، ومحمد حق والساعة حق ، اللهم لك أسلمت وبك آمنت وعليك توكلت وإليك أنبت وبك خاصمت وإليك حاكمت ، فاغفر لى ما قدمت وما أخرت وما أسررت وما أعلنت … » . فقدم الطاعة والعمل الصالح وهو الإيمان والإسلام والتوكل والإنابة متوسلا", "(١) سورة الأعراف : ١٨٠ . (٢) سورة الفاتحة : ٥-٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0155.png"}, {"n": 156, "paras": ["بها إلى الله سبحانه ثم طلب المغفرة .", "- والتوسل إليه سبحانه بدعاء أخيه المسلم له ، له أصل شرعي كذلك ، قال الله تعالى : ﴿ والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان ولا تجعل في قلوبنا غلا للذين آمنوا ربنا إنك غفور رحيم ﴾ (١) . وروى الترمذي بسنده عن عمر بن الخطاب رضي الله عنه قال : استأذنت النبي ﷺ في العمرة فأذن وقال : « لا تنسانا يا أخي من دعائك » وفي رواية قال : « أشركنا يا أخي في دعائك » قال عمر : فقال كلمة ما يسرني أن لي بها الدنيا . وأما التوسل غير المشروع ، أى المحرم فهو التوسل إلى الله بعمل مخالف لكتابه وسنة نبيه ﷺ كالتوسل إليه ببعض مخلوقاته من الملائكة والنبيين والصالحين دون متابعة لهم في أعمالهم الصالحة ، إذ الممنوع اتخاذ هؤلاء وسطاء بين الله سبحانه ومن يدعوه . فإذا كان التوسل إلى الله بذات الشخص المتوسل به فهو حرام ، وأصل ذلك التحريم في الشريعة قول الله تعالى : ﴿ ألا لله الدين الخالص والذين اتخذوا من دونه أولياء ما نعبدهم إلا ليقربونا إلى الله زلفى ، إن الله يحكم بينهم فيما هم فيه يختلفون إن الله لا يهدى من هو كاذب كفار ﴾ (٢) فقد رد الله سبحانه التقرب إليه بذوات الأشخاص دون ذات الله أسمائه وصفاته ، أو دون الطاعة والعمل الصالح، أو دعاء المؤمن لأخيه . رد الله سبحانه ذلك ولم يقبله . وإذا كان التوسل إليه سبحانه بجاه فلان أو حقه أو حرمته ، فهذا أيضا لم يشرع في الإسلام ، والأصل في عدم مشروعيته قوله تعالى : ﴿ وأن ليس للإنسان إلا ما سعى ، وأن سعيه سوف يرى ثم يجزاه الجزاء الأوفى ﴾ (٣) .", "(١) سورة الحشر : ١٠ . (٢) سورة الزمر : ٣ . (٣) سورة النجم : ٣٩ - ٤١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0156.png"}, {"n": 157, "paras": ["وإذا كان التوسل إلى الله تعالى بالإقسام على الله بالمتوسل له فهو غير مشروع كذلك وهذا التوسل فيه خطئان : خطأ الحلف بغير الله ، وخطأ التوسل بغير ما يجوز التوسل به ، بل إن الحلف على الله بفلان أن يقضى له حاجته فيه شرك والعياذ بالله. وعلى هذا التوسل غير المشروع أجمعت كلمة الأثبات من علماء المسلمين ولا عبرة بما أثاره بعض الذين لا يتحرون الدقة والتمحيص في أمور الدين لأنهم يقولون ما لا يؤبه له . والذي يقصده الإمام المؤسس من هذا الأصل أن الدعاء إلى الله إذا قرن بالتوسل إليه بأحد من خلقه مع تقدم الطاعة والعمل الصالح فبين العلماء فيه خلاف فرعى من مسائل العقيدة ، فما ينبغي أن يشغل الناس . أما كيفية الدعاء فالأفضل أن يكون بالأدعية المأثورة في نصوصنا الإسلامية من القرآن الكريم والسنة النبوية المطهرة ، مع مراعاة آداب الدعاء العشرة التي ذكرنا آنفا لأن كل أدب منها له أصله الشرعي . ولا يتصور أن الإمام المؤسس يقصد التوسل إلى الله بأحد من خلقه دون الطاعة والعمل الصالح ، فإن ذلك ليس محلا للخلاف بين الفقهاء وإنما هو مردود بالإجماع ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0157.png"}, {"n": 158, "paras": ["- أن يكون الميت قد مات في حياة الموصي.", "- أن يكون الموصى له قد قتل الموصي قتلاً يمنع من الميراث.", "- أن يرجع الموصي عن وصيته.", "- أن يرفض الموصى له الوصية بعد موت الموصي.", "- أن يهلك الموصى به قبل قبول الموصى له."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0158.png"}, {"n": 159, "paras": ["الأصل السادس عشر من الأصول العشرين لركن الفهم", "« والعرف الخاطئ لا يغير حقائق الألفاظ الشرعية ، بل يجب التأكد من حدود المعاني المقصود بها ، والوقوف عندها ، كما يجب الاحتراز من الخداع اللفظي في كل نواحي الدنيا والدين فالعبرة بالمسميات لا بالأسماء »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0159.png"}, {"n": 160, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0160.png"}, {"n": 161, "paras": ["من المسلم به في الإسلام أن الأعمال بالنيات ، وأن المقاصد معتبرة مرعية في كل قول أو عمل وفي كل فعل أو ترك يصدر من المسلم . وهذه المقاصد أو النوايا هي التي تفرق بين ما هو عادة وما هو عبادة . ومن المعروف الذي ليس محل جدل بين المسلمين أن العمل الواحد يقصد به أمر يكون عبادة ، ويقصد به شئ آخر فلا يكون كذلك ، بل من المسلم به كذلك أن القصد والنية في بعض الأحيان يحول العمل من إيمان إلى كفر ، كفعل السجود مثلا ، إذا كان بنية الخضوع لله سبحانه فهو إيمان ، وإذا كان السجود لصنم فهو كفر . هذا من المسلمات المعروفة في الإسلام لا يمارى فيها أحد من العارفين بالإسلام ، لأنه بديهي معلوم من الدين بالضرورة . ويترتب على ذلك أن يكون للمسلمين موقف محدد من أمرين مهمين : العرف الخاطئ ، والخداع اللفظي ، وهذا ما سوف نبينه في هذا الأصل السادس عشر من أصول فهم الإسلام . أ- العرف الخاطئ : العرف هو ما تعارف عليه الناس في عاداتهم ومعاملاتهم ، وهذا العرف ليس بواجب على المسلمين التمسك به إلا إذا لم يخالف شيئا مما جاءت به الشريعة الإسلامية في الفعل أو الترك . فإذا تعارف الناس في عاداتهم أو معاملاتهم على شئ وكان هذا مما لا يتفق مع مقاصد الشريعة ، فإنه لا يلزم أحدا من المسلمين مهما أجمع عليه الناس . وعلى سبيل المثال : فإن الناس في العصر الذي نعيشه الآن - العقد الأول من القرن الخامس عشر الهجرى - قد تعارفوا على أن ينادوا الزوجة باسم زوجها أو"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0161.png"}, {"n": 162, "paras": ["اسم عائلة الزوج - تقليدا لأهل الغرب في ذلك - وهذا عرف لكنه بكل تأكيد خاطئ لاصدامه مع نصوص الدين ، فقد روى البخاري ومسلم بسنديهما عن سعد بن أبي وقاص رضي الله عنه أن النبي ﷺ قال : « من ادعى إلى غير أبيه وهو يعلم أنه غير أبيه فالجنة عليه حرام » .", "كما رويا بسنديهما عن أبي هريرة رضي الله عنه عن النبي ﷺ قال : « لا ترغبوا عن آباءكم ، فمن رغب عن أبيه فقد كفر » .", "وروينا عن يزيد بن شريك بن طارق قال : رأيت عليا رضي الله عنه على المنبر يخطب فسمعته يقول : لا والله ما عندنا من كتاب نقرؤه إلا كتاب الله وما في هذه الصحيفة ، فنشرها فإذا فيها : أسنان الإبل وأشياء من الجراحات وفيها : قال رسول الله ﷺ : « المدينة حرم ما بين عير إلى ثور ، من أحدث فيها حدثا أو آوى محدثا فعليه لعنة الله والملائكة والناس أجمعين لا يقبل الله منه يوم القيامة صرفا ولا عدلا ، ذمة المسلمين واحدة يسعى بها أدناهم ، فمن أخفر مسلما فعليه لعنة الله والملائكة والناس أجمعين لا يقبل الله منه يوم القيامة صرفا ولا عدلا ، ومن ادعى إلى غير أبيه أو انتمى إلى غير مواليه فعليه لعنة الله والملائكة والناس أجمعين ، لا يقبل الله منه يوم القيامة صرفا ولا عدلا » .", "تلك هي نصوص الشريعة في أن يُدعى الرجل أو المرأة إلى غير أبيه أو أبيها ومهما شاع هذا العرف بين الناس الذين يرغبون في تقليد الغرب ويحبون أن تذوب شخصية المرأة المسلمة - التي قدرها الإسلام حق قدرها - في اسم زوجها أو اسم عائلته ، فإنه لا ينبغي أن يصرف المسلمين عن هذه النصوص ولا يجوز لهم أن يأخذوا به أو يتعاملوا معه مهما شاع بين الناس.", "تلك هي نصوص الشريعة في هذه القضية فهل يغيرها العرف الخاطئ ؟ اللهم لا ، وألف لا .", "إن ألفاظ النصوص الشرعية واضحة ، ومعرفة المقصود منها متوقف على معرفة"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0162.png"}, {"n": 163, "paras": ["قواعد اللغة العربية لغة القرآن والسنة ، بحيث لا يتعسف أحد في تفسيرها ولا يتكلف ولا يحملها ما لا تحتمل .", "ب- الخداع اللفظي : أحيانا يلجأ الناس إلى تسمية الأشياء بغير أسمائها خداعا للناس ووصولا إلى تحقيق أهداف معينة عند الخادعين . ولقد نبه الرسول ﷺ إلى أن ذلك سوف يقع وحذر منه في الحديث الشريف الذي رواه ابن ماجه بسنده عن مالك الأشعرى رضى الله عنه قال : قال رسول الله ﷺ : « ليشربن ناس من أمتى الخمر يسمونها بغير اسمها ، ويعزف على رءوسهم بالمعازف والمغنيات ، يخسف الله بهم الأرض ، ويجعل منهم القردة والخنازير» .", "فهذا الخداع اللفظي في تسمية الأشياء بغير أسمائها ما ينبغي أن يصرفنا عن الحق في مقصود الشريعة ويجب أن نحترز عنه فقد عمت فيه البلوى ، حتى إن بعض المسلمين الذين انخدعوا بالألفاظ في عصرنا هذا وخدعتهم ألفاظ مستوردة وافدة على الإسلام والمسلمين مثل : الديموقراطية والاشتراكية والحداثة وما إليها ، انخدعوا بها حتى حاولوا أن يجعلوا من الإسلام ديموقراطية واشتراكية وإسلاما حديثا.", "وهذا بعينه هو الخداع اللفظي ، إذ سموا الإسلام بغير ما سماه الله به ، وبغير ما هو في حاجة إليه ، مما يجرى على ألسنة الناس وتأخذ به أعرافهم ، فهل يجوز لنا أن ننخدع بهذه الألفاظ ويجرى وراء هذه الخداع ؟ اللهم لا ، وألف لا كذلك.", "والأمثلة على الخداع اللفظي كثيرة لا تكاد تحصى ، ولا نستطيع أن نستطرد فنعدد منها ما لا قبل لنا بالانتهاء منه ، ولكن حسبنا أن نقول : أئذا خدعنا الناس فسموا الزنا بغير اسمه - كما هو حادث فعلا في كثير من بلدان العالم ، أو"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0163.png"}, {"n": 164, "paras": ["سموا الخمر بغير اسمها ثم شاعت هذه التسميات وذاعت بين الناس ، فهل يستطيع أحد أن يغير حقيقة أن الله سبحانه حرم الزنا وحرم الخمر ؟.", "وقد تعارف الناس على كثير من هذه الأمور التي لا يبيحها الإسلام مخادعين عن أهدافهم الحقيقية بألفاظ خالبة ، مثل تعارفهم على الاستماع إلى امرأة تغنى باسم الفن والتمتع بالصوت الجميل واللحن الجميل ، أو تعارفهم على أن النظر إلى امرأة ترقص نوع من الفن كذلك أو استمتاع بجمال إيقاع حركات الجسم البشرى - كما هو حادث مثلا - فهل تغير هذه الألفاظ الخادعة من الحكم الشرعى لمثل هذه الأمور ؟ اللهم . لا .", "ويقاس على ذلك عشرات المفاسد التي أقرها العرف الجارى بين الناس وسماها الناس بغير اسمها مخادعين مضللين ، ثم مارسها كثير من الناس ذاهلين أو غافلين عن هذا الأصل العظيم من أصول فهم الإسلام ، وهو أن العرف الخاطئ لا يغير حقائق الألفاظ الشرعية ، بل يجب التأكد من حدود المعانى المقصودة بها والوقوف عندها ، مع عدم الانخداع بالألفاظ إذ العبرة بالمسميات لا بالأسماء ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0164.png"}, {"n": 165, "paras": ["الأصل السابع عشر من أصول ركن الفهم", "« والعقيدة أساس العلم ، وعمل القلب أهم من عمل الجارحة ، وتحصيل الكمال في كليهما مطلوب شرعا ، وإن اختلفت مرتبتا الطلب » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0165.png"}, {"n": 166, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0166.png"}, {"n": 167, "paras": ["وحديثنا عن هذا الأصل يتناول توضيح أمرين هامين هما : معنى أن العقيدة أساس العمل ، والأعمال بين القلوب والجوارح ، والله المستعان . أ - العقيدة أساس العمل : معنى أن العقيدة أساس العمل ، أن العمل أيا كان عمل قلب أو عمل جارحة - كما سنبين فيما بعد - ما لم يكن نابعا عن عقيدة وإيمان وترجمانا لذلك فلا وزن له ولا قيمة ، بدليل أن أعمال الكفار لا وزن لها ولا قيمة عند الله لأنه لم ينبع عن إيمان ويقين بصدق خاتم أنبيائه محمد ﷺ واقتناع راسخ بأن شريعة الإسلام أتم الشرائع وأكملها وأصلحها لكل زمان ومكان . كما أن الإيمان وحده أو الاعتقاد وحده دون أن تترجمه الأعمال الصالحة وتدل عليه ، لا ينفع صاحبه ولا يعفيه من إثم ترك العلم . هذه أمور مقررة في الإسلام لا يختلف عليها أحد من المسلمين ، غير أننا بحاجة إلى أن نؤصلها بذكر مصادرها الشرعية التي تدل عليها ، على النحو التالي : أما أن العقيدة والإيمان أساس العمل ، بحيث لا يقبل عمل دون عقيدة وإيمان فدليله قول الله تعالى : ﴿ وقال الذين لا يرجون لقاءنا لولا أنزل علينا الملائكة أو نرى ربنا ، لقد استكبروا في أنفسهم وعتوا عتوا كبيرا ، يوم يرون الملائكة لا بشرى يومئذ للمجرمين ويقولون حجرا محجورا ، وقدمنا إلى ما عملوا من عمل فجعلناه هباء منثورا ﴾(١). فهؤلاء الذين لم يؤمنوا لأنهم لا يرجون لقاء الله ولا يعتقدون في صدق ما جاءت به رسلهم إليهم ،", "(١) سورة الفرقان : ٢١ : ٢٣."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0167.png"}, {"n": 168, "paras": ["ويتعلمون - لفقد إيمانهم - بأنهم لم يؤمنوا لأسباب لديهم ، منها : أن الملائكة لم تنزل عليهم ، وأنهم لم يروا الله سبحانه . وهذا الذي جعلهم لا يؤمنون ، وكيف يؤمن من كان لا يرجو لقاء ربه ؟ مع أن هؤلاء لو تنزلت عليهم الملائكة أو لو رأوا ربهم ، ما كان لإيمانهم قيمة. وهم سيرون ربهم يوم القيامة وسيرون الملائكة كما طلبوا ذلك في الدنيا ، ولكن ذلك سيكون مصدر تنفير لهم لأنهم أجرموا في حق أنفسهم في الدنيا إذ طلبوا هذا وعلقوا عليه إيمانهم . وسوف يفزعهم ما يرون يوم القيامة ، ويستعيذون منه - كما كانوا يفعلون في الدنيا - ولكن لات حين استعاذة ؛ لأن الله سبحانه لم يقبل من أعمالهم التي كانوا يعملون في الدنيا شيئا حتى ذلك الذي يظهر فيه أنه خير أو بر أو إحسان إلى الآخرين ، لأنها أعمال لم تنبن على عقيدة وإيمان ، فكانت لذلك جديرة بعدم القبول ، فكانت هباء منثورا . وقال سبحانه : ﴿ إن الذين قالوا ربنا الله ثم استقاموا فلا خوف عليهم ولا هم يحزنون أولئك أصحاب الجنة خالدين فيها جزاء بما كانوا يعملون﴾(١). وفي الحديث الشريف ما رواه الإمام مسلم بسنده عن سفيان بن عبد الله رضى الله عنه قال : قلت يا رسول الله قل لى في الإسلام قولا لا أسأل عنه أحدا غيرك قال : « قل آمنت بالله ثم استقم » أى حقق الإيمان ثم اعمل عمل الطاعات وانته عن عمل المعاصى. فالعقيدة والإيمان بناء على هذه النصوص الإسلامية هي أساس العمل ، كما", "(١) سورة الأحقاف : ١٣ : ١٤ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0168.png"}, {"n": 169, "paras": ["أن العقيدة والإيمان دون عمل لا تنجى من عذاب النار ، بدليل أن الله تبارك وتعالى قد عطف العمل الصالح على الإيمان في كثير من آيات القرآن الكريم ، وجعله تعبيرا عنه . قال تعالى : ﴿ إن الذين آمنوا وعملوا الصالحات لهم جنات النعيم ﴾(١). وقال سبحانه : ﴿ والذين آمنوا وعملوا الصالحات لهم مغفرة وأجر كبير ﴾(٢). وقد جاء العمل الصالح معطوفا على الإيمان ومفسرا له في القرآن الكريم أكثر من سبعين مرة ، وما ذلك إلا لأن العمل الصالح هو ترجمان الإيمان والعقيدة . كما جاء في السنة النبوية المطهرة قول الرسول ﷺ : « ليس الإيمان بالتمنى ولكن ما وقر في القلب وصدقه العمل » . كما وردت في هذا المعنى أحاديث نبوية كثيرة . ب- الأعمال .. بين القلوب والجوارح : الأعمال التي يقوم بها الإنسان نوعان : أعمال قلب ، وأعمال جوارح . أما أعمال القلب فهي أهم من أعمال الجوارح لأن القلب وما ينعقد عليه هو الأساس الذي يقوم عليه عمل الجوارح ، والمؤمن مطالب بأن يحسن عمل قلبه وأن يحسن عمل جوارحه ، ولا يغنى إحسان واحد منهما عن إحسان الآخر ، إذ المؤمن مطالب بأن ينشد الكمال في عمل القلب وعمل الجارحة ، الكمال الذي يلائم بشريته أى في حدود الوسع الذي فطره الله عليه والطاقة التي منحها إياه ، فلا يكلف الله نفسا إلا وسعها .", "(١) سورة لقمان : ٨ . (٢) سورة فاطر : ٧ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0169.png"}, {"n": 170, "paras": ["لكن على الناس أن يتنافسوا في طلب الكمال لأعمال القلب وأعمال الجوارح لأن الشريعة طالبت بهذه الأعمال في صورتها البشرية الكاملة. فما هي أعمال القلوب وأعمال الجوارح على وجه التمثيل والاستشهاد ؟ الإيمان ، والإحسان ، واليقين ، والتوكل ، والإنابة ، والحمد ، والشكر ، والخوف ، والرجاء ، والصبر ، والصدق ، والتقوى ، والمراقبة لله ، والخشوع ، والورع ، والحلم ، والعفو ، والحب ، والبغض ، والرضى ، والرحمة . وغير ذلك من الصفات التي ترضى الله تبارك وتعالى ، لأن الشريعة الإسلامية حثت عليها وطالبت بالتحلى بها. وهذه الأعمال في جانب الخير : كما أن من أعمال القلوب ما يلى : النفاق ، والرياء ، والحسد ، والحقد ، والغرور ، والعجب ، والسخط ، والجزع ، والهلع ، والغضب ، والإسراف ، والتقتير ، والبخل ، والجبن ، والكسل ، والعجز ، والغيبة ، والنميمة ، والغدر ، والخداع ، والخيانة ، وهذه الأعمال في جانب الشر. وغير ذلك من الصفات التي تغضب الله تبارك وتعالى ، لأن الشريعة الإسلامية نهت عنها وأمرت بالتخلى عن الاتصاف بها . وما هي أعمال الجوارح على وجه التمثيل والاستشهاد ؟ من أعمال الجوارح ما يلى : الصلاة ، والصيام ، والزكاة ، والحج لمن استطاع ، والصدقة ، والعمل ، والسعى في الأرض ، والجهاد ، والذكر ، والتلاوة ، وتجهيز الغزاة في سبيل الله ، وفعل الخير ، والبر ، وبذل الجهد في خدمة المسلمين . وغير ذلك من الأعمال التي ترضى الله تبارك وتعالى ، لأن الشريعة الإسلامية"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0170.png"}, {"n": 171, "paras": ["طالبت بها على سبيل الفريضة أو النافلة ، والشريعة لا تطالب إلا بما يحقق مصلحة الناس في معاشهم ومعادهم . وهذا الأعمال في جانب الخير . كما أن من أعمال الجوارح ما يلي : السرقة ، والزنا ، وأكل الربا ، وأكل مال اليتيم ، وتطفيف المكيال والميزان ، والبذاء ، وقذف المحصنين والمحصنات ، والسعى بين الناس بالشر ، والفساد ، والإفساد ، وإيقاع الأذى بالآخرين في غير حد من حدود الله ، والكذب ، والغش ، والاستماع إلى اللهو والباطل ، ورؤية عورات الناس ، أو تتبعها . وغير ذلك من الأعمال الكثيرة التي تغضب الله ، لأن الشريعة الإسلامية حرمتها وطالبت الناس بألا يمارسوها ، بل أمرتهم ألا يمارسوا مقدماتها ودواعيها. وسواء أكان العمل عمل قلب أو عمل جارحة ، فما دام في الخير ومما طالبت به شريعة الإسلام ، فإن الإنسان مطالب أن ينشد في هذا العمل الكمال على قدر ما تطيق بشريته ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0171.png"}, {"n": 172, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0172.png"}, {"n": 173, "paras": ["الأصل الثامن عشر من أصول فهم الإسلام", "والإسلام يحرر العقل ويحث على النظر في الكون ، ويرفع قدر العلم ، ويرحب بالصالح النافع من كل شيء ، والحكمة ضالة المؤمن أنى وجدها فهو أحق الناس بها »"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0173.png"}, {"n": 174, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0174.png"}, {"n": 175, "paras": ["ولكي نوضح هذا الأصل لابد أن نتكلم في إيجاز عن ثلاث نقاط : الأولى : تحرير الإسلام للعقل ، الثانية : دعوته إلى النظر في الكون ، الثالثة : رفعه من قدر العلم والعلماء . والله المستعان . أ- تحرير الإسلام للعقل : الإسلام يحرر العقل بمعنى أن يخلصه من الخرافة والوهم والدجل والترهات والأباطيل ، ذلك أن العقل البشرى بهذه الخلقة التي خلقه الله عليها هو من أكبر النعم التي أنعم الله على الإنسان بل هو أكبرها بعد الإيمان ، لذلك لم يكن عجباً أن جعله الله سبحانه مناط التكليف ، ورفع الإثم والحرج عمن فقده أو حرمه أصلا . هذا العقل بما أتاح الله له من قدرات ، كان وما يزال فتنة لكثير من الناس قديما وحديثا ، حتى لقد ضل فيه وضل به خلق كثيرون ، كان هذا الضلال بالعقل قبل الإسلام كما كان بعده . ومن المسلمين فرقة فتنت بالعقل هي فرقة « المعتزلة » وما تفرع عنها من فرق ، ولا يزال لهم أتباع يعيشون بين المسلمين اليوم . ولقد حرر الإسلام العقل من كثير من عيوبه التي ألحقها به المفتونون بالعقل قديما وحديثا . حرره أولا من المقررات التي لم تقم على اليقين والعلم ، وإنما قامت على الظن أو الخرافة أو التقليد . بل نص الإسلام على الذين يعتمدون على التقليد دون أن يعلموا عقولهم ،"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0175.png"}, {"n": 176, "paras": ["فقال سبحانه: ﴿ وقالوا بل نتبع ما ألفينا عليه آباءنا ، أو لو كان آباؤهم لا يعلمون شيئا ولا يهتدون ﴾(١).", "- ثم حرره من النظرة العجلى غير المتأنية ، وإصدار الحكم دون تريث وأناة ، وتلك آفات العقل عندما يضل ، فنادت آيات القرآن الكريم على الناس كل الناس وعلى الإنسان فردا ، فقررت ضرورة التثبت والتأكد قبل إصدار الحكم ، بل جعلت التثبت والتأكد أصلا وأساسا ، قال الله تعالى: ﴿ ولا تقف ما ليس لك به علم ، إن السمع والبصر والفؤاد كل أولئك كان عنه مسئولا ﴾(٢). وقال سبحانه وتعالى: ﴿ يأيها الذين آمنوا إن جاءكم فاسق بنبأ فتبينوا أن تصيبوا قوما بجهالة فتصبحوا على ما فعلتم نادمين ﴾(٣).", "- وحرره من البلادة والكسل فطالبه بالعمل والنشاط والتفكر الدائم والتدبر فيما يحيط به من نواميس الكون الذي يعيش فيه ، وهي نواميس خاضعة لنظام دقيق وتناسق ملفت ، وأداء منتظم ، حتى يتعلم الإنسان من ذلك كله ما يعود عليه بالنفع والفائدة قال الله تعالى: ﴿ وفى الأرض آيات للموقنين وفي أنفسكم أفلا تبصرون ﴾(٤). وقال سبحانه: ﴿ أو لم يروا كيف يبدئ الله الخلق ثم يعيده إن ذلك على الله يسير ، قل سيروا في الأرض فانظروا كيف بدأ الخلق ثم ينشئ النشأة الآخرة إن الله على كل شئ قدير ﴾(٥). وقد دعا رسول الله ﷺ إلى إعمال العقل وجعله الوسيلة لاستخراج الدلالة والحجة ، فعن البراء بن عازب رضى الله عنه قال: كثرت المسائل يوما على رسول الله ﷺ فقال: « يأيها الناس ، إن لكل شئ مطية ومطية المرء العقل ، وأحسنكم دلالة ومعرفة بالحجة أفضلكم عقلا »(٦).", "(١) سورة البقرة : ١٧٠ . (٢) سورة الإسراء : ٣٦ .", "(٣) سورة الحجرات : ٦ . (٤) سورة الذاريات : ٢٠ - ٢١ .", "(٥) سورة العنكبوت : ١٩ . (٦) الغزالي : إحياء علوم الدين - ابن المجد ١/ ٧٤ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0176.png"}, {"n": 177, "paras": ["بل إن الرسول ﷺ يؤكد أن العقل هو ملاك الإيمان والدين وعمارة الآخرة ، روى ابن الحبر والترمذى في النوادر بسنديهما عن ابن عباس رضى الله عنهما قال : قال رسول الله ﷺ : « لكل شيء آلة وعدة وإن آلة المؤمن العقل ، ولكل شيء مطية ومطية المرء العقل ، ولكل شيء دعامة ودعامة الدين العقل ، ولكل قوم غاية وغاية العباد العقل ، ولكل قوم داع وداعى العابدين العقل ، ولكل تاجر بضاعة ، وبضاعة المجتهدين العقل ، ولكل أهل بيت قيم ، وقيم بيوت الصديقين العقل ، ولكل خراب عمارة ، وعمارة الآخرة العقل ، ولكل امرئ عقب ينسب إليه ، ويذكر به ، وعقب الصديقين الذي ينتسبون إليه ويذكرون به العقل ، ولكل سفر فسطاط وفسطاط المؤمنين العقل » .", "ب - الدعوة إلى النظر في الكون : دعا الإسلام الناس إلى النظر في الكون والتأمل فيه ، لينطلق الفكر من عقاله ، ويتحول من النظر إلى العمل والممارسة ، فيحيا حياته الإنسانية الجديرة بكرامة الإنسان وتكريم الله له وتفضيله إياه على كثير من خلقه ، فقال سبحانه : ﴿ إن في خلق السموات والأرض واختلاف الليل والنهار لآيات لأولى الألباب الذين يذكرون الله قياما وقعودا وعلى جنوبهم ويتفكرون في خلق السموات والأرض ، ربنا ما خلقت هذا باطلا سبحانك فقنا عذاب النار ﴾ (٢) . ودعاه إلى التعمق في النظر في أحوال الأمم السابقة ، وتاريخ البشرية التي سبقته على هذه الأرض ليستفيد ويفيد ، فقال تعالى ﴿ قد خلت من قبلكم سنن فسيروا في الأرض فانظروا كيف كان عاقبة المكذبين ، هذا بيان للناس وهدى وموعظة للمتقين ﴾ (٣) . بل جعل الله النظر في أحوال السابقين معيارا لصلاح اللاحقين ، فقال جل شأنه : ﴿ ولقد أهلكنا القرون من قبلكم لما ظلموا وجاءتهم رسلهم بالبينات", "(١) السابق : ٧٥/١ .", "(٢) سورة آل عمران ١٩٠ - ١٩١ .", "(٣) سورة آل عمران : ١٣٧ - ١٣٨ .", "(٤) سورة الحج : ٤٠ - ٤١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0177.png"}, {"n": 178, "paras": ["وما كانوا ليؤمنوا كذلك نجزي القوم المجرمين ، ثم جعلناكم خلائف في الأرض من بعدهم للنظر كيف تعملون (١). إلى غير ذلك من الآيات القرآنية الكثيرة الداعية إلى النظر في الكون وفي تاريخ الأمم السابقة ، لأخذ العظة والعبرة ، ومعرفة السلوك الراشد والعمل الصالح النافع في الدنيا والآخرة .", "ج - وتقدير الإسلام للعلم : يقول الإمام المؤسس : « والإسلام يرفع قدر العلم ويرحب بالصالح النافع من كل شئ ، والحكمة ضالة المؤمن أنى وجدها فهو أحق الناس بها » . وإن الاستدلال على أن الإسلام يرفع من قدر العلم والعلماء ليضع بين أيدينا عشرات النصوص الإسلامية من آيات قرآنية كريمة ، وأحاديث نبوية شريفة ، نسوق منها ما يلي : قال الله تعالى : ﴿ شهد الله أنه لا إله إلا هو والملائكة وأولو العلم قائما بالقسط ﴾ (٢) ، فبدأ سبحانه ثم ثنى بالملائكة وثلث بأهل العلم ، وليس وراء ذلك تشريف أو تكريم للعلم والعلماء . وقال سبحانه : ﴿ وليعلم الذين أوتوا العلم أنه الحق من ربك فيؤمنوا به فتخبت له قلوبهم وإن الله لهاد الذين آمنوا إلى صراط مستقيم ﴾ (٣) . وقال جل شأنه : ﴿ بل هو آيات بينات في صدور الذين أوتوت العلم وما يجحد بآياتنا إلا الظالمون ﴾ (٤) . وقال سبحانه : ﴿ يرفع الله الذين آمنوا منكم والذين أتوا العلم درجات ﴾ (٥) .", "(١) سورة الحج : ٤٠-٤١ .", "(٢) سورة آل عمران : ١٨ .", "(٣) سورة الحج : ٥٤ .", "(٤) سورة العنكبوت : ٤٩ .", "(٥) سورة المجادلة : ١١ ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0178.png"}, {"n": 179, "paras": ["وجاءت في السنة النبوية المطهرة جملة أحاديث نذكر منها ما يلي: ما رواه أبو داود وابن ماجه وغيرهم بأسانيدهم عن أبي الدرداء رضى الله عنه قال: قال رسول الله ﷺ: « العلماء ورثة الأنبياء » ومن المعلوم أنه لا رتبة فوق رتبة النبوة، والعلماء ورثة الأنبياء أصحاب أرفع رتبة في البشر على الإطلاق، لاصطفاء الله لهم واختيارهم ليبلغوا عنه عباده ما يوحيه إليهم. وروى أبو داود وغيره بأسانيدهم عن أبي الدرداء رضى الله عنه قال: قال رسول الله ﷺ: « يستغفر للعالم ما في السموات والأرض ... » قال أبو حامد الغزالي في التعليق على هذا الحديث: « وأى منصب يزيد على منصب من تشتغل ملائكة السموات والأرض بالاستغفار له، فهو مشغول بنفسه وهم مشغولون بالاستغفار له ». وروى ابن حبان بسنده عن ابن عباس رضى الله عنه قال: قال رسول الله ﷺ: « أقرب الناس من درجة النبوة أهل العلم والجهاد، أما أهل العلم فدلوا الناس على ما جاءت به الرسل، وأما أهل الجهاد، فجاهدوا بأسيافهم على ما جاءت به الرسل ». وهذه الآيات والأحاديث كلها في العلم والعلماء الذين ينتمون بعلمهم إلى الإسلام أو علم الدين . فما مكان علم الدنيا من الإسلام ؟. من المعروف المسلم به أن الإسلام دعا الإنسان إلى تعلم علوم الدنيا، بل التعمق فيها، حين دعاه إلى ضرورة الاستفادة من هذا الكون وما أودع الله للناس فيه من خيرات ومنافع، قال الله تعالى مخاطبا الناس في هذا المجال: ﴿ ولقد مكناكم في الأرض وجعلنا لكم فيها معايش ﴾(١). وقال سبحانه: ﴿ فامشوا في مناكبها وكلوا من رزقه ﴾(٢). وقال جل شأنه: ﴿ وعلمناه صنعة لبوس ﴾.", "(١) سورة الأعراف: ١٠. (٢) سورة الملك: ٦."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0179.png"}, {"n": 180, "paras": ["لكم لتحصنكم من بأسكم (١). وقال سبحانه : ﴿ أو لم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم كانوا أشد منهم قوة وأثاروا الأرض وعمروها أكثر مما عمروها ، وجاءتهم رسلهم بالبينات فما كان الله ليظلمهم ولكن كانوا أنفسهم يظلمون ﴾ (٢).", "وإن هذه الآيات لتدل على أن العلم والتقنية التي تخدم الحياة ؛ مطلب من مطالب الإسلام ، وهذا المطلب قد وعاه أسلافنا من المسلمين وعملوا له بل برعوا فيه في مجالات عديدة منها ما يلي :", "- العلم بكل فروعه التي أتيحت لهم أو التي اكتشفوها وكانوا من روادها وبخاصة في مجالات الطب والرياضيات والطبيعة والمنطق وغيرها ،", "- والسياسة وفروعها وما ينبغي أن تدور عليه سياسة الدولة في الداخل أو في الخارج من أسس وأركان ، وكان لهم في ذلك قصب السبق ، بدليل اتساع رقعة الحكم إلى الحد الذي شمل نصف الكرة الأرضية كلها أو ما يزيد على ذلك .", "- والحرب ونظامها وآدابها وآلاتها وأدواتها.", "- والكشف والاختراع ،", "- والفقه والتشريع ،", "ولقد فهم المسلمون سريعا ما ترك المصريون القدماء والإغريق والهنود وغيرهم من تراث علمي في الطب والفلك والفيزياء والرياضيات وغيرها ، ثم لم يكتفوا بأن يظلوا نقلة، وإنما عكفوا على هذه الأصول والجذور يزيدون عليها ويجددون فيها ، ويضيفون إليها في كل فرع من الفروع ما جعلهم أساتذة يشار إليهم.", "وإن أوربا في عصر نهضتها العلمية قد أخذت من العلوم التي تفوق فيها المسلمون وبنت عليها وأضافت فوصلت إلى ما وصلت إليه ، ولقد قرر ذلك", "(١) سورة الأنبياء : ٨٠. (٢) سورة الروم : ٩."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0180.png"}, {"n": 181, "paras": ["كثير من الأوربيين أنفسهم . بل إن المذهب التجريبي في العلم الذي قام عليه العلم في أوربا هو باعترافهم تراث إسلامي أصيل - ولكنهم يقولون عربي لا إسلامي - اعترف بذلك المنصفون منهم ، بل الحاقدون على الإسلام والمسلمين من أمثال : « هاملتون جب » في كتابه الخبيث الهدف والمحتوى : « الاتجاهات الحديث في الإسلام » لقد اعترف هذا الحاقد بصراحة أن المنهج التجريبي الحديث انتقل إلى أوربا - في العصور الوسطى ( بالنسبة لأوربا إذ واكبت هذه التسمية : « العصور الوسطى » عند الأوربيين عصور الظلام والتخلف ، بينما كانت هذه الحقبة تعنى عند المسلمين عصور الازدهار والتقدم ) .", "فكل علم صالح نافع يرحب الإسلام به ويدعو إليه ، بل يراه واجبا على المسلمين وجوب كفاية وأحيانا وجوبا عينياً ، وذلك أن العلم حكمة والحكمة ضالة المؤمن أنى وجدها فهو أحق الناس بها . فقد روى أبو نعيم في الحلية قول الرسول ﷺ : « إن الحكمة تزيد الشريف شرفا ، وترفع المملوك حتى يدرك مدارك الملوك» .", "ونعود فنقول : إن الحكمة ضالة المؤمن يبحث عنها في كل مجال وفي كل مظنة ، دون ملل أو تقصير ، فإذا وجدها فهو أولى الناس بها ، وإنما كان أولى الناس بها لأنه مطالب بأن يحصل عليها وأن يسخرها للاستفادة بها في دنياه وآخرته ، وكل علم يوصل المسلم إلى مصلحة ونفع في دنياه وآخرته فمن الواجب عليه أن يصل إليه .", "وإن شريعة الله لتؤكد في كل فروعها ومفرداتها أنها لصالح الإنسان في معاشه ومعاده ، حتى إن الإمام ابن القيم رحمه الله يقول : « حيثما وجدت المصلحة فثم شرع الله ، ما دام لا يوجد نص » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0181.png"}, {"n": 182, "paras": ["ومن المعروف أن النص الشرعى لا يمكن أن يأتي بغير مصلحة المكلف في دنياه وآخرته ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0182.png"}, {"n": 183, "paras": ["الأصل التاسع عشر من الأصول العشرين لركن الفهم", "« وقد يتناول كل من النظر الشرعي والنظر العقلى ما لا يدخل في دائرة الآخر ، ولكنهما لن يختلفا في القطعى ، فلن تصطدم حقيقة علمية صحيحة وقاعدة شرعية ثابتة ، ويؤول الظنى منهما ليتفق مع القطعى ، فإن كانا ظنيين فالنظر الشرعى أولى بالاتباع حتى يثبت العقلى أو ينهار » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0183.png"}, {"n": 184, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0184.png"}, {"n": 185, "paras": ["لا تعارض بين العقل والنقل : من الحقائق المؤكدة أن الشريعة الإسلامية ليس فيها شئ ينافي العقل أو يعارضه ، على هذا قامت الأدلة العقلية والنقلية ، وعليه أجمع العلماء في كل العصور ، حتى إن الإمام ابن تيمية رحمه الله ألف كتابا ضخما موسعا في هذا الموضوع وحده سماه « درء تعارض العقل والنقل » أو : « الجمع بين العقل والنقل » . أما الأدلة العقلية على عدم تعارض النقل « نصوص الشريعة » مع العقل فنذكر منها : أولا : أن النقل « نصوص الشريعة » من عند الله سبحانه ، وكلها تستهدف مصلحة الإنسان في دنياه وآخرته - كما قامت على ذلك الأدلة والبراهين . والعقل جعله الله مناط التكليف عند الإنسان ، ومن المحال أن يتعارض شرع الله وما يطلبه من الناس مع العقل الذي هو مناط التكليف ، إذ كيف يكلف الله العقل بما لا يسوغ ؟ . ثانيا : أن أحدا من القدامى أو المحدثين لم يستطيع أن يقدم دليلا مقبولا على تعارض النقل « الشرع » مع العقل ، وكل من ادعى هذه الدعوى وقدم عليها بعض الأدلة ، لم تستطع أدلته أن تثبت أمام الحق ، ولا أن تثبت هذه الدعوى ، وإنما انهارت تماما عند التأمل والحوار. ثالثا : أن التاريخ الإسلامي حافل دائما بالمصالحة والموادة والمصافاة بين النقل"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0185.png"}, {"n": 186, "paras": ["والعقل ، أى بين متطلبات الشرع في العقيدة والعبادة والمعاملة والآداب ، ومتطلبات العقل وقدراته وإمكاناته . رابعا : أن الجمع بين النقل والعقل في أى قضية تطرح على أى مستوى من مستويات العقيدة أو العبادة أو المعاملة أو الخلق والسلوك سهل ميسور لكل من يحاوله ، فلا تعارض ولا تضاد. وأما الأدلة الشرعية - النصوص - فهي لا تنافى العقل أبدا أو تعارضه ، ولو نافته أو عارضته - والعقل مناط التكليف كما ذكرنا - لكان في ذلك مشقة على العباد وحرج لهم في الدين ، والله تبارك وتعالى يقول : ﴿ وما جعل عليكم في الدين من حرج ﴾(١). ولتوضيح ذلك نقول : إن الدليل أو الحكم إما عقلى وإما عادى وإما شرعى ، ولا تعارض بينها بحال ، وبخاصة في أدلة الشرع القطعية لا الظنية ، وبيان ذلك: أن الحكم العقلى معترف به في الإسلام ضرورة أن العقل مناط التكليف وأن الله سبحانه قد أمر الإنسان بالتفكر والتأمل والتدبر والنظر في الكون ، وكل ذلك لا يتوصل إليه إلا بالعقل ، وهو : « إثبات أمر لأمر أو نفيه عنه من غير توقف على تكرار أو وضع واضع » فكان الحكم العقلى واردا معترفا به . والحكم العادى معترف به كذلك في الإسلام بدليل أن الله تبارك وتعالى طالب الإنسان بالنظر والملاحظة لنفسه وللكون وما فيه كدليل لعقله ، وإنما يتوصل إلى ذلك بالمشاهدة والتجربة ، وهو : « إثبات الربط بين أمر وأمر وجودا وعدما بوساطة تكرار أو وضع واضع » فكان الحكم أو الدليل العادى واردا كذلك ومعترفا به. والحكم أو الدليلى الشرعى هو الذى قامت عليه التكاليف كلها ، ويتوصل", "(١) سورة الحج : ٧٨."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0186.png"}, {"n": 187, "paras": ["إليه بالشرع ، وهو : « خطاب الشارع المتعلق بأفعال المكلفين طلبا أو تخييرا أو وضعا » . والأحكام الشرعية نابعة من الكتاب والسنة ، والكتاب الكريم كله متواتر والسنة منها المتواتر لفظا والمتواتر معنى ، ومنها غير المتواتر ، وغير المتواتر من السنة إما صحيح وإما حسن وإما ضعيف . والخلاف بين علماء المسلمين في الحسن والضعيف من السنة غير المتواترة. ومن هنا كانت أحكام الشريعة على أنواع : الأول : أحكام معلومة من الدين بالضرورة ، وهي التي لا خلاف فيها بين الأئمة لأن النصوص فيها قطعية الثبوت قطعية الدلالة . والثاني : أحكام مجمع عليها ولكنها ليست من المعلوم من الدين بالضرورة . والثالث : أحكام اختلف فيها المجتهدون . ونستطيع أن نلخص عدم تعارض العقل مع الشرع في نقاط نرجو أن تكون مستوعبة لأبعاد هذه القضية هي : أولا : لا تعارض أصلا بين العقل والأدلة الشرعية القطعية للأسباب التي قدمناها آنفا، فإن بدا هناك تعارض بين العقل بأدلته حتى لو كانت قطعية - وهذا محال - والأدلة الشرعية القطعية - وهذا أيضا من المستحيل - صرف النظر عن أدلة العقل واتهم بها حال بينه وبين الحق من أسباب ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0187.png"}, {"n": 188, "paras": ["ثانيا : إذا احتمل النص الشرعي الظني عدة وجوه ، وكان أحد هذه الوجوه يوهم تعارضه مع العقل ، حاولنا أولا التوفيق بين العقل والنقل بالتأول ، فإن لم تستطع أن نوفق بينهما ، فإن كان دليل العقل قطعي الثبوت أخذنا به وإن كان ظني الثبوت أخذنا بالدليل الشرعي وأهملنا الدليل العقلي . ثالثا : الأصل أن نعرض أدلة العقل لمزيد من المراجعة والتدقيق حتى نستيقن من قطعيتها أو ظنيتها ، ويظل الباب مفتوحا حتى يثبت الدليل العقلي أو ينهار . وبعد : فتلك هي الصورة المجملة لهذا الأصل العظيم من أصول فهم الإسلام كما أشار إليه الإمام المؤسس رحمه الله ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0188.png"}, {"n": 189, "paras": ["الأصل العشرون من أصول الفهم", "« لا نكفر مسلما أقر بالشهادتين وعمل بمقتضاهما ، وأدى الفرائض ، برأى أو معصية ، إلا إن أقر بكلمة الكفر ، أو أنكر معلوما من الدين بالضرورة أو كذب صريح القرآن أو فسره على وجه لا تحتمله أساليب اللغة العربية بحال ، أو عمل عملا لا يحتمل تأويلا غير الكفر » ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0189.png"}, {"n": 190, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0190.png"}, {"n": 191, "paras": ["حكم تكفير المسلم : يدقق الإمام المؤسس في قضية تكفير المسلم الذي أقر بالشهادتين : « لا إله إلا الله ، محمد رسول الله » لأن الحكم بكفر مسلم عمل خطير قد يبوء به - والعياذ بالله - من أطلقه على من لا يستحقه . ومن أجل ذلك جاء هذا التدقيق . ولابد أن نحدد أن الحكم بتكفير مسلم - شهد أن لا إله إلا الله محمدا رسول الله وعمل بمقتضى الشهادتين - أى وحد الله وعبده وآمن بكتبه ورسله وملائكته واليوم الآخر والقضاء والقدر ، وأدى الفرائض ، لا يجوز لأحد من المسلمين أن يحكم عليه بالكفر ، كما لا يجوز لأحد أن يكفره حتى لو تبنى رأيا شاذا يخالف ما يراه المسلمون ، أو ارتكبت بعض المعاصي التي نهى الله عنها ، لأنه مع هذا الرأى الشاذ وتلك المعصية لا يزال مؤمنا مسلما وإن عد من العصاة. لكن ليس معنى ذلك أنه لا يحكم على أحد من المسلمين بالكفر بحال ، ما دام قد أقر بالشهادتين وأدى الفرائض ، وإنما يمكن الحكم على أحد المسلمين بالكفر إذا أتى عملا من الأعمال التالية :", "١ - أن يقر بكلمة الكفر مختارا غير مكره ، ولا غائب العقل بأن يقول عن نفسه : إنه كافر بدين الإسلام ، أو أى كلمة تؤدى هذا المعنى وقد رأى جمهور علماء المسلمين أن مما يؤدى معنى الكفر مايلى : أ - إنكار وجود الله تبارك وتعالى ، أو وصفه بما لا يليق بجلاله أو تسميته بغير مما سمى به نفسه ، مما لا يليق بجلاله سبحانه وتعالى . ب - وإنكار نبوة محمد ﷺ ، أو اتهامه بالكذب فيما أخبر به عن ربه ، أو اتهامه بأنه وضع القرآن الكريم من عند نفسه دون أن يوحيه إليه ربه ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0191.png"}, {"n": 192, "paras": ["ج- وإهانة الرسول ﷺ بأي صورة من صور الإهانة ، أو إهانة الدين الذي جاء به عند الله سبحانه وتعالى .", "٢- وأن ينكر معلوما من الدين بالضرورة ، والمعلوم من الدين بالضرورة كثير، ولذلك وضع العلماء له ضوابط على النحو التالي : أ- إنكار فريضة مما فرض الله على عباده ، ب- وإنكار القرآن الكريم كله أو بعضه ، ج- وإنكار السنة النبوية الصحيحة ، د- وإنكار تحريم ما حرم الله على عباده ، كإنكار تحريم الله للزنا والخمر وأكل الربا وقتل النفس ، وغيرها مما هو معروف أنه مما حرم الله ،", "٣- وأن يُكذّب صريح القرآن الكريم ، بأن ينفى شيئا قرره القرآن الكريم صراحة لا تحتمل تأويلا ، فضلا عن تكذيبه القرآن الكريم كله ، كأن يكذب - على سبيل المثال : أن الله يحب المحسنين ، أو أنه لا يحب المسرفين ، أو أنه وعد المؤمنين بالنصر ، أو أنه سيعذب الكافرين يوم القيامة ... الخ.", "٤- وأن يفسر القرآن الكريم أو بعضه تفسيرا لا تحتمله أساليب اللغة العربية بحال من الأحوال ، لأن القرآن نزل باللغة العربية ، واللغة العربية لها قواعدها وأصولها ووسائلها وأساليبها المتعددة . فمن خالف ذلك ففسر القرآن الكريم أو بعضه تفسيرا لا تحتمله أساليب العربية بحال ، فقد أتى عملا يستحق به أن يوصف بالكفر."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0192.png"}, {"n": 193, "paras": ["ه- وأن يقوم بعمل لا يحتمل تأويلا غير الكفر ، وضربوا لذلك بعض الأمثال كالتالي : أ- أن يحمل صليبا لغير خدعة حرب . ب- وأن يسجد لصنم أو وثن غير مُكره ولا غائب العقل .", "وبعد : فهذا هو شرح الأصل العشرين من أصول فهم الإسلام فهما صحيحا لا تشوبه شائبة جهل أو وهم ، وقد جعل الإمام البنا هذه الأصول العشرين تمثل الركن الأول من أركان البيعة العشرة أو أصول فهم الإسلام . وطالب كل واحد من الإخوان الصادقين بأن يحقق هذه الأصول لفهم الدين ."], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0193.png"}, {"n": 194, "paras": ["خاتمة", "في ختام هذا الشرح الوجيز لأصول فهم الإسلام ، كما جاءت على لسان الإمام المؤسس رحمه الله - أرجو أن أؤكد بعض الحقائق التي يمكن أن نستنبطها من هذا الركن من أركان البيعة العشرة وهو الفهم ، تلك الحقائق فيما بدا لي - والله سبحانه أعلم - هي :", "أولا : أن دين الإسلام منهج إصلاح متكامل للإنسان في معاشه ومعاده ، وأنه منهج قد جرب فنجح في إصلاح الإنسان والحياة الإنسانية فترات قصيرة من عمر الزمان .", "ثانيا : أن إصلاح الحياة الإنسانية عن طريق الإسلام بكماله وتمامه منهج يحتاج في تطبيقه إلى أركان هي : الفهم للإسلام والإخلاص لله والعمل من أجل الإسلام والجهاد في سبيل الله لتكون كلمة الله هي العليا والتضحية بالجهد والوقت والمال ، والطاعة لله ولرسوله ولأئمة المسلمين وقادتهم في غير معصية ، والثبات على الحق وعلى دعوة الله مهما كانت العقبات والعراقيل ، والتجرد من كل الدعوات والانتماءات غير دعوة الله والانتماء لهذا الدين العظيم ، والتآخي في الله أثناء السير في طريق الحق والثقة بين القائد والجندى .", "ثالثا : أن أبرز الأركان العشرة وأولاها بأن يكون القاعدة والأساس هو الفهم أى فهم الإسلام في ضوء هذه الأصول العشرين التي جمع فيها الإمام المؤسس كل ما يحتاج إليه المسلم ليمارس الإصلاح وقد صحت عقيدته وسلمت عبادته ورشدت أقواله وأعماله وعاداته .", "رابعا : أن تلك الشمولية والإحاطة التي نظر بها الإمام البنا في ركن الفهم إنما نبعت لديه من فقهه العميق للكتاب والسنة ، ومن حرصه الشديد على الإصلاح والتجديد لأمر هذا الدين وإعداده الرجال القادرين على حمل أعباء"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0194.png"}, {"n": 195, "paras": ["الإصلاح . خامسا : أن ما قدمته رسالة التعاليم أو هذه الأركان العشرة للإصلاح الإسلامي - التي شرحنا واحدا منها في هذا الكتاب - هو الحل لمشكلات الحياة الإنسانية بعامة ومشكلات المجتمعات الإسلامية التي تعيش فرقة وضياعا وتراجعا حضاريا بصفة خاصة . والله من وراء القصد وهو الهادي إلى سواء السبيل ،،،"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0195.png"}, {"n": 196, "paras": ["ثبت الموضوعات الإهداء ٣ بين يدى الكتاب ٥ أسباب تفرق المسلمين وتراجعهم الحضاري اليوم ٧ المخرج من هذه الفرقة والضياع ٩ مناهج المصلحين المسلمين في الإصلاح ١٠ منهج الإمام البنا في الإصلاح ١٣ أصول فهم الإسلام في رسالة التعاليم ١٧ أركان البيعة ٢٠ معنى الأركان ٢١ معنى البيعة ٢٢ الركن الأول - الفهم وهو وحده موضوع هذا الكتاب ٢٥ الأصل الأول من أصول الفهم ٢٧", "١ - الإسلام دولة ووطن أو حكومة وأمة ٢٨ أ - الإسلام دولة ووطن ٢٨ ب - الإسلام حكومة وأمة ٢٩", "٢ - الإسلام خلق وقوة أو رحمة وعدالة ٣٠ أ - الإسلام خلق وقوة ٣١ ب - الإسلام رحمة وعدالة ٣٣", "٣ - الإسلام ثقافة وقانون أو علم وقضاء ٣٥ أ - الإسلام ثقافة وقانون ٣٥ ب - الإسلام علم وقضاء ٣٦", "٤ - الإسلام مادة وثروة أو كسب وغنى ٣٨"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0196.png"}, {"n": 197, "paras": ["أ- الإسلام مادة وثروة ٣٨ ب- الإسلام كسب وغنى ٤٠", "٥- الإسلام جهاد ودعوة أو جيش وفكرة ٤٢ أ- الإسلام جهاد ودعوة ٤٢ ب- الإسلام جيش وفكرة ٤٥", "٦- الإسلام عقيدة صادقة وعبادة صحيحة سواء بسواء ٤٧ أ- الإسلام عقيدة صادقة ٤٧ ب- الإسلام عبادة صحيحة ٤٨ الأصل الثاني : من أصول الفهم ٥١ أ- تعرف أحكام الإسلام ٥٣ ب- حجية القرآن الكريم ٥٤ ج- حجية السنة النبوية ٥٧ الأصل الثالث : من أصول الفهم ٥٩ نور الإيمان الصادق ٦١ ما لا يتخذ دليلا شرعيا ٦٢ أ- الإلهام ٦٣ ب- الخواطر ٦٤ ج- الكشف ٦٤ د- الرؤى ٦٥ الأصل الرابع : من أصول الفهم ٦٩ المنكرات التي يجب محاربتها ٧١ أ- التمائم ٧١ ب- الرقى ٧٢ ج- الودع ٧٤"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0197.png"}, {"n": 198, "paras": ["د- الرمل ٧٤ ه- المعرفة أو كلام العراف ٧٤ و- الكهانة ٧٥ الأصل الخامس : من أصول الفهم ٧٧ أ- الاجتهاد ٧٩ ب- موقف المسلمين من العبادات والعادات ٨٢ الأصل السادس : من أصول الفهم ٨٣ أ- العصمة من الخطأ ٨٥ ب- حرمة تجريح المسلم ٨٦ الأصل السابع : من أصول الفهم ٨٧ أ- الاتباع ٨٩ ب- واجبات الاتباع ٩٠ ج- بلوغ درجة النظر ٩٠ الأصل الثامن : من أصول الفهم ٩٣ أ- أنواع الاختلاف ٩٥ ب- أدب الاختلاف ٩٨ الأصل التاسع : من أصول الفهم ١٠١ أ- الخوض في مسائل لا ينبنى عليها عمل ١٠٣ ب- الخوض في معانى القرآن التي لم يصل إليها العلم بعد ١٠٧ ج- الخوض في المفاضلة بين الأصحاب ١٠٨ الأصل العاشر : من أصول الفهم ١١١ أ- الطريق الصحيح إلى معرفة الله ١١٤ ب- أبرز قضايا التوحيد ١١٥ النقطة الأولى - الكلام في صفات الله ١١٥"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0198.png"}, {"n": 199, "paras": ["الثانية - توحيد الربوبية ١١٧ الثالثة - توحيد الألوهية ١١٨ الأصل الحادي عشر : من أصول الفهم ١٢١ أ- تعريف البدعة ١٢٣ ب- تقسيم البدعة ١٢٣ الأصل الثاني عشر : من أصول الفهم ١٢٧ أ- الحكم التكليفي للبدعة في العقيدة والعبادة والعادة ١٢٩ ب- حكم البدعة الإضافية والبدعة التركية ١٣١ الأصل الثالث عشر : من أصول الفهم ١٣٣ أ- من هم الأولياء ١٣٥ ب- ما الكرامات التي تثبت لهم شرعا ؟ ١٣٧ ج- ما موقف المسلمين من هؤلاء الأولياء ؟ ١٤٠ الأصل الرابع عشر : من أصول الفهم ١٤٣ أ- مشروعية زيارة القبور ١٤٥ ب- أهم الأعمال المحرمة بالنسبة للقبور ١٤٧ الأصل الخامس عشر : من أصول الفهم ١٥١ أ- الدعاء ١٥٣ ب- التوسل ١٥٤ الأصل السادس عشر : من أصول الفهم ١٥٩ أ- العرف الخاطئ ١٦١ ب- الخداع اللفظي ١٦٣ الأصل السابع عشر : من أصول الفهم ١٦٥ أ- العقيدة أساس العمل ١٦٧ ب- الأعمال .. بين القلوب والجوارح ١٦٩"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0199.png"}, {"n": 200, "paras": ["الأصل الثامن عشر : من أصول الفهم … ١٧٣ أ- تحرير الإسلام للعقل … ١٧٥ ب- الدعوة إلى النظر في الكون … ١٧٧ ج- تقدير الإسلام للعلم … ١٠٨ الأصل التاسع عشر : من أصول الفهم … ١٨٣ لا تعارض بين العقل والنقل … ١٨٥ الأصل العشرون : من أصول الفهم … ١٨٩ حكم تكفير المسلم … ١٩١ خاتمة … ١٩٥ ثبت الموضوعات … ١٩٧", "مطابع دار الطباعة والنشر الإسلامية مدينة العاشر من رمضان المنطقة الصناعية ب ٢ ت : ٣٦٢٣١٣ مكتب القاهرة : مدينة نصر ١٢ ش ابن هانىء الأندلسي ت : ٦١٨١٣٧"], "img": "../../../_ocr-work/libocr/sharh-fahm-mahmud/pages/0200.png"}]};
